nted$)"},"$:/plugins/rimir/outline/language/block/delete-children":{"title":"$:/plugins/rimir/outline/language/block/delete-children","text":"Yes, with its sub-items ($counted$)"},"$:/plugins/rimir/outline/language/block/delete-container":{"title":"$:/plugins/rimir/outline/language/block/delete-container","text":"Yes, with its contents ($counted$)"},"$:/plugins/rimir/outline/language/block/delete-own":{"title":"$:/plugins/rimir/outline/language/block/delete-own","text":"Just the heading"},"$:/plugins/rimir/outline/language/block/delete-range":{"title":"$:/plugins/rimir/outline/language/block/delete-range","text":"Yes, the selected blocks ($counted$)"},"$:/plugins/rimir/outline/language/block/cancel":{"title":"$:/plugins/rimir/outline/language/block/cancel","text":"Cancel (Esc)"},"$:/plugins/rimir/outline/language/block/count-blocks":{"title":"$:/plugins/rimir/outline/language/block/count-blocks","text":"$count$ blocks"},"$:/plugins/rimir/outline/language/block/count-blocks-one":{"title":"$:/plugins/rimir/outline/language/block/count-blocks-one","text":"1 block"},"$:/plugins/rimir/outline/language/block/count-items":{"title":"$:/plugins/rimir/outline/language/block/count-items","text":"$count$ items"},"$:/plugins/rimir/outline/language/block/count-items-one":{"title":"$:/plugins/rimir/outline/language/block/count-items-one","text":"1 item"},"$:/plugins/rimir/outline/language/block/count-sub-items":{"title":"$:/plugins/rimir/outline/language/block/count-sub-items","text":"$count$ sub-items"},"$:/plugins/rimir/outline/language/block/count-sub-items-one":{"title":"$:/plugins/rimir/outline/language/block/count-sub-items-one","text":"1 sub-item"},"$:/plugins/rimir/outline/model.js":{"title":"$:/plugins/rimir/outline/model.js","text":"/*\
title: $:/plugins/rimir/outline/model.js
type: application/javascript
module-type: library

Builds the outline unit model of a wikitext text from TiddlyWiki's parse tree.

buildModel(wiki, text, title) -> {text, units, roots}
Each unit: {id, kind, start, end, subtreeEnd, level, marker, parent, children, tag, target}.
`title` (optional) is the tiddler the text belongs to: a transclusion of it is a widget, not a transclusion.

\*/
"use strict";

// Pragma rules: their nodes wrap the rest of the tree and are never units
var PRAGMA_RULES = {
	macrodef: true, procedure: true, fnprocdef: true, "function": true, import: true,
	importvariables: true, whitespace: true, rules: true, parameters: true, set: true
};
var LIST_TAGS = {ul: true, ol: true, dl: true, blockquote: true};
var ITEM_TAGS = {li: true, dt: true, dd: true, div: true};
var HEADING_RE = /^h([1-6])$/;
var MARKER_CHARS = "*#;:>";

// List marker characters (an item's marker is a run of them)
exports.MARKER_CHARS = MARKER_CHARS;

function literal(node, name) {
	var attr = node.attributes && node.attributes[name];
	return attr && attr.type === "string" ? attr.value : null;
}

exports.buildModel = function(wiki, text, title) {
	text = text || "";
	var units = [], roots = [];

	// Own range end without trailing line breaks (some rules include the newline)
	function trimEnd(start, end) {
		end = Math.min(end, text.length);
		while(end > start && (text.charAt(end - 1) === "\n" || text.charAt(end - 1) === "\r")) {
			end--;
		}
		return end;
	}

	function addUnit(node, kind, parent, extra) {
		var start = node.start,
			end = trimEnd(start, node.end),
			unit = {
				id: units.length,
				kind: kind,
				start: start,
				end: end,
				subtreeEnd: end,
				level: 0,
				marker: "",
				parent: parent,
				children: [],
				tag: node.type === "element" ? node.tag : node.type,
				target: null
			};
		$tw.utils.extend(unit, extra || {});
		units.push(unit);
		if(parent === -1) {
			roots.push(unit.id);
		} else {
			units[parent].children.push(unit.id);
		}
		return unit;
	}

	// Widen subtreeEnd of a unit and its ancestors
	function extend(unit, end) {
		while(unit && unit.subtreeEnd < end) {
			unit.subtreeEnd = end;
			unit = unit.parent === -1 ? null : units[unit.parent];
		}
	}

	function hasPosition(node) {
		return typeof node.start === "number" && typeof node.end === "number";
	}

	// Items of a list node (ul/ol/dl/blockquote), as children of `parent`
	function walkItems(listNode, parent) {
		$tw.utils.each(listNode.children || [], function(itemNode) {
			if(itemNode.type !== "element" || !ITEM_TAGS[itemNode.tag] || !hasPosition(itemNode)) {
				return;
			}
			var children = itemNode.children || [],
				first = children[0];
			// Skipped levels ("* a\n*** c") produce a synthetic item that only holds the deeper list
			// and starts where it starts: it is not a unit, its items go to `parent`
			if(first && first.type === "element" && LIST_TAGS[first.tag] && first.start === itemNode.start) {
				$tw.utils.each(children, function(child) {
					if(isNestedList(child)) {
						walkItems(child, parent);
					}
				});
				return;
			}
			var pos = itemNode.start;
			while(pos < text.length && MARKER_CHARS.indexOf(text.charAt(pos)) !== -1) {
				pos++;
			}
			var marker = text.substring(itemNode.start, pos),
				item = addUnit(itemNode, "item", parent, {level: marker.length, marker: marker});
			extend(units[parent], item.end);
			$tw.utils.each(children, function(child) {
				if(isNestedList(child)) {
					walkItems(child, item.id);
				}
			});
		});
	}

	function isNestedList(node) {
		return node.type === "element" && LIST_TAGS[node.tag] && node.rule === undefined;
	}

	// Block-level nodes of one container (root or opened HTML element).
	// `ctx` = {parent: container unit id or -1, headings: stack of open heading units}
	function walkBlocks(nodes, ctx) {
		$tw.utils.each(nodes || [], function(node) {
			walkBlock(node, ctx);
		});
	}

	function currentParent(ctx) {
		return ctx.headings.length ? ctx.headings[ctx.headings.length - 1].id : ctx.parent;
	}

	function walkBlock(node, ctx) {
		if(node.rule && PRAGMA_RULES[node.rule]) {
			walkBlocks(node.children, ctx);
			return;
		}
		if(!hasPosition(node)) {
			// Unpositioned wrapper: step through
			if(node.type !== "text") {
				walkBlocks(node.children, ctx);
			}
			return;
		}
		if(node.type === "text") {
			return;
		}
		if(node.rule === "commentblock") {
			// Comments render nothing. At the top of the text (pragma position) they wrap the rest
			walkBlocks(node.children, ctx);
			return;
		}
		var unit, m;
		if(node.type === "element" && (m = HEADING_RE.exec(node.tag)) && node.rule === "heading") {
			var level = parseInt(m[1], 10);
			while(ctx.headings.length && ctx.headings[ctx.headings.length - 1].level >= level) {
				ctx.headings.pop();
			}
			unit = addUnit(node, "heading", currentParent(ctx), {level: level});
			ctx.headings.push(unit);
			extendParent(unit);
			return;
		}
		var parent = currentParent(ctx);
		if(node.type === "element" && node.rule === "list" && LIST_TAGS[node.tag]) {
			unit = addUnit(node, "list", parent);
			extendParent(unit);
			walkItems(node, unit.id);
			// The list node ends at its last top-level item, without that item's nested items:
			// the list's own range is its full extent
			unit.end = unit.subtreeEnd;
			extendParent(unit);
			return;
		}
		if(node.type === "element" && node.isBlock && node.rule === "html") {
			unit = addUnit(node, "container", parent);
			var before = units.length;
			walkBlocks(node.children, {parent: unit.id, headings: []});
			if(units.length === before) {
				unit.kind = "block";
			}
			extendParent(unit);
			return;
		}
		if(node.type === "element" || node.type === "codeblock" || node.type === "void") {
			if(node.rule === "typedblock") {
				// The typedblock rule starts the node after its "$$$type" header line
				var lineStart = text.lastIndexOf("\n", node.start - 2) + 1;
				if(text.substr(lineStart, 3) === "$$$") {
					node = $tw.utils.extend({}, node, {start: lineStart});
				}
			}
			unit = addUnit(node, "block", parent);
			extendParent(unit);
			return;
		}
		var target = null;
		if(node.type === "tiddler" && node.rule === "transcludeblock") {
			target = literal(node, "tiddler");
		} else if(node.type === "transclude" && !(node.attributes && node.attributes.$variable)) {
			target = literal(node, "$tiddler");
			if(target === null && !(node.attributes && node.attributes.$tiddler)) {
				target = literal(node, "tiddler");
			}
		}
		if(target && target !== title) {
			unit = addUnit(node, "transclusion", parent, {target: target});
		} else {
			unit = addUnit(node, "widget", parent);
		}
		extendParent(unit);
	}

	function extendParent(unit) {
		if(unit.parent !== -1) {
			extend(units[unit.parent], unit.subtreeEnd);
		}
	}

	var tree = wiki.parseText("text/vnd.tiddlywiki", text).tree;
	walkBlocks(tree, {parent: -1, headings: []});
	return {text: text, units: units, roots: roots};
};

/*
Id of the unit that starts at `start`, preferring `kind` (a list and its first item share a start);
-1 if none. accept(id) optionally restricts the candidates (e.g. to units with DOM nodes).
*/
exports.findUnit = function(model, start, kind, accept) {
	var match = -1;
	for(var i = 0; i < model.units.length; i++) {
		var u = model.units[i];
		if(u.start === start && (!accept || accept(u.id))) {
			if(!kind || u.kind === kind) {
				return u.id;
			}
			if(match === -1) {
				match = u.id;
			}
		}
	}
	return match;
};

/*
Post-operation guard: true when `newText` has the units a structural operation `name` on unit `id` of model
`before` must leave. Moves keep the unit count and the kinds and levels (as a multiset: the order changes).
Indent/promote keep the unit count and order; the units of the operated subtree (of the unit's kind) change
their level by exactly +1/-1, all others keep it. Delete, merge, split and externalize remove exactly the units
result.removed (ids) and add exactly result.added ({kind, level}), keeping all others with their kinds and levels
(`result`: the adapter's result). Anything else is refused by the caller (no write).
*/
exports.checkOp = function(wiki, before, id, name, newText, title, result) {
	// The adapter's convert checks its own result (a conversion changes kinds and the unit count)
	if(name === "convert") {
		return true;
	}
	var after = exports.buildModel(wiki, newText, title),
		u = before.units[id];
	function signature(units) {
		return units.map(function(x) { return x.kind + ":" + x.level; }).sort().join(",");
	}
	if(name === "deleteUnit" || name === "merge" || name === "split" || name === "externalize") {
		var removed = (result && result.removed) || [],
			added = (result && result.added) || [];
		return !!u && !!result && (removed.length || added.length) > 0 && signature(after.units) ===
			signature(before.units.filter(function(x) { return removed.indexOf(x.id) === -1; }).concat(added));
	}
	if(!u || after.units.length !== before.units.length) {
		return false;
	}
	if(name === "move") {
		return signature(after.units) === signature(before.units);
	}

	if(name !== "indent" && name !== "promote") {
		return false;
	}
	var delta = name === "indent" ? 1 : -1;
	for(var i = 0; i < before.units.length; i++) {
		var a = before.units[i], b = after.units[i],
			affected = a.kind === u.kind && a.start >= u.start && a.start < u.subtreeEnd;
		if(a.kind !== b.kind || b.level !== a.level + (affected ? delta : 0)) {
			return false;
		}
	}
	return true;
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/outline/outline-clipboard.js":{"title":"$:/plugins/rimir/outline/outline-clipboard.js","text":"/*\
title: $:/plugins/rimir/outline/outline-clipboard.js
type: application/javascript
module-type: library

Copy, cut and paste of the selected unit through the system clipboard: the browser's copy, cut and paste events on
the focused outline (Ctrl-C / Ctrl-X / Ctrl-V, Cmd on Mac, the Edit and context menus). install(proto) adds these
methods to the widget prototype:
  handleCopy(event)  - the selected unit with its subtree to the clipboard; a short flash shows it
  handleCut(event)   - copy, then delete it with its subtree, without asking (Ctrl-Z brings it back)
  handlePaste(event) - insert the clipboard after the selected unit (a tiddler without units: at the end), its levels
                       adapted to the place (adapter paste), and select it

A copy writes three formats: text/html (the unit's source rendered, links to tiddlers as their text, for e-mail and
the like), text/plain (the wikitext source; items of both moved to level 1) and CLIP_TYPE (JSON {kind, source}, see
the adapter's copy). A paste takes CLIP_TYPE, else the plain text as wikitext (adapter clipKind); outside HTML is not
converted.
The events are left to the browser while text is marked, while the focus is not on the outline itself (the editor), and
without a selection. Read-only wikis: copy only. An open editor in this view: cut and paste do nothing.

\*/
"use strict";

var buildModel = require("$:/plugins/rimir/outline/model.js").buildModel,
	dom = require("$:/plugins/rimir/outline/dom-utils.js");

var CLIP_TYPE = "application/x-rimir-outline",
	COPIED_CLASS = "rr-ol-copied",
	FLASH_MS = 600;

exports.CLIP_TYPE = CLIP_TYPE;

var methods = {};

// True while text is marked with the mouse: the browser copies that text as usual
methods.hasTextSelection = function() {
	var view = this.document.defaultView,
		selection = view && view.getSelection ? view.getSelection() : null;
	return !!selection && !selection.isCollapsed && String(selection).length > 0;
};

// Whether a clipboard event is the outline's: the outline itself has the focus (not its editor; the event's target is
// where the caret of the last click is), a unit selected (paste: or no units at all)
methods.ownsClipboardEvent = function(event, paste) {
	return this.awake && this.document.activeElement === this.domNode && !!event.clipboardData && !this.hasTextSelection() &&
		(this.selectedId !== -1 || (paste && !this.hasSelectable()));
};

// The clip of the selected unit ({kind, source}) or null
methods.selectedClip = function() {
	var adapter = this.getAdapter();
	if(!adapter || !adapter.copy || !this.ensureCurrent()) {
		return null;
	}
	var ids = this.rangeIds();
	return ids.length > 1 && adapter.rangeClip ? adapter.rangeClip(this.model.text, this.model, ids) :
		adapter.copy(this.model.text, this.model, this.selectedId);
};

// `source` rendered as HTML in this outline's context, links to tiddlers replaced by their text, no classes
methods.clipHtml = function(source) {
	var parser = this.wiki.parseText("text/vnd.tiddlywiki", source, {parseAsInline: false}),
		container = this.document.createElement("div"),
		widget = this.wiki.makeWidget(parser, {document: this.document, parentWidget: this});
	widget.render(container, null);
	$tw.utils.each(Array.prototype.slice.call(container.querySelectorAll("a.tc-tiddlylink")), function(link) {
		link.parentNode.replaceChild(link.ownerDocument.createTextNode(link.textContent), link);
	});
	$tw.utils.each(Array.prototype.slice.call(container.querySelectorAll("[class]")), function(node) {
		node.removeAttribute("class");
	});
	return container.innerHTML;
};

/*
Source of `clip` for outside: items at level 1, the way they paste into an empty tiddler (a sub-item copied alone
would otherwise render inside empty outer list items). Anything else as it is.
*/
methods.outsideSource = function(clip) {
	var adapter = this.getAdapter();
	if(clip.kind !== "items" || !adapter.paste) {
		return clip.source;
	}
	var result = adapter.paste("", buildModel(this.wiki, "", this.tiddlerTitle), -1, clip,
		buildModel(this.wiki, clip.source, this.tiddlerTitle));
	return result ? result.text : clip.source;
};

// Write the selected unit to the clipboard of `event`; false without a clip
methods.writeClip = function(event) {
	var clip = this.selectedClip();
	if(!clip) {
		return false;
	}
	var source = this.outsideSource(clip);
	event.clipboardData.setData("text/plain", source);
	event.clipboardData.setData("text/html", this.clipHtml(source));
	event.clipboardData.setData(CLIP_TYPE, JSON.stringify(clip));
	this.flashUnits(this.rangeIds());
	return true;
};

/*
The outline a clipboard event is for: this one when it owns it, else the outline of its overlay (or one inside that)
when that one has the focus. The browser sends copy/cut/paste to where the page's caret is, which can still be in
this outline's text while its overlay has the keyboard focus. Null when none (or the event was handled already).
*/
methods.clipboardOutline = function(event, paste) {
	if(event.defaultPrevented) {
		return null;
	}
	if(this.ownsClipboardEvent(event, paste)) {
		return this;
	}
	return this.overlay && this.overlay.outline ? this.overlay.outline.clipboardOutline(event, paste) : null;
};

methods.handleCopy = function(event) {
	var w = this.clipboardOutline(event);
	if(w) {
		w.writeClip(event);
		event.preventDefault();
	}
};

// A short highlight of units `ids` with their subtrees (a heading: its whole section; CSS class, removed after FLASH_MS)
methods.flashUnits = function(ids) {
	var model = this.model,
		spans = ids.map(function(id) { return model && model.units[id]; }).filter(Boolean),
		nodes = [];
	$tw.utils.each(this.units, function(entry) {
		var x = entry.unit;
		if(spans.some(function(u) { return x.start >= u.start && x.start < u.subtreeEnd; })) {
			nodes.push.apply(nodes, entry.domNodes);
		}
	});
	// Nodes inside another flashed node (sub-items in their item) get it from there
	nodes = nodes.filter(function(node) {
		return !nodes.some(function(other) { return other !== node && dom.isInside(node, other); });
	});
	$tw.utils.each(nodes, function(node) {
		dom.setClass(node, COPIED_CLASS, true);
	});
	setTimeout(function() {
		$tw.utils.each(nodes, function(node) {
			dom.setClass(node, COPIED_CLASS, false);
		});
	}, FLASH_MS);
};

// Copy, then delete like Delete's first entry, without asking; one write (one undo step)
methods.handleCut = function(event) {
	var w = this.clipboardOutline(event);
	if(!w) {
		return;
	}
	event.preventDefault();
	if(!w.isReadOnly() && !w.editor && w.writeClip(event)) {
		w.operate("deleteUnit");
	}
};

// The clip on the clipboard of `event`: the outline's own format, else the plain text as wikitext; or null
methods.readClip = function(event, adapter) {
	var data = event.clipboardData, clip = null;
	try {
		clip = JSON.parse(data.getData(CLIP_TYPE) || "null");
	} catch(e) {
		clip = null;
	}
	if(!clip || typeof clip.source !== "string") {
		var text = (data.getData("text/plain") || "").replace(/^(\s*\n)+/, "").replace(/\s+$/, "");
		clip = text && adapter.clipKind ? {source: text} : null;
	}
	if(!clip || !/\S/.test(clip.source)) {
		return null;
	}
	clip.model = buildModel(this.wiki, clip.source, this.tiddlerTitle);
	clip.kind = clip.kind || adapter.clipKind(clip.model);
	return clip;
};

// Paste after the selected unit (a range: after its last unit), or at the end of a tiddler without units
methods.handlePaste = function(event) {
	var w = this.clipboardOutline(event, true);
	if(w && w !== this) {
		w.handlePaste(event);
		return;
	}
	var adapter = this.getAdapter();
	if(!w || !adapter || !adapter.paste) {
		return;
	}
	// Not also imported as tiddlers by a dropzone around the outline (it does not check defaultPrevented)
	event.preventDefault();
	event.stopPropagation();
	var clip = this.readClip(event, adapter);
	if(!clip || this.isReadOnly() || this.editor || !this.ensureCurrent()) {
		return;
	}
	var tiddler = this.wiki.getTiddler(this.tiddlerTitle);
	if(!tiddler) {
		return;
	}
	var ids = this.rangeIds(),
		id = this.hasSelectable() && ids.length ? ids[ids.length - 1] : -1,
		result = adapter.paste(tiddler.fields.text || "", this.model, id, clip, clip.model);
	if(result) {
		this.writeText(tiddler, result.text);
		this.saveSelection(result.select, id + 1, result.kind);
	}
};

exports.install = function(proto) {
	$tw.utils.each(methods, function(fn, name) {
		proto[name] = fn;
	});
};
