original own source; none or several -> null.
*/
methods.locateEditUnit = function(text) {
	var ed = this.editor,
		m = this.model && this.model.text === text ? this.model : model.buildModel(this.wiki, text, this.tiddlerTitle);
	if(ed.where === "end") {
		// Appended at the end: no anchor to find
		return {model: m, id: -1};
	}
	if(text === ed.origText) {
		var same = model.findUnit(m, ed.origStart, ed.unitKind);
		return same === -1 ? null : {model: m, id: same};
	}
	var found = m.units.filter(function(u) {
		return u.kind === ed.unitKind && text.substring(u.start, u.end) === ed.origSource;
	});
	return found.length === 1 ? {model: m, id: found[0].id} : null;
};

// After a re-render: open the new unit requested by saveEdit({continue: true})
methods.runPendingContinue = function() {
	var pending = this.pendingContinue;
	this.pendingContinue = null;
	if(!pending || this.editor) {
		return;
	}
	var id = model.findUnit(this.model, pending.start, pending.kind);
	if(id !== -1) {
		this.startEdit(id, {isNew: true});
	}
};

/*
After the body was (re-)mapped: put the host next to the relocated unit again. When the host is still in
place it is left alone (moving an iframe reloads it). Otherwise the editor widget is created again from the
buffer, so typed text is kept. It gets the focus (and caret) back only if it had the focus before.
*/
methods.reattachEditor = function() {
	var ed = this.editor;
	if(!ed) {
		if(!this.restoreEditor()) {
			this.runPendingContinue();
		}
		return;
	}
	var target = this.locateEditUnit(this.model.text);
	ed.id = target && this.isSelectable(target.id) ? target.id : -1;
	if(this.hostInPlace()) {
		this.hideEdited();
		return;
	}
	if(ed.id === -1 && dom.isInside(ed.host, this.domNode)) {
		// Unit not found (the save will report the conflict): leave the editor where it is
		this.unhideEdited();
		return;
	}
	// The focus moved elsewhere just before (its blur is decided a tick later, see noteBlur): do not take it back
	var active = this.document.activeElement,
		hadFocus = ed.focused && (!active || active === this.document.body || (!!ed.host && ed.host.contains(active)));
	ed.caret = this.editorCaret();
	this.unhideEdited();
	this.removeHost();
	this.placeEditor(hadFocus);
	if(hadFocus) {
		this.focusEditor();
	}
};

// True when the host is attached inside the container at the place the unit asks for
methods.hostInPlace = function() {
	var ed = this.editor;
	if(ed.id === -1 || !dom.isInside(ed.host, this.domNode)) {
		return false;
	}
	var nodes = this.units[ed.id].domNodes;
	if(ed.placement === "after") {
		return dom.nextSiblingOf(nodes[nodes.length - 1]) === ed.host;
	}
	if(ed.placement === "inside") {
		return ed.host.parentNode === nodes[0] && nodes[0].firstChild === ed.host;
	}
	return dom.nextSiblingOf(ed.host) === nodes[0];
};

methods.editorEngine = function() {
	var found = null;
	function walk(widget) {
		if(found || !widget) {
			return;
		}
		if(widget.engine) {
			found = widget.engine;
			return;
		}
		$tw.utils.each(widget.children, walk);
	}
	walk(this.editor && this.editor.widget);
	return found;
};

// [selectionStart, selectionEnd] of the editor's textarea, or null
methods.editorCaret = function() {
	var engine = this.editorEngine();
	return engine && engine.domNode && typeof engine.domNode.selectionStart === "number" ?
		[engine.domNode.selectionStart, engine.domNode.selectionEnd] : null;
};

/*
A freshly opened editor starts with the caret at the end of the text (or at editor.caret, set by the caller), never
with the text selected. The edit widget does this when it focuses; some browsers or plugins select the whole text
on focus, and a double-click's own selection can move the caret afterwards. One tick later the caret is set again,
unless a key was pressed (or something typed) meanwhile: the caret is then where the user put it.
*/
methods.settleCaret = function() {
	var ed = this.editor,
		self = this,
		start = this.wiki.getTiddlerText(this.bufferTitle(), "");
	if(!$tw.browser || !ed) {
		return;
	}
	setTimeout(function() {
		var engine = self.editorEngine(),
			node = engine && engine.domNode;
		if(self.editor !== ed || ed.keyed || !node || !node.setSelectionRange || node.value !== start || !ed.focused) {
			return;
		}
		var caret = ed.caret || [node.value.length, node.value.length];
		if(node.selectionStart !== caret[0] || node.selectionEnd !== caret[1]) {
			node.setSelectionRange(caret[0], caret[1]);
		}
	}, 0);
};

methods.focusEditor = function() {
	var engine = this.editorEngine();
	if(engine && engine.focus && $tw.browser) {
		engine.focus();
		var caret = this.editor.caret,
			len = (engine.domNode && engine.domNode.value || "").length;
		if(caret && engine.domNode && engine.domNode.setSelectionRange) {
			engine.domNode.setSelectionRange(Math.min(caret[0], len), Math.min(caret[1], len));
		}
		this.editor.focused = true;
	}
};

// Show notice `name` (NOTICES) at the top of the host; replaces a previous notice
methods.showNotice = function(name) {
	var ed = this.editor,
		info = NOTICES[name];
	ed.notice = name;
	if(!ed.host) {
		return;
	}
	var children = Array.prototype.slice.call(ed.host.childNodes || []);
	$tw.utils.each(children, function(child) {
		if(child.nodeType === 1 && (child.className || "").split(" ").indexOf("rr-ol-notice") !== -1) {
			ed.host.removeChild(child);
		}
	});
	var note = this.document.createElement("div");
	note.className = info.cls;
	note.appendChild(this.document.createTextNode(info.text));
	ed.host.insertBefore(note, ed.host.firstChild || null);
};

/*
Insert a line break at the caret. The FramedEngine (full editor) takes it as a text operation (keeps undo, height
and the buffer in sync). The SimpleEngine (compact editor) has no text operations: the line break goes into the
textarea directly, and an input event lets the engine save the buffer and fix the height.
*/
methods.insertNewline = function() {
	var engine = this.editorEngine();
	if(!engine || !engine.widget || !engine.widget.handleEditTextOperationMessage) {
		return;
	}
	if(!engine.createTextOperation || !engine.createTextOperation()) {
		var node = engine.domNode,
			view = node && node.ownerDocument && node.ownerDocument.defaultView;
		if(!node || !node.setRangeText || !view) {
			return;
		}
		node.setRangeText("\n", node.selectionStart, node.selectionEnd, "end");
		node.dispatchEvent(new view.Event("input", {bubbles: true}));
		return;
	}
	engine.widget.handleEditTextOperationMessage({
		type: "tm-edit-text-operation",
		param: "insert-text",
		paramObject: {text: "\n"}
	});
};

/*
Keys while editing. Events already handled elsewhere (AutoComplete popup) are ignored.
Multi-line units (code blocks, tables, widgets, multi-line items) get native Enter and Shift-Enter.
*/
methods.handleEditorKeydown = function(event) {
	var ed = this.editor;
	if(!ed || event.defaultPrevented) {
		return;
	}
	// Any key (Home, arrows, ...) places the caret itself: settleCaret leaves it alone
	ed.keyed = true;
	if(ed.target) {
		// The editor of another tiddler (a diagram) or of a template's content: save and cancel only
		if(this.keyMatches(event, "outline-save") || (ed.target.template && this.keyMatches(event, "outline-continue"))) {
			this.saveEdit();
		} else if(this.keyMatches(event, "outline-cancel")) {
			this.cancelEdit();
		} else {
			return;
		}
		event.preventDefault();
		event.stopPropagation();
		return;
	}
	if(this.keyMatches(event, "outline-save")) {
		this.saveEdit();
	} else if(!ed.multiline && this.keyMatches(event, "outline-continue")) {
		if(!this.editInsertBefore() && !this.editSplit()) {
			this.saveEdit({"continue": true});
		}
	} else if(!ed.multiline && this.keyMatches(event, "outline-newline")) {
		this.insertNewline();
	} else if(this.keyMatches(event, "outline-merge") && this.editMerge()) {
		// consumed
	} else if(this.keyMatches(event, "outline-merge-next") && this.editMergeNext()) {
		// consumed
	} else if(this.keyMatches(event, "outline-undo") && this.editUndo(true)) {
		// consumed
	} else if(this.keyMatches(event, "outline-redo") && this.editUndo(false)) {
		// consumed
	} else if(this.keyMatches(event, "outline-menu")) {
		this.editMenu();
	} else if(this.keyMatches(event, "outline-cancel")) {
		this.cancelEdit();
	} else if(this.keyMatches(event, "outline-move-up")) {
		this.editOperate("move", -1);
	} else if(this.keyMatches(event, "outline-move-down")) {
		this.editOperate("move", 1);
	} else if(this.keyMatches(event, "outline-indent")) {
		this.editOperate("indent");
	} else if(this.keyMatches(event, "outline-promote")) {
		this.editOperate("promote");
	} else if(this.keyMatches(event, "outline-edit-up")) {
		this.editStep(-1);
	} else if(this.keyMatches(event, "outline-edit-down")) {
		this.editStep(1);
	} else {
		return;
	}
	event.preventDefault();
	event.stopPropagation();
};

/*
Move the editor to the previous (dir -1) or next (1) unit: save, then edit the neighbour. A refused save (conflict,
read-only, children) keeps the editor open with its notice. After a blank save the editor goes to the unit at the
same place when that already is the requested neighbour: the one after a deleted unit (down) or the anchor of an
empty new unit (up). At the first/last unit the editor reopens on the same unit.
*/
methods.editStep = function(dir) {
	var ed = this.editor;
	if(!ed) {
		return false;
	}
	// A new unit before its anchor has the anchor below it
	var blank = !/\S/.test(this.wiki.getTiddlerText(this.bufferTitle(), "")),
		stay = blank && (ed.isNew && ed.where !== "before" ? dir < 0 : dir > 0);
	// Step from the edited unit (a new unit: from its anchor), whatever was selected before
	if(ed.id !== -1 && this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(!this.saveEdit()) {
		return true;
	}
	// The save may not be rendered yet: remap now so the neighbour is found at its new position
	this.ensureCurrent();
	// Unit by unit (never the whole list): the editor goes into lists
	if(!stay) {
		this.step(dir, true);
	}
	this.editSelected();
	return true;
};

/*
Double-click on unit `id` while editing: save, then edit that unit at its place in the saved text. A refused save
keeps the editor open with its notice; a unit that cannot be found again leaves the outline in selection mode.
*/
methods.editOther = function(id) {
	var ed = this.editor,
		target = this.units[id] && this.units[id].unit;
	if(!ed || !target) {
		return false;
	}
	var oldText = this.model.text;
	if(ed.id !== -1 && this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(!this.saveEdit()) {
		return true;
	}
	this.ensureCurrent();
	var start = utils.mapPosition(oldText, this.model.text, target.start),
		self = this,
		next = start === -1 ? -1 : model.findUnit(this.model, start, target.kind, function(i) { return self.isSelectable(i); });
	if(next !== -1 && this.select(next)) {
		this.startEdit(next);
	}
	return true;
};

/*
Tab / Shift-Tab and Alt-Up/Down while editing: like in selection mode, on the edited unit. Save, indent, promote or
move the unit with its subtree, edit it again (at its new place) with the caret where it was. A refused save keeps the editor. With empty text the key is
consumed and nothing changes.
*/
// One undo step for the save and the operation (outline-undo.js)
/*
The marker a new item after an item (Enter) is saved with, at its current depth (see newItemMarker of the adapter);
"" for other editors (also a new item before its anchor) or when the level does not fit (any more).
*/
methods.newItemMarker = function() {
	var ed = this.editor,
		adapter = this.getAdapter();
	// (a new unit of a picked item type too: its marker character is the type's, see insertBlock)
	if(!ed || !ed.isNew || ed.where !== "after" || ed.kind !== "item" || ed.unitKind !== "item" || ed.id === -1 || !adapter ||
		!adapter.newItemMarker) {
		return "";
	}
	var marker = adapter.newItemMarker(this.model, ed.id, ed.depth) || "",
		type = ed.blockType ? blockTypes.getBlockType(this.wiki, ed.blockType) : null;
	return marker && type ? marker.substring(0, marker.length - 1) + type.marker : marker;
};

// Tab (1) / Shift-Tab (-1) on an empty new item: one level deeper / higher, within the range newItemMarker allows
methods.shiftNewItem = function(dir) {
	var ed = this.editor;
	ed.depth += dir;
	if(!this.newItemMarker()) {
		ed.depth -= dir;
		return;
	}
	var buffer = this.wiki.getTiddler(this.bufferTitle());
	if(buffer) {
		this.wiki.addTiddler(new $tw.Tiddler(buffer, {"outline-depth": String(ed.depth)}));
	}
	this.showNewItemDepth();
};

/*
Show a new item's depth: the field moves by one list indentation per level, and gets the marker type of its level
(a bullet under a numbered item, ...)
*/
methods.showNewItemDepth = function() {
	var ed = this.editor,
		host = ed && ed.host;
	if(!host || !host.style || !ed.isNew || ed.kind !== "item") {
		return;
	}
	var view = this.document.defaultView,
		list = host.parentNode,
		step = view && view.getComputedStyle && list ? parseFloat(view.getComputedStyle(list).paddingLeft) || 0 : 0;
	host.style.marginLeft = ed.depth && step ? (ed.depth * step) + "px" : "";
	var type = this.editorType();
	if(type) {
		host.setAttribute("data-ol-type", type);
	}
};

methods.editOperate = function(name, arg) {
	var args = arguments;
	return this.undoGroup(function() { return editOperateSteps.apply(this, args); });
};

function editOperateSteps(name, arg) {
	var ed = this.editor;
	if(!ed) {
		return false;
	}
	// Empty text: an existing unit would be deleted by the save, a new one has nothing to write yet. A new item
	// takes Tab / Shift-Tab as the level it is saved with
	if(!/\S/.test(this.wiki.getTiddlerText(this.bufferTitle(), ""))) {
		if(name === "indent" || name === "promote") {
			this.shiftNewItem(name === "indent" ? 1 : -1);
		}
		return true;
	}
	var caret = this.editorCaret();
	if(ed.id !== -1 && this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(!this.saveEdit()) {
		return true;
	}
	this.operate(name, arg);
	this.editAgain(caret);
	return true;
};

// Edit the selected unit again (after a save and an operation on it), the caret at `caret` if given
methods.editAgain = function(caret) {
	// The write may not be rendered yet: remap so the unit is edited at its new position
	this.ensureCurrent();
	if(this.editSelected() && this.editor && caret) {
		this.editor.caret = caret;
		this.focusEditor();
	}
};

/*
Alt-Enter in the editor: save, then the block menu with the "Turn into" entries of the unit (outline-menu.js). The
editor opens again on the unit, converted or not (Escape), the caret where it was. Blank text: a new unit offers every
block type (retypeMenu, outline-menu.js), an existing one does nothing.
*/
methods.editMenu = function() {
	var ed = this.editor;
	if(!ed || ed.target) {
		return;
	}
	if(!/\S/.test(this.wiki.getTiddlerText(this.bufferTitle(), ""))) {
		// A new, still empty unit: choose what it becomes
		if(ed.isNew) {
			this.retypeMenu();
		}
		return;
	}
	var caret = this.editorCaret();
	if(ed.id !== -1 && this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(!this.saveEdit() || !this.ensureCurrent()) {
		return;
	}
	if(!this.openMenu({convertOnly: true, caret: caret})) {
		this.editAgain(caret);
	}
};

/*
Ctrl-Z / Ctrl-Y in the editor while its text is as it opened (nothing typed, or the typing undone): the outline's undo
or redo (outline-undo.js), so a split, merge, move or save made from the editor is taken back; the editor then opens
on the unit selected after it. With typed text, or without a step, the key is the text field's own.
*/
methods.editUndo = function(back) {
	if(!this.editor || this.editChanged() || this.isReadOnly() || !this.undoAvailable(back)) {
		return false;
	}
	this.closeEditor(true);
	dom.focus(this.domNode);
	this.undoStep(back);
	if(this.ensureCurrent()) {
		this.editSelected();
	}
	return true;
};

/*
Backspace with the caret at the start of a list item (nothing selected): merge the item into the item above it in its
list (the previous item in document order) and edit that one, the caret where the merged text begins. An empty item
is deleted and the editor goes to the end of the item above; its sub-items stay. An empty new item is discarded the
same way. False (the key acts as usual) anywhere else: not at the start, not a list item, a multi-line item, the
first item of a list, a new item with text.
*/
// One undo step for the save and the operation (outline-undo.js)
methods.editMerge = function() {
	var args = arguments;
	return this.undoGroup(function() { return editMergeSteps.apply(this, args); });
};

function editMergeSteps() {
	var ed = this.editor,
		caret = this.editorCaret(),
		adapter = this.getAdapter();
	if(!ed || ed.multiline || ed.kind !== "item" || ed.unitKind !== "item" || ed.id === -1 || !adapter ||
		!caret || caret[0] !== 0 || caret[1] !== 0) {
		return false;
	}
	var blank = !/\S/.test(this.wiki.getTiddlerText(this.bufferTitle(), ""));
	if(ed.isNew) {
		if(!blank) {
			return false;
		}
		// The item above the empty new one: the last item of the anchor's subtree (before the anchor: the item above
		// the anchor; none: the anchor itself, at its start)
		var anchor = this.units[ed.id].unit,
			before = ed.where === "before",
			above = adapter.itemBefore(this.model, ed.id, before ? anchor.start : anchor.subtreeEnd);
		this.cancelEdit();
		if(above !== -1 && this.select(above) && this.editSelected()) {
			this.editAtEnd();
		} else if(above === -1 && before && this.editSelected() && this.editor) {
			this.editor.caret = [0, 0];
			this.focusEditor();
		}
		return true;
	}
	if(adapter.mergeTarget(this.model, ed.id) === -1) {
		return false;
	}
	if(this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(blank) {
		// A blank save would delete the item but refuse one with sub-items: merge "" instead (sub-items stay)
		this.closeEditor(true);
	} else if(!this.saveEdit()) {
		return true;
	}
	if(!this.ensureCurrent()) {
		return true;
	}
	var id = this.selectedId,
		target = adapter.mergeTarget(this.model, id),
		join = target === -1 ? 0 : adapter.editSource(this.model.text, this.model, target, blockTypes.getBlockTypes(this.wiki)).length;
	this.operate("merge", blank ? "" : undefined);
	this.ensureCurrent();
	// Merged: the item above is selected, edited at the join; refused: the same item again, at its start
	var merged = this.selectedId !== id;
	if(this.editSelected() && this.editor) {
		this.editor.caret = merged ? [join, join] : [0, 0];
		this.focusEditor();
	}
	return true;
};

/*
Enter with the caret inside a list item's text (not at its start or end, nothing selected): split the item. The text
before the caret stays, the text after it goes to a new item right below (a sibling, or the first sub-item when the
item has sub-items), which is edited with the caret at its start. The inverse of the Backspace merge. False (Enter
acts as usual: save and new) anywhere else.
*/
// One undo step for the save and the operation (outline-undo.js)
methods.editSplit = function() {
	var args = arguments;
	return this.undoGroup(function() { return editSplitSteps.apply(this, args); });
};

function editSplitSteps() {
	var ed = this.editor,
		caret = this.editorCaret(),
		value = this.wiki.getTiddlerText(this.bufferTitle(), "");
	if(!ed || ed.multiline || ed.isNew || ed.kind !== "item" || ed.unitKind !== "item" || ed.id === -1 || !caret ||
		caret[0] !== caret[1]) {
		return false;
	}
	var head = value.substring(0, caret[0]),
		rest = value.substring(caret[0]);
	if(!/\S/.test(head) || !/\S/.test(rest)) {
		return false;
	}
	if(this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	// Save the part before the caret (with the usual conflict handling), then add the rest below
	this.wiki.setText(this.bufferTitle(), "text", null, head.replace(/[ \t]+$/, ""));
	if(!this.saveEdit()) {
		return true;
	}
	if(!this.ensureCurrent()) {
		return true;
	}
	var id = this.selectedId;
	this.operate("split", rest.replace(/^[ \t]+/, ""));
	this.ensureCurrent();
	var split = this.selectedId !== id;
	if(this.editSelected() && this.editor && split) {
		this.editor.caret = [0, 0];
		this.focusEditor();
	}
	return true;
};

/*
Enter with the caret at the start of a filled list item or paragraph (nothing selected): an empty new unit of its kind
above it (an item with its marker, a paragraph), edited at once; the edited text is saved first. The inverse of the
Backspace merge of an empty item. False (Enter acts as usual) anywhere else.
*/
methods.editInsertBefore = function() {
	var ed = this.editor,
		caret = this.editorCaret(),
		unit = ed && ed.id !== -1 ? this.units[ed.id].unit : null;
	if(!unit || ed.multiline || ed.isNew || !caret || caret[0] !== 0 || caret[1] !== 0 ||
		!(unit.kind === "item" || (unit.kind === "block" && unit.tag === "p")) ||
		!/\S/.test(this.wiki.getTiddlerText(this.bufferTitle(), ""))) {
		return false;
	}
	if(this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(this.saveEdit() && this.ensureCurrent()) {
		this.startEdit(this.selectedId, {isNew: true, where: "before"});
	}
	return true;
};

/*
Delete with the caret at the end of a list item (nothing selected): the item below that merges into this one (see
mergeSource) comes up, its text after the caret. The inverse of Backspace at the start of that item. False (the key acts
as usual) anywhere else: not at the end, a blank, new or multi-line item, no such item below.
*/
// One undo step for the save and the operation (outline-undo.js)
methods.editMergeNext = function() {
	var args = arguments;
	return this.undoGroup(function() { return editMergeNextSteps.apply(this, args); });
};

function editMergeNextSteps() {
	var ed = this.editor,
		caret = this.editorCaret(),
		adapter = this.getAdapter(),
		value = this.wiki.getTiddlerText(this.bufferTitle(), "");
	if(!ed || ed.multiline || ed.isNew || ed.kind !== "item" || ed.unitKind !== "item" || ed.id === -1 || !adapter ||
		!adapter.mergeSource || !caret || caret[0] !== value.length || caret[1] !== value.length || !/\S/.test(value)) {
		return false;
	}
	var next = adapter.mergeSource(this.model, ed.id);
	if(next === -1 || !adapter.merge(this.model.text, this.model, next)) {
		return false;
	}
	if(this.selectedId !== ed.id) {
		this.select(ed.id);
	}
	if(!this.saveEdit() || !this.ensureCurrent()) {
		return true;
	}
	var id = this.selectedId,
		join = adapter.editSource(this.model.text, this.model, id).length;
	next = adapter.mergeSource(this.model, id);
	if(next !== -1 && this.select(next)) {
		this.operate("merge");
	}
	this.editAgain([join, join]);
	return true;
}

methods.editAtEnd = function() {
	var len = this.wiki.getTiddlerText(this.bufferTitle(), "").length;
	this.editor.caret = [len, len];
	this.focusEditor();
};

// Select-mode Ctrl-Enter: an empty new unit below the selected one, as Enter at the end of its editor adds (an item on
// its level, a paragraph after anything else). In a tiddler without units: a first paragraph
methods.addBelow = function() {
	if(this.selectedId === -1) {
		return this.editSelected();
	}
	this.startEdit(this.selectedId, {isNew: true});
	return true;
};

// Select-mode Enter. In a tiddler without units: a first paragraph at the end of the text
methods.editSelected = function() {
	if(this.selectedId === -1) {
		return !this.hasSelectable() && this.startEdit(-1, {isNew: true, blockType: "paragraph", where: "end"});
	}
	this.startEdit(this.selectedId);
	return true;
};

// Open `title` in the story, its outline awake: its first unit selected (unless it already has a selection)
methods.openTarget = function(title) {
	if(!title) {
		return false;
	}
	var selection = SELECTION_PREFIX + title;
	if(!this.wiki.tiddlerExists(selection)) {
		this.wiki.addTiddler(new $tw.Tiddler({title: selection, start: "0", index: "0", kind: ""}));
	}
	this.dispatchEvent({
		type: "tm-navigate",
		navigateTo: title,
		navigateFromTitle: this.tiddlerTitle,
		navigateFromNode: this
	});
	return true;
};

/*
The editor of another tiddler or of a template's content, below unit `id` (the unit is not hidden; its text is not
touched until the save). opts:
  {title}             - a diagram tiddler that unit `id` transcludes: its text is edited, the save writes it
  {isNew, typeName}   - "Add to this item" with a type of the item context: a transclude type starts with its starter
                        text; the first save creates the tiddler (newTiddlerTitle, the type's content type) and appends
                        {{title}} to the item's line. A template type (inline: a template with $content$) edits the
                        content; the save appends the filled template. Escape before the save writes nothing.
The buffer is the editor buffer of this tiddler, marked outline-target-mode (a re-render does not keep it).
*/
methods.startTargetEdit = function(id, opts) {
	opts = opts || {};
	if(this.editor) {
		this.focusEditor();
		return false;
	}
	var owner = this.otherOwner();
	if(owner) {
		owner.focusEditor();
		return false;
	}
	var type = opts.isNew ? blockTypes.getBlockType(this.wiki, opts.typeName) : null,
		existing = opts.isNew ? null : this.wiki.getTiddler(opts.title);
	// An existing target must be a diagram: a tiddler of a registered typed type (transcluded wikitext is not edited here)
	if(this.isReadOnly() || !this.getAdapter() || !this.isSelectable(id) || (opts.isNew ? !type || !type.inline :
		!existing || !blockTypes.typeForContentType(this.wiki, existing.fields.type))) {
		return false;
	}
	var unit = this.units[id].unit,
		ed = editorState(unit.kind, false, this.model.text.substring(unit.start, unit.end), unit.start, this.model.text,
			"", this.getAdapter(), "", blockTypes.getBlockTypes(this.wiki)),
		template = type && type.inline !== "transclude" ? type.inline : "",
		initial = opts.isNew ? (template ? "" : type.starter) : this.wiki.getTiddlerText(opts.title, "");
	ed.id = id;
	ed.target = {title: opts.isNew ? "" : opts.title, isNew: !!opts.isNew, typeName: type ? type.name : "", template: template};
	ed.placement = "after";
	ed.multiline = !template;
	this.editor = ed;
	ownersOf(this.wiki)[this.bufferTitle()] = this;
	this.wiki.addTiddler(new $tw.Tiddler({
		title: this.bufferTitle(),
		text: initial,
		type: "text/vnd.tiddlywiki",
		"outline-orig-edit": initial,
		"outline-orig-source": ed.origSource,
		"outline-orig-start": String(ed.origStart),
		"outline-orig-text": ed.origText,
		"outline-unit-kind": ed.unitKind,
		"outline-target-mode": "yes"
	}));
	this.placeEditor(true);
	this.settleCaret();
	return true;
};

// Save of the editor opened by startTargetEdit
methods.saveTargetEdit = function() {
	var ed = this.editor,
		target = ed.target,
		text = this.wiki.getTiddlerText(this.bufferTitle(), "");
	if(this.isReadOnly()) {
		this.showNotice("readonly");
		return false;
	}
	if(!target.isNew) {
		var tiddler = this.wiki.getTiddler(target.title),
			buffer = this.wiki.getTiddler(this.bufferTitle()),
			orig = buffer ? buffer.fields["outline-orig-edit"] || "" : "";
		// Changed outside since the edit started: not saved over (typed text stays in the editor; nothing typed: nothing
		// written)
		if(tiddler && (tiddler.fields.text || "") !== orig) {
			if(text !== orig) {
				this.showNotice("conflict");
				return false;
			}
			tiddler = null;
		}
		this.closeEditor(true);
		dom.focus(this.domNode);
		if(tiddler && text !== (tiddler.fields.text || "")) {
			this.wiki.addTiddler(new $tw.Tiddler(tiddler, {text: text}, this.wiki.getModificationFields()));
		}
		return true;
	}
	if(!/\S/.test(text)) {
		this.closeEditor(true);
		dom.focus(this.domNode);
		return true;
	}
	var host = this.wiki.getTiddler(this.tiddlerTitle),
		current = host ? (host.fields.text || "") : "",
		located = host ? this.locateEditUnit(current) : null,
		type = blockTypes.getBlockType(this.wiki, target.typeName),
		adapter = this.getAdapter();
	if(!located || !type) {
		this.showNotice("conflict");
		return false;
	}
	var u = located.model.units[located.id],
		title = target.template ? "" : this.newTiddlerTitle("diagram", {type: type.name}),
		snippet = target.template ? target.template.replace(/\$content\$/g, text.replace(/\s*\r?\n\s*/g, " ").trim()) :
			adapter.referenceTo(title, true);
	this.closeEditor(true);
	dom.focus(this.domNode);
	if(title) {
		this.wiki.addTiddler(new $tw.Tiddler(this.wiki.getCreationFields(), {title: title, type: type.contentType, text: text},
			this.wiki.getModificationFields()));
	}
	this.writeText(host, utils.splice(current, u.end, u.end, " " + snippet));
	this.saveSelection(u.start, located.id, u.kind);
	return true;
};

/*
Title of a new tiddler made by outline: the template $:/config/rimir/outline/name/<kind> ("diagram": "Add to this item",
"externalize") with $host$ (this tiddler's title) and $type$ (vars.type) filled in, and the first free number from 1.
*/
methods.newTiddlerTitle = function(kind, vars) {
	// (function replacements: a "$" in the host title or type is no replacement pattern)
	var host = this.tiddlerTitle,
		type = (vars && vars.type) || "",
		base = this.wiki.getTiddlerText(NAME_PREFIX + kind, NAME_DEFAULTS[kind] || "$host$/")
			.replace(/\$host\$/g, function() { return host; }).replace(/\$type\$/g, function() { return type; }).trim(),
		n = 1;
	while(this.wiki.tiddlerExists(base + n)) {
		n++;
	}
	return base + n;
};

// True when a new unit of block type `name` takes Enter as a line break (fenced and typed blocks)
methods.newTypeIsMultiline = function(name) {
	var type = name ? blockTypes.getBlockType(this.wiki, name) : null;
	return !!type && (type.behaviour === "fenced" || type.behaviour === "typed");
};

// Name of the typed block type (a diagram) whose code the editor shows: a new diagram ("Add to this item"), a new typed
// block, or an existing typed block; "" for anything else
methods.editedDiagramType = function() {
	var ed = this.editor,
		types = blockTypes.getBlockTypes(this.wiki),
		type = null;
	if(ed.target) {
		type = ed.target.template ? null : (ed.target.typeName ? blockTypes.getBlockType(this.wiki, ed.target.typeName) : null);
	} else if(ed.isNew) {
		type = ed.blockType ? blockTypes.getBlockType(this.wiki, ed.blockType) : null;
	} else if(ed.id !== -1 && this.units[ed.id]) {
		var adapter = this.getAdapter();
		type = adapter && adapter.typedBlockType ? adapter.typedBlockType(this.model.text, this.units[ed.id].unit, types) : null;
	}
	return type && type.behaviour === "typed" ? type.name : "";
};

// Caption of block type `name` (the new unit's placeholder), "" when there is none
methods.newTypeCaption = function(name) {
	var type = name ? blockTypes.getBlockType(this.wiki, name) : null;
	return type ? type.caption : "";
};

methods.getAdapter = function() {
	var tiddler = this.wiki.getTiddler(this.tiddlerTitle);
	return formats.getFormat(tiddler ? tiddler.fields.type : "");
};

exports.NOTICES = NOTICES;

exports.install = function(proto) {
	$tw.utils.each(methods, function(fn, name) {
		proto[name] = fn;
	});
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/outline/outline-keys.js":{"title":"$:/plugins/rimir/outline/outline-keys.js","text":"/*\
title: $:/plugins/rimir/outline/outline-keys.js
type: application/javascript
module-type: library

Selection, configurable keys and structural operations of the $outline widget.
install(proto) adds these methods to the widget prototype. They use widget.model, widget.units,
widget.domNode and widget.tiddlerTitle (see outline-widget.js).

Selection state: $:/temp/rimir/outline/selection/<title> with fields start, index and kind (the outline inside an
overlay: under $:/temp/rimir/outline/overlay/, see stateTitle).
After a re-render the unit with the saved start is selected again (same kind preferred, because a list
and its first item share a start). Otherwise the saved index, clamped. Units without DOM nodes cannot
be selected. A list item with sub-items is framed around its own lines only (drawSelectionBox).

Key overview: toggleHelp sets/deletes helpTitle() ($:/temp/rimir/outline/help/<title>, or the overlay's own); ui/body
and ui/overlay show ui/keys-table while it is "yes". Escape closes it before it clears the selection.

\*/
"use strict";

var formats = require("$:/plugins/rimir/outline/formats.js"),
	findUnit = require("$:/plugins/rimir/outline/model.js").findUnit,
	checkOp = require("$:/plugins/rimir/outline/model.js").checkOp,
	buildModel = require("$:/plugins/rimir/outline/model.js").buildModel,
	mapPosition = require("$:/plugins/rimir/outline/text-utils.js").mapPosition,
	dom = require("$:/plugins/rimir/outline/dom-utils.js"),
	blockTypes = require("$:/plugins/rimir/outline/block-types.js"),
	setClass = dom.setClass,
	focus = dom.focus,
	isInside = dom.isInside,
	isEditable = dom.isEditable,
	scrollIntoView = dom.scrollIntoView;

var SELECTION_PREFIX = "$:/temp/rimir/outline/selection/",
	// The outline inside an overlay keeps its own state (selection, edit buffer, key overview) under this prefix: a
	// story view of the same tiddler is not woken or changed by it
	OVERLAY_STATE_PREFIX = "$:/temp/rimir/outline/overlay/",
	OVERLAY_HOST_VARIABLE = "rr-ol-overlay-host",
	READ_ONLY = "$:/status/IsReadOnly",
	SELECTED_CLASS = "rr-ol-selected",
	OWN_CLASS = "rr-ol-selected-own",
	BOX_CLASS = "rr-ol-selbox",
	NESTED_TAGS = {UL: true, OL: true, DL: true, BLOCKQUOTE: true};

/*
Select-mode actions in matching order. run returns true when the key is consumed. Structural keys
(operate) are consumed whenever a unit is selected, even when nothing changes or the wiki is read-only,
so Tab never moves the focus away from a selection. In read-only wikis only up/down/clear/open act.
`char` is a typed character that also triggers the action, whatever the keyboard layout ("?" is shift-slash only
on US layouts).
*/
var ACTIONS = [
	{name: "outline-extend-up", run: function(w) { return w.extendSelection(-1); }},
	{name: "outline-extend-down", run: function(w) { return w.extendSelection(1); }},
	{name: "outline-up", run: function(w) { return w.step(-1); }},
	{name: "outline-down", run: function(w) { return w.step(1); }},
	{name: "outline-up-deep", run: function(w) { return w.step(-1, true); }},
	{name: "outline-down-deep", run: function(w) { return w.step(1, true); }},
	{name: "outline-parent", run: function(w) { return w.stepTree(-1); }},
	{name: "outline-child", run: function(w) { return w.stepTree(1); }},
	// Escape: clears the selection; with nothing selected the outline goes idle
	{name: "outline-clear", run: function(w) { return w.clearSelection() || w.sleep(); }},
	{name: "outline-open", run: function(w) { return w.openTransclusion(); }},
	{name: "outline-open-story", run: function(w) { return w.openTransclusion(true); }},
	{name: "outline-edit", run: function(w) { return w.editSelected(); }},
	{name: "outline-add", run: function(w) { return w.addBelow(); }},
	{name: "outline-menu", run: function(w) { return w.openMenu(); }},
	{name: "outline-delete", run: function(w) { return w.deleteSelected(); }},
	{name: "outline-move-up", run: function(w) { return w.operate("move", -1); }},
	{name: "outline-move-down", run: function(w) { return w.operate("move", 1); }},
	{name: "outline-indent", run: function(w) { return w.operate("indent"); }},
	{name: "outline-promote", run: function(w) { return w.operate("promote"); }},
	{name: "outline-undo", run: function(w) { return w.undoStep(true); }},
	{name: "outline-redo", run: function(w) { return w.undoStep(false); }},
	{name: "outline-help", char: "?", run: function(w) { return w.toggleHelp(); }}
];

var methods = {};

// Operations that run on a range as one step per unit (operateRange)
var RANGE_STEPS = {move: true, indent: true, promote: true};

/* ---------- selection ---------- */

// Title of this outline's state tiddler of `kind` (selection, edit, help): $:/temp/rimir/outline/<kind>/<title>, or
// under OVERLAY_STATE_PREFIX for the outline inside an overlay
methods.stateTitle = function(kind) {
	return (this.getVariable(OVERLAY_HOST_VARIABLE) === "yes" ? OVERLAY_STATE_PREFIX : "$:/temp/rimir/outline/") +
		kind + "/" + this.tiddlerTitle;
};

methods.selectionTitle = function() {
	return this.stateTitle("selection");
};

methods.isSelectable = function(id) {
	var entry = this.units[id];
	return !!entry && entry.domNodes.length > 0;
};

// Select unit `id` and save the selection. Returns false for units that cannot be selected.
methods.select = function(id) {
	if(!this.isSelectable(id)) {
		return false;
	}
	var unit = this.units[id].unit;
	this.rangeAnchor = -1;
	this.saveSelection(unit.start, id, unit.kind);
	this.showSelection(id);
	return true;
};

/*
Ranges: siblings (the selectable children of the same parent, or the roots) from the anchor (this.rangeAnchor) to the
selected unit (the moving end). A unit's subtree goes along with it. The selection tiddler keeps the anchor as
anchor-start / anchor-kind next to the selected unit's start / index / kind.
*/
methods.siblingsOf = function(id) {
	var model = this.model,
		parent = model.units[id].parent,
		self = this;
	return (parent === -1 ? model.roots : model.units[parent].children).filter(function(i) {
		return self.isSelectable(i);
	});
};

// Ids of the selected units in document order: the range, or the selected unit alone ([] without a selection)
methods.rangeIds = function() {
	var id = this.selectedId;
	if(id === -1) {
		return [];
	}
	var sibs = this.rangeAnchor === -1 || this.rangeAnchor === id ? [] : this.siblingsOf(id),
		a = sibs.indexOf(this.rangeAnchor),
		b = sibs.indexOf(id);
	if(a === -1 || b === -1) {
		return [id];
	}
	return sibs.slice(Math.min(a, b), Math.max(a, b) + 1);
};

// Select the siblings from `anchor` to `focus` (focus is the selected unit); a single unit when they are the same
methods.selectRange = function(anchor, focus) {
	if(!this.isSelectable(focus) || (anchor !== focus && this.siblingsOf(focus).indexOf(anchor) === -1)) {
		return this.select(focus);
	}
	var unit = this.units[focus].unit,
		a = this.units[anchor].unit;
	this.rangeAnchor = anchor === focus ? -1 : anchor;
	this.saveSelection(unit.start, focus, unit.kind, this.rangeAnchor === -1 ? null : {start: a.start, kind: a.kind});
	this.showSelection(focus);
	return true;
};

// Shift-Up/Down: extend (or shrink) the range by the previous / next sibling; stays at the first / last one
methods.extendSelection = function(dir) {
	this.ensureCurrent();
	var id = this.selectedId;
	if(id === -1) {
		return false;
	}
	var sibs = this.siblingsOf(id),
		next = sibs[sibs.indexOf(id) + dir];
	if(next !== undefined) {
		this.selectRange(this.rangeAnchor === -1 ? id : this.rangeAnchor, next);
		scrollIntoView(dom.firstShown(this.units[next].domNodes));
	}
	return true;
};

methods.clearSelection = function() {
	if(this.selectedId === -1) {
		return false;
	}
	// A range collapses to its moving end first
	if(this.rangeIds().length > 1) {
		return this.select(this.selectedId);
	}
	this.wiki.deleteTiddler(this.selectionTitle());
	this.showSelection(-1);
	return true;
};

methods.saveSelection = function(start, index, kind, anchor) {
	this.wiki.addTiddler(new $tw.Tiddler({
		title: this.selectionTitle(),
		start: String(start),
		index: String(index),
		kind: kind || "",
		"anchor-start": anchor ? String(anchor.start) : undefined,
		"anchor-kind": anchor ? anchor.kind || "" : undefined
	}));
};

// Unit id for the saved selection in the current mapping, or -1
methods.resolveSelection = function() {
	var state = this.wiki.getTiddler(this.selectionTitle()),
		self = this;
	if(!state || !this.units.length) {
		return -1;
	}
	var id = findUnit(this.model, parseInt(state.fields.start, 10), state.fields.kind, function(i) {
		return self.isSelectable(i);
	});
	if(id !== -1) {
		return id;
	}
	var index = parseInt(state.fields.index, 10);
	if(isNaN(index)) {
		return -1;
	}
	index = Math.max(0, Math.min(index, this.units.length - 1));
	return this.nearestSelectable(index);
};

methods.hasSelectable = function() {
	for(var i = 0; i < this.units.length; i++) {
		if(this.isSelectable(i)) {
			return true;
		}
	}
	return false;
};

// `index` itself if selectable, else the next selectable unit after it, else the one before it
methods.nearestSelectable = function(index) {
	var i;
	for(i = index; i < this.units.length; i++) {
		if(this.isSelectable(i)) { return i; }
	}
	for(i = index - 1; i >= 0; i--) {
		if(this.isSelectable(i)) { return i; }
	}
	return -1;
};

// Move the selection frame to unit `id` (-1: none) without touching the state tiddler
methods.showSelection = function(id) {
	$tw.utils.each(this.selectedNodes || [], function(node) {
		setClass(node, SELECTED_CLASS, false);
	});
	this.selectedId = id;
	if(this.menu) {
		if(this.menu.id !== id) {
			this.closeMenu();
		} else {
			this.positionMenu();
		}
	}
	if(id === -1) {
		this.rangeAnchor = -1;
	}
	var units = this.units,
		nodes = [];
	$tw.utils.each(this.rangeIds(), function(i) {
		nodes = nodes.concat(units[i].domNodes);
	});
	this.selectedNodes = nodes;
	$tw.utils.each(this.selectedNodes, function(node) {
		setClass(node, SELECTED_CLASS, true);
	});
	this.drawSelectionBox();
};

// First child element of a list item that holds its sub-items, or null
function nestedListOf(node) {
	for(var child = node.firstChild; child; child = child.nextSibling) {
		if(child.nodeType === 1 && NESTED_TAGS[child.tagName]) {
			return child;
		}
	}
	return null;
}

/*
A selected list item with sub-items gets its frame from an overlay box around its own lines only (the item's
element contains its sub-items). Moves still take the sub-items along. Called after every selection change and
when the outline container resizes. Needs a real DOM (ranges, layout); elsewhere the item keeps its plain frame.
*/
methods.drawSelectionBox = function() {
	var nodes = this.selectedNodes || [],
		doc = this.document,
		box = this.selectionBox,
		target = null,
		nested = null;
	$tw.utils.each(nodes, function(node) {
		setClass(node, OWN_CLASS, false);
	});
	if(this.selectedId !== -1 && this.units[this.selectedId].unit.kind === "item" && nodes.length === 1 &&
		doc.createRange && nodes[0].getBoundingClientRect && this.domNode.getBoundingClientRect) {
		nested = nestedListOf(nodes[0]);
		target = nested ? nodes[0] : null;
	}
	if(!target) {
		if(box) {
			box.style.display = "none";
		}
		return;
	}
	var range = doc.createRange();
	range.setStart(target, 0);
	range.setEndBefore(nested);
	var own = range.getBoundingClientRect(),
		item = target.getBoundingClientRect(),
		root = this.domNode.getBoundingClientRect(),
		top = own.height ? own.top : item.top,
		bottom = own.height ? own.bottom : nested.getBoundingClientRect().top;
	if(!box) {
		box = this.selectionBox = doc.createElement("div");
		box.className = BOX_CLASS;
	}
	if(box.parentNode !== this.domNode) {
		this.domNode.appendChild(box);
	}
	box.style.display = "";
	box.style.left = (item.left - root.left) + "px";
	box.style.top = (top - root.top) + "px";
	box.style.width = item.width + "px";
	box.style.height = Math.max(0, bottom - top) + "px";
	setClass(target, OWN_CLASS, true);
};

// Re-apply the saved selection after (re-)mapping
methods.restoreSelection = function() {
	var id = this.resolveSelection(),
		state = this.wiki.getTiddler(this.selectionTitle()),
		self = this,
		anchor = -1;
	// The range's other end, when it is still a sibling of the selected unit
	if(id !== -1 && state && state.fields["anchor-start"] !== undefined) {
		anchor = findUnit(this.model, parseInt(state.fields["anchor-start"], 10), state.fields["anchor-kind"], function(i) {
			return self.isSelectable(i);
		});
		if(anchor === id || this.siblingsOf(id).indexOf(anchor) === -1) {
			anchor = -1;
		}
	}
	this.rangeAnchor = anchor;
	this.showSelection(id);
};

// Select the previous (-1) or next (1) selectable unit. Without a selection: the first or last one.
/*
Up/Down. `deep` (Ctrl-Up/Down): every unit in document order. Otherwise a whole list counts as one block: Down from a
selected list goes to the unit after it, and Up into a list from below selects the whole list (see outerList).
*/
methods.step = function(dir, deep) {
	// Positions of an unrendered change are stale: remap first (selecting writes nothing)
	this.ensureCurrent();
	var id = this.selectedId, i;
	if(id === -1) {
		i = dir > 0 ? this.nearestSelectable(0) : this.lastSelectable();
	} else {
		var skipEnd = !deep && dir > 0 && this.units[id].unit.kind === "list" ? this.units[id].unit.subtreeEnd : -1;
		for(i = id + dir; i >= 0 && i < this.units.length &&
			(!this.isSelectable(i) || this.units[i].unit.start < skipEnd); i += dir) {}
		if(i < 0 || i >= this.units.length) {
			i = id;
		} else if(!deep && dir < 0) {
			i = this.outerList(i, id);
		}
	}
	if(i === -1) {
		return false;
	}
	this.select(i);
	scrollIntoView(dom.firstShown(this.units[i].domNodes));
	return true;
};

/*
Left (dir -1): select the parent unit - the item a sub-item belongs to, the whole list of a top-level item, the
heading of a section.
Right (1): select the first child: the list of a heading's section, the first item of a list, the first sub-item.
Units that cannot be selected are passed over. Consumed whenever a unit is selected, also when there is nowhere to go.
*/
methods.stepTree = function(dir) {
	this.ensureCurrent();
	var id = this.selectedId;
	if(id === -1) {
		return false;
	}
	var target = dir < 0 ? this.treeParent(id) : this.treeChild(id);
	if(target !== -1) {
		this.select(target);
		scrollIntoView(dom.firstShown(this.units[target].domNodes));
	}
	return true;
};

methods.treeParent = function(id) {
	var model = this.model;
	for(var p = model.units[id].parent; p !== -1; p = model.units[p].parent) {
		if(this.isSelectable(p)) {
			return p;
		}
	}
	return -1;
};

methods.treeChild = function(id) {
	var model = this.model, self = this;
	// The first selectable child; a child that cannot be selected stands in for its own first child
	function first(children) {
		for(var i = 0; i < children.length; i++) {
			var c = model.units[children[i]],
				found = self.isSelectable(c.id) ? c.id : first(c.children);
			if(found !== -1) {
				return found;
			}
		}
		return -1;
	}
	return first(model.units[id].children);
};

// The outermost selectable list around unit `i` that does not contain unit `from`; else `i`
methods.outerList = function(i, from) {
	var model = this.model,
		start = model.units[from].start,
		result = i;
	for(var p = model.units[i].parent; p !== -1; p = model.units[p].parent) {
		var u = model.units[p];
		if(u.kind === "list" && !(start >= u.start && start < u.subtreeEnd) && this.isSelectable(p)) {
			result = p;
		}
	}
	return result;
};

methods.lastSelectable = function() {
	for(var i = this.units.length - 1; i >= 0; i--) {
		if(this.isSelectable(i)) { return i; }
	}
	return -1;
};

/* ---------- operations ---------- */

// Shift-Enter (outline-open): the tiddler the selected unit transcludes in an overlay (a diagram: its source in place);
// Ctrl-Shift-Enter (outline-open-story, inStory): in the story, in outline mode (openTarget: outline-editor.js)
methods.openTransclusion = function(inStory) {
	var id = this.selectedId,
		target = id === -1 ? null : this.transcludedTitle(id),
		tiddler = target ? this.wiki.getTiddler(target) : null;
	if(!target) {
		return false;
	}
	// A field, index or template transclusion shows part of the tiddler: it opens in the story
	if(!inStory && !this.transcludesPart(id)) {
		// An overlay over the unit (outline-overlay.js): the tiddler's own outline, a diagram's source with a preview
		if(this.openOverlay(id, target)) {
			return true;
		}
	}
	this.openTarget(target);
	return true;
};

// True when the (first) transclusion of unit `id` names a field, an index or a template ({{X!!f}}, {{X##i}},
// {{X||T}}, <$transclude $field=... / $index=...>)
methods.transcludesPart = function(id) {
	var unit = this.units[id].unit,
		source = this.model.text.substring(unit.start, unit.end),
		braces = /\{\{[^{}|]+?(!!|##|\|\|)/.exec(source),
		widget = /<\$transclude\b[^>]*?\s\$?(?:field|index)=/.exec(source);
	return !!(braces && (!widget || braces.index < widget.index)) || !!(widget && !braces);
};

// The tiddler unit `id` transcludes: a transclusion unit's target, or the first transclusion in its source; or null
methods.transcludedTitle = function(id) {
	var unit = this.units[id].unit;
	return unit.kind === "transclusion" ? unit.target : firstTransclusion(this.model.text.substring(unit.start, unit.end));
};

// Title of the first transclusion in `source` ({{title}}, {{title!!field}}, {{title||template}}, or a transclude widget
// with a literal $tiddler / tiddler attribute), or null
function firstTransclusion(source) {
	var braces = /\{\{([^{}|]+?)(?:!!|##|\|\||\}\})/.exec(source),
		widget = /<\$transclude\b[^>]*?\s\$?tiddler=(?:"([^"]*)"|'([^']*)'|\[\[([^\]]*)\]\]|([^\s\/>"']+))/.exec(source),
		first = braces && (!widget || braces.index < widget.index) ? braces : widget;
	if(!first) {
		return null;
	}
	return first === braces ? braces[1].trim() : (widget[1] || widget[2] || widget[3] || widget[4]);
}

// The data-ol-diagram-target element (a diagram transclusion, see mapDiagrams) node is in, or null
function diagramNodeOf(node, root) {
	for(; node && node !== root; node = node.parentNode) {
		if(node.getAttribute && node.getAttribute("data-ol-diagram-target")) {
			return node;
		}
	}
	return null;
}

/*
Run adapter operation `name` on the selected unit. Returns true when a unit is selected (the key is
consumed), whether or not the text changed. A result that fails the model guard (checkOp) is not written.
*/
methods.operate = function(name, arg) {
	var id = this.selectedId;
	if(id === -1) {
		return false;
	}
	// Read-only, or an open editor in this view (a move could rewrite the edited unit): consumed, no write
	if(this.isReadOnly() || this.editor) {
		return true;
	}
	if(!this.ensureCurrent()) {
		return true;
	}
	id = this.selectedId;
	var tiddler = this.wiki.getTiddler(this.tiddlerTitle),
		text = tiddler.fields.text || "",
		adapter = formats.getFormat(tiddler.fields.type),
		ids = this.rangeIds();
	if(!adapter || !adapter[name]) {
		return true;
	}
	if(ids.length > 1) {
		if(RANGE_STEPS[name]) {
			return this.operateRange(name, arg, ids, tiddler, adapter);
		}
		if(name === "deleteUnit" && adapter.deleteRange) {
			var removed = adapter.deleteRange(text, this.model, ids);
			if(removed && checkOp(this.wiki, this.model, ids[0], name, removed.text, this.tiddlerTitle, removed)) {
				this.rangeAnchor = -1;
				this.applyResult(removed);
			}
			return true;
		}
		// Other operations act on the range's moving end (the selected unit), like Enter and the block menu
		this.select(id);
	}
	var result = adapter[name](text, this.model, id, arg, blockTypes.getBlockTypes(this.wiki));
	// Guard: never write a result that changes units the operation must leave alone
	if(result && result.text !== text && !checkOp(this.wiki, this.model, id, name, result.text, this.tiddlerTitle, result)) {
		return true;
	}
	this.applyResult(result);
	return true;
};

/*
True when the positions of this.model fit the tiddler's current text (the tiddler exists). When the text changed
and that change has not been rendered yet, the body is rebuilt first. If the change is this view's own last write
(a key pressed before the refresh after a write), the rebuilt mapping and the restored selection are valid and
the result is true; after any other change it is false (positions are not trusted for a write: do nothing).
*/
/*
Externalize the selected unit or range (block menu): its text goes into a new wikitext tiddler (newTiddlerTitle
"externalize"), a reference takes its place (the adapter's externalize). One write of this tiddler (one undo step);
the new tiddler stays on undo. The reference is selected.
*/
methods.externalizeSelected = function() {
	var adapter = this.getAdapter();
	if(this.selectedId === -1 || this.isReadOnly() || this.editor || !adapter || !adapter.externalize || !this.ensureCurrent()) {
		return false;
	}
	var ids = this.rangeIds(),
		tiddler = this.wiki.getTiddler(this.tiddlerTitle),
		text = tiddler ? (tiddler.fields.text || "") : "",
		title = this.newTiddlerTitle("externalize"),
		result = tiddler ? adapter.externalize(text, this.model, ids, title) : null;
	// Checked like a structural operation (its removed and added units): otherwise nothing is written, no tiddler made
	if(!result || !checkOp(this.wiki, this.model, ids[0], "externalize", result.text, this.tiddlerTitle, result)) {
		return true;
	}
	this.wiki.addTiddler(new $tw.Tiddler(this.wiki.getCreationFields(), {title: title, type: "text/vnd.tiddlywiki",
		text: result.source}, this.wiki.getModificationFields()));
	this.rangeAnchor = -1;
	this.writeText(tiddler, result.text);
	this.saveSelection(result.select, ids[0], result.kind);
	return true;
};

/*
Move, indent or promote a range (`ids`, siblings in document order): the single-unit operation for each unit, the
first one first (the last one first for a move down), each on the model of the text before it and checked like a
single operation; the other units' starts follow each change (mapPosition). All or nothing: one write (one undo step),
the range stays selected. Always consumed.
*/
methods.operateRange = function(name, arg, ids, tiddler, adapter) {
	var wiki = this.wiki,
		title = this.tiddlerTitle,
		types = blockTypes.getBlockTypes(wiki),
		text = tiddler.fields.text || "",
		model = this.model,
		units = ids.map(function(id) { return {start: model.units[id].start, kind: model.units[id].kind}; }),
		order = units.map(function(u, i) { return i; });
	if(name === "move" && arg > 0) {
		order.reverse();
	}
	for(var k = 0; k < order.length; k++) {
		var i = order[k],
			id = findUnit(model, units[i].start, units[i].kind),
			result = id === -1 ? null : adapter[name](text, model, id, arg, types);
		if(!result || !checkOp(wiki, model, id, name, result.text, title, result)) {
			return true;
		}
		for(var j = 0; j < units.length; j++) {
			units[j].start = j === i ? result.select : mapPosition(text, result.text, units[j].start);
			if(units[j].start === -1) {
				return true;
			}
		}
		text = result.text;
		model = buildModel(wiki, text, title);
	}
	// The range must stay in its order (a heading moving over the block above it takes that block into its section,
	// and the next heading would then swap with that section): otherwise nothing is written
	for(var n = 1; n < units.length; n++) {
		if(units[n].start <= units[n - 1].start) {
			return true;
		}
	}
	// ... and stay together: consecutive siblings (a block moving down over a heading line goes into the next section,
	// away from a heading of the range that moved on)
	var after = units.map(function(u) { return findUnit(model, u.start, u.kind); }),
		parentOf = function(id) { return id === -1 ? null : model.units[id].parent; },
		siblings = parentOf(after[0]) === -1 ? model.roots : (after[0] === -1 ? [] : model.units[parentOf(after[0])].children),
		at = siblings.indexOf(after[0]);
	for(var q = 0; q < after.length; q++) {
		if(at === -1 || siblings[at + q] !== after[q]) {
			return true;
		}
	}
	var focus = ids.indexOf(this.selectedId),
		anchor = ids.indexOf(this.rangeAnchor);
	if(text !== (tiddler.fields.text || "")) {
		this.writeText(tiddler, text);
	}
	this.saveSelection(units[focus].start, this.selectedId, units[focus].kind,
		anchor === -1 ? null : {start: units[anchor].start, kind: units[anchor].kind});
	return true;
};

methods.ensureCurrent = function() {
	var tiddler = this.wiki.getTiddler(this.tiddlerTitle),
		text = tiddler ? (tiddler.fields.text || "") : "";
	if(tiddler && text === this.model.text) {
		return true;
	}
	this.rebuild();
	return !!tiddler && text === this.lastWritten && this.model.text === text && this.selectedId !== -1;
};

// Write `text` to the tiddler (one change, one undo step: outline-undo.js) and remember it as this view's own last write
methods.writeText = function(tiddler, text) {
	this.recordWrite(tiddler ? (tiddler.fields.text || "") : "", text);
	this.lastWritten = text;
	this.wiki.addTiddler(new $tw.Tiddler(tiddler, {text: text}, this.wiki.getModificationFields()));
};

/*
Write the adapter result {text, select} to the tiddler (once) and save the selection at the new start.
null (no-op) writes nothing; a result whose text equals the current text only saves the selection.
*/
methods.applyResult = function(result) {
	if(!result) {
		return false;
	}
	var old = this.wiki.getTiddler(this.tiddlerTitle),
		id = this.selectedId,
		// A conversion changes the unit's kind: the result names the new one
		kind = result.kind || (id === -1 ? "" : this.units[id].unit.kind);
	// Same text (e.g. two identical siblings swapped): no write, but the frame still follows result.select
	if(!old || result.text !== (old.fields.text || "")) {
		this.writeText(old, result.text);
	}
	this.saveSelection(result.select, id === -1 ? 0 : id, kind);
	return true;
};

methods.isReadOnly = function() {
	return this.wiki.getTiddlerText(READ_ONLY) === "yes";
};

/* ---------- events ---------- */

methods.handleKeydown = function(event) {
	// Idle, consumed elsewhere (AutoComplete popups listen in the capture phase), or from an element inside
	if(!this.awake || event.defaultPrevented || event.target !== this.domNode) {
		return;
	}
	// An open block menu takes its keys; any other key closes it and acts as usual
	if(this.menu) {
		if(this.handleMenuKeydown(event)) {
			event.preventDefault();
			event.stopPropagation();
			return;
		}
		this.closeMenu();
	}
	// An open key overview closes with Escape before Escape clears the selection
	if(event.keyCode === 27 && !event.ctrlKey && !event.altKey && !event.metaKey && !event.shiftKey && this.isHelpOpen()) {
		this.toggleHelp(false);
		event.preventDefault();
		event.stopPropagation();
		return;
	}
	for(var i = 0; i < ACTIONS.length; i++) {
		var action = ACTIONS[i];
		if((this.keyMatches(event, action.name) || typedChar(event, action.char)) && action.run(this)) {
			event.preventDefault();
			event.stopPropagation();
			return;
		}
	}
};

function typedChar(event, ch) {
	return !!ch && event.key === ch && !event.ctrlKey && !event.altKey && !event.metaKey;
}

/* ---------- key overview ---------- */

// The overview (ui/keys-table) is shown by the body template while this temp tiddler is "yes"
methods.helpTitle = function() {
	return this.stateTitle("help");
};

methods.isHelpOpen = function() {
	return this.wiki.getTiddlerText(this.helpTitle()) === "yes";
};

// Open, close (open = true/false) or toggle the key overview. Always consumes the key.
methods.toggleHelp = function(open) {
	if(open === undefined) {
		open = !this.isHelpOpen();
	}
	if(open) {
		this.wiki.setText(this.helpTitle(), "text", null, "yes");
	} else if(this.wiki.tiddlerExists(this.helpTitle())) {
		this.wiki.deleteTiddler(this.helpTitle());
	}
	return true;
};

methods.keyMatches = function(event, name) {
	var km = $tw.keyboardManager;
	return !!km && km.checkKeyDescriptors(event, km.parseKeyDescriptors("((" + name + "))", {wiki: this.wiki}));
};

// True when `node` is in a link or button (below the outline): its click and double-click are its own
function inControl(node, root) {
	for(var m = node; m && m !== root; m = m.parentNode) {
		if(m.tagName && /^(A|BUTTON|INPUT|SELECT|OPTION|TEXTAREA|LABEL)$/i.test(m.tagName)) {
			return true;
		}
	}
	return false;
}

/*
Idle: only Ctrl-Click (Cmd-Click) on the outline does something, outside links, buttons and form controls: it wakes the outline and
selects the clicked unit. Awake: click on a transclusion marker opens its target. Click on a stamped element selects
its unit and focuses the container. Clicks inside the editor host are left to the editor.
*/
methods.handleClick = function(event) {
	var node = event.target;
	// Clicks inside this outline's overlay belong to the overlay's own outline; a click outside it closes it (not with
	// changes in it)
	if(this.inOverlay(node)) {
		return;
	}
	if(this.overlay) {
		this.closeOverlay();
	}
	if(!this.awake) {
		// (an outline inside this one already woke for this click: the event bubbles from it)
		if(!(event.ctrlKey || event.metaKey) || event.defaultPrevented || inControl(node, this.domNode)) {
			return;
		}
		event.preventDefault();
		this.wake();
		var woken = this.unitIdAt(node);
		if(woken !== -1) {
			this.select(woken);
		}
		focus(this.domNode);
		return;
	}
	this.closeMenu();
	if(this.editor && this.editor.host && isInside(node, this.editor.host)) {
		return;
	}
	for(var m = node; m && m !== this.domNode; m = m.parentNode) {
		if(m.getAttribute && m.getAttribute("data-ol-target")) {
			event.preventDefault();
			event.stopPropagation();
			this.openTarget(m.getAttribute("data-ol-target"));
			return;
		}
	}
	var id = this.unitIdAt(node);
	// Shift-Click: the range from the anchor (or the selected unit) to the clicked sibling
	if(id !== -1 && event.shiftKey && this.selectedId !== -1) {
		event.preventDefault();
		// The browser extended its text selection on mousedown; it would take over Ctrl-C / Ctrl-X
		var view = this.document.defaultView;
		if(view && view.getSelection) {
			view.getSelection().removeAllRanges();
		}
		if(this.selectRange(this.rangeAnchor === -1 ? this.selectedId : this.rangeAnchor, id)) {
			focus(this.domNode);
		}
		return;
	}
	if(id !== -1 && this.select(id) && !isEditable(event.target)) {
		focus(this.domNode);
	}
};

// Id of the unit whose stamped element contains `node` (the innermost), or -1
methods.unitIdAt = function(node) {
	for(; node && node !== this.domNode; node = node.parentNode) {
		if(node.getAttribute && node.getAttribute("data-ol-id") !== null && node.getAttribute("data-ol-id") !== undefined) {
			return parseInt(node.getAttribute("data-ol-id"), 10);
		}
	}
	return -1;
};

/*
Double-click on a unit edits it (a transclusion: its line, not the target); while another unit is edited, that one is
saved first. Not inside the editor, not on links, buttons or inputs; the word the double-click selected is deselected.
*/
methods.handleDblClick = function(event) {
	var node = event.target;
	if(!this.awake || this.inOverlay(node) || (this.editor && this.editor.host && isInside(node, this.editor.host))) {
		return;
	}
	if(isEditable(node) || inControl(node, this.domNode)) {
		return;
	}
	var id = this.unitIdAt(node),
		view = this.document.defaultView;
	if(id === -1) {
		return;
	}
	event.preventDefault();
	// A diagram inside the unit: its own editor (an open editor is saved first)
	var diagram = diagramNodeOf(node, this.domNode);
	if(diagram) {
		if(!this.editor || this.saveEdit()) {
			this.select(id);
			this.openOverlay(id, diagram.getAttribute("data-ol-diagram-target"));
		}
		return;
	}
	// The word the double-click selected goes first (clearing it later would reset the editor's caret)
	if(view && view.getSelection) {
		view.getSelection().removeAllRanges();
	}
	if(this.editor && this.editor.id !== id) {
		this.editOther(id);
	} else if(this.select(id)) {
		this.startEdit(id);
	}
};

exports.SELECTION_PREFIX = SELECTION_PREFIX;
exports.OVERLAY_STATE_PREFIX = OVERLAY_STATE_PREFIX;
exports.OVERLAY_HOST_VARIABLE = OVERLAY_HOST_VARIABLE;

exports.install = function(proto) {
	$tw.utils.each(methods, function(fn, name) {
		proto[name] = fn;
	});
};
