title: $:/plugins/rimir/outline/outline-menu.js
type: application/javascript
module-type: library

Menus of the $outline widget at the selected unit: the block menu (outline-menu key, default Alt-Enter) and the
delete confirmation (outline-delete key, default Delete), both in selection mode; the block menu also from the editor.
install(proto) adds these methods to the widget prototype:

  openMenu(opts)        - open the block menu at the selected unit; false when nothing is selected. opts.convertOnly:
                          only the "Turn into" entries (from the editor, after its save; false when there are none),
                          and the editor opens again afterwards, also on Escape, the caret at opts.caret
  deleteSelected()      - delete the selected unit, after the confirmation menu (see below)
  showMenu(id, entries) - show a menu of entries at unit id
  closeMenu()           - remove it
  handleMenuKeydown(e)  - Up/Down/Home/End move, Enter runs, Escape closes; true when consumed

Block menu entries, in three groups: "Insert after" and "Insert before" (a new block of a type, edited at once; not
for single list items) and "Turn into" (the adapter's convertTypes for the unit). In a tiddler without units the menu
only inserts (at the end of the text). On a transclusion the first entry edits the line itself.
Delete confirmation: "Yes" (with the count of what goes along), on a heading with a section also "Just the heading",
and "Cancel". Childless list items are deleted without asking when $:/config/rimir/outline/quick-delete-items is yes.
Labels are the tiddlers $:/plugins/rimir/outline/language/block/<key>.

\*/
"use strict";

var dom = require("$:/plugins/rimir/outline/dom-utils.js"),
	blockTypes = require("$:/plugins/rimir/outline/block-types.js");

var LABEL_PREFIX = "$:/plugins/rimir/outline/language/block/",
	KEY = {up: 38, down: 40, home: 36, end: 35, enter: 13, escape: 27},
	QUICK_DELETE = "$:/config/rimir/outline/quick-delete-items";

var methods = {};

// Block menu entries for unit `id` (-1: a tiddler without units): [{group, action: "insert"|"convert"|"edit", type, where}]
// Insert and convert entries are labelled with the type's caption (block type tiddlers, see block-types.js)
methods.menuEntries = function(id) {
	var self = this,
		adapter = this.getAdapter(),
		types = blockTypes.getBlockTypes(this.wiki),
		captions = {},
		entries = [];
	if(!adapter) {
		return entries;
	}
	types.forEach(function(t) { captions[t.name] = t.caption; });
	var blockTypesHere = types.filter(function(t) { return t.contexts.indexOf("block") !== -1; });
	if(id === -1) {
		return blockTypesHere.map(function(t) {
			return {group: "group-insert", action: "insert", type: t.name, text: t.caption, where: "end"};
		});
	}
	var unit = this.units[id].unit;
	this.diagramTargets(id).forEach(function(d) {
		entries.push({group: "", action: "edit-target", title: d.title, text: self.label("edit-target").replace("$title$", d.title)});
	});
	if(unit.kind === "item") {
		entries = entries.concat(this.addEntries());
	}
	["after", "before"].forEach(function(where) {
		blockTypesHere.forEach(function(t) {
			entries.push({group: where === "after" ? "group-insert" : "group-insert-before", action: "insert", type: t.name,
				text: t.caption, where: where});
		});
	});
	adapter.convertTypes(this.model, id, types).forEach(function(type) {
		entries.push({group: "group-convert", action: "convert", type: type, text: captions[type]});
	});
	// Last: Alt-Enter, Enter keeps inserting a paragraph
	if(adapter.canExternalize && adapter.canExternalize(this.model, this.rangeIds())) {
		entries.push({group: "group-more", action: "externalize", text: this.label("externalize")});
	}
	return entries;
};

// "Add to this item" entries: the types with the item context (a diagram tiddler or a template, see startTargetEdit)
methods.addEntries = function() {
	return blockTypes.getBlockTypes(this.wiki).filter(function(t) {
		return t.contexts.indexOf("item") !== -1 && t.inline;
	}).map(function(t) {
		return {group: "group-add", action: "add", type: t.name, text: t.caption};
	});
};

methods.label = function(key) {
	return this.wiki.getTiddlerText(LABEL_PREFIX + key, key);
};

methods.openMenu = function(opts) {
	var id = this.selectedId;
	this.closeMenu();
	if(opts && opts.convertOnly) {
		var entries = id === -1 || this.editor ? [] : this.menuEntries(id).filter(function(entry) {
			return entry.action === "convert";
		});
		this.showMenu(id, entries);
		if(this.menu) {
			this.menu.reedit = {caret: opts.caret};
		}
		return !!this.menu;
	}
	if(id === -1 && !this.editor && !this.isReadOnly() && !this.hasSelectable()) {
		this.showMenu(-1, this.menuEntries(-1));
		return true;
	}
	if(id === -1 || this.editor || this.isReadOnly() || !this.ensureCurrent()) {
		return id !== -1;
	}
	this.showMenu(this.selectedId, this.menuEntries(this.selectedId));
	return true;
};

/*
The type menu of a new, still empty editor (Alt-Enter in it): every block type. The editor closes (nothing was written)
and opens again for the picked type at the same place; Escape opens it again as it was.
*/
methods.retypeMenu = function() {
	var ed = this.editor,
		retype = {id: ed.id, where: ed.where, blockType: ed.blockType, depth: ed.depth},
		onItem = ed.id !== -1 && this.units[ed.id] && this.units[ed.id].unit.kind === "item" && ed.where !== "end";
	this.closeEditor(true);
	this.closeMenu();
	this.showMenu(retype.id, blockTypes.getBlockTypes(this.wiki).filter(function(t) {
		return t.contexts.indexOf("block") !== -1;
	}).map(function(t) {
		return {group: "", action: "retype", type: t.name, text: t.caption};
	}).concat(onItem ? this.addEntries() : []));
	if(this.menu) {
		this.menu.retype = retype;
	}
	return !!this.menu;
};

methods.deleteSelected = function() {
	var id = this.selectedId,
		adapter = this.getAdapter();
	this.closeMenu();
	if(id === -1 || this.editor || this.isReadOnly() || !adapter || !this.ensureCurrent()) {
		return id !== -1;
	}
	id = this.selectedId;
	var unit = this.units[id].unit,
		count = adapter.deleteCount(this.model, id),
		yes = {group: "group-delete", action: "delete"},
		ids = this.rangeIds();
	// A range: one question for all of it (its units and everything below them)
	if(ids.length > 1) {
		var all = ids.length, model = this.model;
		ids.forEach(function(i) { all += adapter.deleteCount(model, i); });
		yes.text = this.countLabel("delete-range", "blocks", all);
		this.showMenu(id, [yes, {group: "group-delete", action: "cancel", type: "cancel"}]);
		return true;
	}
	if(unit.kind === "item" && !unit.children.length && this.wiki.getTiddlerText(QUICK_DELETE) === "yes") {
		this.operate("deleteUnit");
		return true;
	}
	if(count && unit.kind === "heading") {
		yes.text = this.countLabel("delete-heading", "blocks", count);
	} else if(count && unit.kind === "list") {
		yes.text = this.countLabel("delete-list", "items", count);
	} else if(count && unit.kind === "item" && unit.children.length) {
		yes.text = this.countLabel("delete-children", "sub-items", count);
	} else if(count && unit.kind === "container") {
		yes.text = this.countLabel("delete-container", "blocks", count);
	} else {
		yes.type = "delete";
	}
	var entries = [yes];
	if(count && unit.kind === "heading") {
		entries.push({group: "group-delete", action: "delete", arg: "own", type: "delete-own"});
	}
	entries.push({group: "group-delete", action: "cancel", type: "cancel"});
	this.showMenu(id, entries);
	return true;
};

// Label `key` with $counted$ replaced by "<count> <noun>" (language count-<noun> / count-<noun>-one)
methods.countLabel = function(key, noun, count) {
	var counted = this.label("count-" + noun + (count === 1 ? "-one" : "")).replace("$count$", String(count));
	return this.label(key).replace("$counted$", counted);
};

// Show `entries` ({group, action, type or text, arg}) as a menu below unit `id`; the first entry is active
methods.showMenu = function(id, entries) {
	this.closeMenu();
	var doc = this.document,
		self = this;
	if(!entries.length) {
		return;
	}
	var node = doc.createElement("div"),
		group = null;
	node.className = "rr-ol-menu";
	entries.forEach(function(entry, index) {
		if(entry.group && entry.group !== group) {
			var head = doc.createElement("div");
			head.className = "rr-ol-menu-group";
			head.appendChild(doc.createTextNode(self.label(entry.group)));
			node.appendChild(head);
		}
		group = entry.group;
		var item = doc.createElement("div");
		item.className = "rr-ol-menu-item";
		item.setAttribute("data-ol-menu-index", String(index));
		item.appendChild(doc.createTextNode(entry.text || self.label(entry.type)));
		entry.node = item;
		node.appendChild(item);
	});
	// Mouse: a click runs the entry; mousedown is cancelled so the outline keeps the focus
	node.addEventListener("mousedown", function(event) {
		event.preventDefault();
	}, false);
	node.addEventListener("click", function(event) {
		event.preventDefault();
		event.stopPropagation();
		for(var m = event.target; m && m !== node; m = m.parentNode) {
			if(m.getAttribute && m.getAttribute("data-ol-menu-index") !== null) {
				self.runMenuEntry(parseInt(m.getAttribute("data-ol-menu-index"), 10));
				return;
			}
		}
	}, false);
	this.menu = {id: id, entries: entries, node: node, active: 0};
	this.domNode.appendChild(node);
	this.positionMenu();
	this.setMenuActive(0);
};

// Below the selected unit's first shown DOM node (dom.firstShown), inside the (position: relative) outline container
methods.positionMenu = function() {
	var menu = this.menu,
		anchor = menu.id === -1 ? this.emptyHint : dom.firstShown(this.units[menu.id].domNodes);
	if(!anchor || !anchor.getBoundingClientRect || !this.domNode.getBoundingClientRect) {
		return;
	}
	var a = anchor.getBoundingClientRect(),
		root = this.domNode.getBoundingClientRect();
	menu.node.style.left = Math.max(0, a.left - root.left) + "px";
	menu.node.style.top = (a.bottom - root.top + 2) + "px";
};

methods.setMenuActive = function(index) {
	var menu = this.menu;
	menu.active = Math.max(0, Math.min(menu.entries.length - 1, index));
	menu.entries.forEach(function(entry, i) {
		dom.setClass(entry.node, "rr-ol-menu-active", i === menu.active);
	});
	dom.scrollIntoView(menu.entries[menu.active].node);
};

methods.closeMenu = function() {
	if(this.menu) {
		if(this.menu.node.parentNode) {
			this.menu.node.parentNode.removeChild(this.menu.node);
		}
		this.menu = null;
	}
};

methods.runMenuEntry = function(index) {
	var menu = this.menu,
		entry = menu && menu.entries[index];
	if(!entry) {
		return;
	}
	var id = menu.id,
		reedit = menu.reedit;
	this.closeMenu();
	if(id !== -1 && id !== this.selectedId) {
		this.select(id);
	}
	dom.focus(this.domNode);
	if(entry.action === "externalize") {
		this.externalizeSelected();
	} else if(entry.action === "add") {
		this.startTargetEdit(id, {isNew: true, typeName: entry.type});
	} else if(entry.action === "edit-target") {
		this.openOverlay(id, entry.title);
	} else if(menu.retype) {
		this.startEdit(menu.retype.id, {isNew: true, blockType: entry.type, where: menu.retype.where, depth: menu.retype.depth});
	} else if(reedit) {
		this.operate("convert", entry.type);
		this.editAgain(reedit.caret);
	} else if(entry.action === "cancel") {
		return;
	} else if(entry.action === "delete") {
		this.operate("deleteUnit", entry.arg);
	} else if(entry.action === "insert") {
		this.startEdit(id, {isNew: true, blockType: entry.type, where: entry.where});
	} else {
		this.operate("convert", entry.type);
	}
};

methods.handleMenuKeydown = function(event) {
	var menu = this.menu;
	if(!menu || event.ctrlKey || event.altKey || event.metaKey) {
		return false;
	}
	switch(event.keyCode) {
		case KEY.up: this.setMenuActive(menu.active - 1); return true;
		case KEY.down: this.setMenuActive(menu.active + 1); return true;
		case KEY.home: this.setMenuActive(0); return true;
		case KEY.end: this.setMenuActive(menu.entries.length - 1); return true;
		case KEY.enter: this.runMenuEntry(menu.active); return true;
		case KEY.escape:
			var reedit = menu.reedit,
				retype = menu.retype;
			this.closeMenu();
			if(retype) {
				this.startEdit(retype.id, {isNew: true, blockType: retype.blockType, where: retype.where, depth: retype.depth});
			} else if(reedit) {
				this.editAgain(reedit.caret);
			}
			return true;
	}
	return false;
};

exports.install = function(proto) {
	$tw.utils.each(methods, function(fn, name) {
		proto[name] = fn;
	});
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/outline/outline-overlay.js":{"title":"$:/plugins/rimir/outline/outline-overlay.js","text":"/*\
title: $:/plugins/rimir/outline/outline-overlay.js
type: application/javascript
module-type: library

Transclusion overlay of the $outline widget: Shift-Enter (outline-open) on a wikitext transclusion opens the target
tiddler's own outline in an overlay over the unit (ui/overlay: a title bar and an $outline of the target), where it is
navigated and edited as always. install(proto) adds:

  openOverlay(id, title) - open the overlay of `title` over unit `id` (one per outline; a further one opens inside it)
  closeOverlay(force)    - close it, select the unit again, focus this outline; refused while an editor is open in it
                           (or in an overlay inside it) unless forced (its unit is gone, this outline goes away):
                           then that edit is kept like an edit over a re-render
  overlayBusy()          - true while an editor is open in the overlay (or in one inside it), or a diagram's source
                           in it is changed
  saveOverlay()          - a diagram overlay: write the source into the diagram tiddler and close

A diagram (a tiddler of a registered typed block type, see block-types.js) opens in ui/overlay-diagram instead: its
source in a code field (buffer $:/temp/rimir/outline/diagram/<this title>, of the diagram's type) and a live preview of
the buffer below it. Ctrl-Enter (outline-save) saves, Escape (outline-cancel) closes without writing.
  placeOverlay()         - after a remap: put it at its unit's top again; close it when the unit is gone
  inOverlay(node)        - true when node is inside this outline's overlay
  overlayHost()          - for the outline inside an overlay: the outline that opened it (else null)

this.overlay = {id, start, kind, title, element, widget, outline}
The element is a child of this outline's container, outside the body's widget tree: a re-render keeps it. The host
ignores events from inside it (handleClick, handleDblClick, ownsTarget); the overlay's outline counts its whole overlay
as its own, so a click on the title bar does not close it. The overlay's outline does not sleep on its own: its sleep
(Escape with nothing selected, a click outside) closes the overlay.

\*/
"use strict";

var dom = require("$:/plugins/rimir/outline/dom-utils.js"),
	findUnit = require("$:/plugins/rimir/outline/model.js").findUnit,
	mapPosition = require("$:/plugins/rimir/outline/text-utils.js").mapPosition,
	formats = require("$:/plugins/rimir/outline/formats.js"),
	keys = require("$:/plugins/rimir/outline/outline-keys.js"),
	NOTICES = require("$:/plugins/rimir/outline/outline-editor.js").NOTICES;

var blockTypes = require("$:/plugins/rimir/outline/block-types.js");

var TEMPLATE = "$:/plugins/rimir/outline/ui/overlay",
	DIAGRAM_TEMPLATE = "$:/plugins/rimir/outline/ui/overlay-diagram",
	OVERLAY_CLASS = "rr-ol-overlay",
	HOST_VARIABLE = keys.OVERLAY_HOST_VARIABLE;

function findOutline(widget) {
	for(var i = 0; i < (widget.children || []).length; i++) {
		var child = widget.children[i];
		if(child.parseTreeNode && child.parseTreeNode.type === "outline") {
			return child;
		}
		var found = findOutline(child);
		if(found) {
			return found;
		}
	}
	return null;
}

var methods = {};

/*
Refused (false: the caller opens the story instead) for a missing tiddler, a tiddler that is neither a diagram nor of a
format the outline edits (it would show an empty overlay), and a tiddler that is this outline's own or one an overlay
below it already shows (a self-transclusion).
*/
methods.openOverlay = function(id, title) {
	if(!this.isSelectable(id) || !title || !this.wiki.tiddlerExists(title)) {
		return false;
	}
	for(var w = this; w; w = w.overlayHost()) {
		if(w.tiddlerTitle === title) {
			return false;
		}
	}
	var target = this.wiki.getTiddler(title),
		diagram = !!blockTypes.typeForContentType(this.wiki, target.fields.type);
	if(!diagram && !formats.getFormat(target.fields.type)) {
		return false;
	}
	// A diagram buffer in use by another view of this tiddler (its open overlay) is not taken over
	var buffer = diagram ? this.stateTitle("diagram") : "";
	if(diagram && this.wiki.tiddlerExists(buffer) && !(this.overlay && this.overlay.buffer === buffer)) {
		return false;
	}
	this.closeOverlay();
	if(this.overlay) {
		return false;
	}
	var
		unit = this.units[id].unit,
		element = this.document.createElement("div"),
		typed = blockTypes.typeForContentType(this.wiki, target.fields.type),
		variables = {"rr-ol-overlay-target": title, "rr-ol-overlay-buffer": buffer, "rr-ol-overlay-type": typed ? typed.name : ""},
		self = this;
	variables[HOST_VARIABLE] = "yes";
	if(diagram) {
		this.wiki.addTiddler(new $tw.Tiddler({title: buffer, type: target.fields.type, text: target.fields.text || ""}));
	} else {
		// The overlay's outline wakes itself on render when its selection tiddler exists (first unit, or the kept one)
		var selection = keys.OVERLAY_STATE_PREFIX + "selection/" + title;
		if(!this.wiki.tiddlerExists(selection)) {
			this.wiki.addTiddler(new $tw.Tiddler({title: selection, start: "0", index: "0", kind: ""}));
		}
	}
	element.className = OVERLAY_CLASS;
	this.domNode.appendChild(element);
	var widget = this.wiki.makeTranscludeWidget(diagram ? DIAGRAM_TEMPLATE : TEMPLATE, {
		parentWidget: this,
		document: this.document,
		variables: variables
	});
	widget.render(element, null);
	this.overlay = {id: id, start: unit.start, kind: unit.kind, text: this.model.text, title: title, element: element, widget: widget,
		outline: diagram ? null : findOutline(widget), diagram: diagram, buffer: buffer, orig: target.fields.text || ""};
	// The diagram's code field: Ctrl-Enter saves, Escape closes without writing
	if(diagram) {
		element.addEventListener("keydown", function(event) {
			if(self.keyMatches(event, "outline-save")) {
				self.saveOverlay();
			} else if(self.keyMatches(event, "outline-cancel")) {
				self.closeOverlay(true);
			} else {
				return;
			}
			event.preventDefault();
			event.stopPropagation();
		}, false);
	}
	// Title bar buttons (data-ol-overlay-action): close, open in the story
	// A mousedown on the title bar or the overlay's edge does not move the keyboard focus to this outline (below it)
	element.addEventListener("mousedown", function(event) {
		var o = self.overlay;
		if(o && o.outline && !dom.isInside(event.target, o.outline.domNode)) {
			event.preventDefault();
			dom.focus(o.outline.domNode);
		}
	}, false);
	element.addEventListener("click", function(event) {
		for(var n = event.target; n && n !== element; n = n.parentNode) {
			var action = n.getAttribute && n.getAttribute("data-ol-overlay-action");
			if(action) {
				event.preventDefault();
				event.stopPropagation();
				if(self.closeOverlay() && action === "story") {
					self.openTarget(title);
				}
				return;
			}
		}
	}, false);
	this.placeOverlay();
	if(this.overlay) {
		if(element.scrollIntoView && this.document.defaultView) {
			element.scrollIntoView({block: "nearest"});
		}
		if(this.overlay.outline) {
			dom.focus(this.overlay.outline.domNode);
			// Copy / cut / paste go where the caret is (dom.caretInto)
			dom.caretInto(this.overlay.outline.domNode);
		}
	}
	return true;
};

methods.overlayBusy = function() {
	var o = this.overlay;
	if(o && o.diagram) {
		return this.wiki.getTiddlerText(o.buffer, "") !== o.orig;
	}
	var outline = o && o.outline;
	return !!outline && (!!outline.editor || outline.overlayBusy());
};

methods.saveOverlay = function() {
	var o = this.overlay;
	if(!o || !o.diagram) {
		return false;
	}
	// The buffer gone (closed by another view): nothing to save
	if(!this.wiki.tiddlerExists(o.buffer)) {
		return false;
	}
	var text = this.wiki.getTiddlerText(o.buffer, ""),
		tiddler = this.wiki.getTiddler(o.title),
		current = tiddler ? tiddler.fields.text || "" : "";
	// The diagram changed outside since the overlay opened: a changed source is not saved over it (the notice says so,
	// the source stays to be copied); an unchanged one writes nothing
	if(tiddler && current !== o.orig) {
		if(text === o.orig) {
			return this.closeOverlay(true);
		}
		this.showOverlayNotice("conflict");
		return false;
	}
	if(tiddler && text !== current) {
		this.wiki.addTiddler(new $tw.Tiddler(tiddler, {text: text}, this.wiki.getModificationFields()));
	}
	return this.closeOverlay(true);
};

// Notice `name` (outline-editor NOTICES) below the overlay's title bar; replaces a previous one
methods.showOverlayNotice = function(name) {
	var o = this.overlay,
		info = NOTICES[name];
	if(!o || !info) {
		return;
	}
	if(o.notice && o.notice.parentNode) {
		o.notice.parentNode.removeChild(o.notice);
	}
	o.notice = this.document.createElement("div");
	o.notice.className = info.cls;
	o.notice.appendChild(this.document.createTextNode(info.text));
	var bar = o.element.firstChild;
	o.element.insertBefore(o.notice, bar ? bar.nextSibling : null);
};

// Unit id of the overlay's unit in the current model (its start mapped over text changes since it was placed), or -1
methods.overlayUnitId = function() {
	var o = this.overlay;
	if(!o || !this.model || !this.units.length) {
		return -1;
	}
	var start = this.model.text !== o.text ? mapPosition(o.text, this.model.text, o.start) : o.start;
	return start === -1 ? -1 : findUnit(this.model, start, o.kind);
};

// quiet: no selection, no focus afterwards (this outline is going to show another tiddler)
methods.closeOverlay = function(force, quiet) {
	var o = this.overlay;
	if(!o) {
		return false;
	}
	if(!force && this.overlayBusy()) {
		return false;
	}
	var id = this.overlayUnitId();
	this.overlay = null;
	if(o.outline) {
		o.outline.closingOverlay = true;
	}
	o.widget.destroy();
	if(o.element.parentNode) {
		o.element.parentNode.removeChild(o.element);
	}
	if(o.buffer) {
		this.wiki.deleteTiddler(o.buffer);
	}
	if(this.awake && this.units.length && !quiet) {
		if(id !== -1) {
			this.select(id);
		}
		dom.focus(this.domNode);
		dom.caretInto(this.domNode);
	}
	return true;
};

methods.placeOverlay = function() {
	var o = this.overlay;
	if(!o) {
		return;
	}
	// Its unit's start follows changes of the text before it
	var id = this.overlayUnitId();
	if(id === -1 || !this.isSelectable(id)) {
		this.closeOverlay(true);
		return;
	}
	o.id = id;
	o.start = this.units[id].unit.start;
	o.text = this.model.text;
	// Over the unit: from its first shown element's top, relative to this outline's container (the positioning
	// context; offsetTop would be relative to a positioned list or item)
	var node = dom.firstShown(this.units[id].domNodes);
	if(node && node.getBoundingClientRect && this.domNode.getBoundingClientRect && o.element.style) {
		o.element.style.top = (node.getBoundingClientRect().top - this.domNode.getBoundingClientRect().top) + "px";
	}
};

methods.inOverlay = function(node) {
	return !!this.overlay && dom.isInside(node, this.overlay.element);
};

methods.overlayHost = function() {
	if(this.getVariable(HOST_VARIABLE) !== "yes") {
		return null;
	}
	for(var w = this.parentWidget; w; w = w.parentWidget) {
		if(w.overlay && w.overlay.widget && dom.isInside(this.domNode, w.overlay.element)) {
			return w;
		}
	}
	return null;
};

exports.install = function(proto) {
	$tw.utils.each(methods, function(fn, name) {
		proto[name] = fn;
	});
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/outline/outline-undo.js":{"title":"$:/plugins/rimir/outline/outline-undo.js","text":"/*\
title: $:/plugins/rimir/outline/outline-undo.js
type: application/javascript
module-type: library

Undo and redo of the outline's own writes. install(proto) adds these methods to the widget prototype.

Every text write of the outline (writeText: operations, edits, deletes, merges, splits) records {before, after, sel}:
the text before and after it and the selection before it. The history of a tiddler lives in the temp tiddler
$:/temp/rimir/outline/undo/<title> (JSON {undo: [...], redo: [...]}) for the running session only. It keeps the last
$:/config/rimir/outline/undo-depth steps (default 20). A new write empties the redo list.

Undo writes `before` back, redo writes `after` again, each only while the tiddler still has the text the step left
(after resp. before). Any other text means it changed outside the outline: the history no longer fits and is
dropped, nothing is written.

undoGroup(fn) runs fn so that all its writes form one step (a split saves the edited item and then adds the new one).

\*/
"use strict";

var UNDO_PREFIX = "$:/temp/rimir/outline/undo/",
	DEPTH = "$:/config/rimir/outline/undo-depth",
	DEFAULT_DEPTH = 20;

var methods = {};

methods.undoTitle = function() {
	return UNDO_PREFIX + this.tiddlerTitle;
};

methods.readUndo = function() {
	var state = null;
	try {
		state = JSON.parse(this.wiki.getTiddlerText(this.undoTitle(), "null"));
	} catch(e) {
		state = null;
	}
	if(!state || !$tw.utils.isArray(state.undo) || !$tw.utils.isArray(state.redo)) {
		state = {undo: [], redo: []};
	}
	return state;
};

methods.writeUndo = function(state) {
	this.wiki.addTiddler(new $tw.Tiddler({
		title: this.undoTitle(),
		type: "application/json",
		text: JSON.stringify(state)
	}));
};

// The saved selection {start, index, kind, anchor} (anchor: a range's other end {start, kind}, or null), or null
methods.selectionSnapshot = function() {
	var state = this.wiki.getTiddler(this.selectionTitle()),
		f = state ? state.fields : null;
	return f ? {start: f.start, index: f.index, kind: f.kind || "",
		anchor: f["anchor-start"] !== undefined ? {start: f["anchor-start"], kind: f["anchor-kind"] || ""} : null} : null;
};

methods.applySnapshot = function(sel) {
	if(sel) {
		this.saveSelection(sel.start, sel.index, sel.kind, sel.anchor);
	} else if(this.wiki.tiddlerExists(this.selectionTitle())) {
		this.wiki.deleteTiddler(this.selectionTitle());
	}
};

// Record a write of the outline (called by writeText before the write)
methods.recordWrite = function(before, after) {
	if(before === after) {
		return;
	}
	var state = this.readUndo(),
		top = state.undo[state.undo.length - 1],
		group = this.undoGroupState;
	if(group && group.started && top && top.after === before) {
		top.after = after;
	} else {
		state.undo.push({before: before, after: after, sel: this.selectionSnapshot()});
		var depth = parseInt(this.wiki.getTiddlerText(DEPTH, ""), 10);
		depth = isNaN(depth) || depth < 1 ? DEFAULT_DEPTH : depth;
		if(state.undo.length > depth) {
			state.undo.splice(0, state.undo.length - depth);
		}
	}
	if(group) {
		group.started = true;
	}
	state.redo = [];
	this.writeUndo(state);
};

// Run fn with all its writes recorded as one step; returns fn's result
methods.undoGroup = function(fn) {
	var outer = this.undoGroupState;
	if(!outer) {
		this.undoGroupState = {started: false};
	}
	try {
		return fn.call(this);
	} finally {
		if(!outer) {
			this.undoGroupState = null;
		}
	}
};

// True when undo (back = true) or redo has a step that fits the tiddler's current text
methods.undoAvailable = function(back) {
	var tiddler = this.wiki.getTiddler(this.tiddlerTitle),
		state = this.readUndo(),
		from = back ? state.undo : state.redo,
		entry = from[from.length - 1];
	return !!tiddler && !!entry && (tiddler.fields.text || "") === (back ? entry.after : entry.before);
};

/*
Undo (back = true) or redo the last step. Always consumes the key. Nothing happens in read-only wikis, while this view
has an open editor, or when there is no step.
*/
methods.undoStep = function(back) {
	if(this.isReadOnly() || this.editor) {
		return true;
	}
	var tiddler = this.wiki.getTiddler(this.tiddlerTitle),
		state = this.readUndo(),
		from = back ? state.undo : state.redo,
		entry = from[from.length - 1];
	if(!tiddler || !entry) {
		return true;
	}
	if((tiddler.fields.text || "") !== (back ? entry.after : entry.before)) {
		// Changed outside the outline since: the history no longer fits
		this.wiki.deleteTiddler(this.undoTitle());
		return true;
	}
	from.pop();
	var sel = this.selectionSnapshot();
	if(back) {
		entry.redoSel = sel;
		state.redo.push(entry);
	} else {
		entry.sel = sel;
		state.undo.push(entry);
	}
	this.writeUndo(state);
	var text = back ? entry.before : entry.after;
	this.lastWritten = text;
	this.wiki.addTiddler(new $tw.Tiddler(tiddler, {text: text}, this.wiki.getModificationFields()));
	this.applySnapshot(back ? entry.sel : (entry.redoSel || entry.sel));
	return true;
};

exports.install = function(proto) {
	$tw.utils.each(methods, function(fn, name) {
		proto[name] = fn;
	});
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/outline/outline-widget.js":{"title":"$:/plugins/rimir/outline/outline-widget.js","text":"/*\
title: $:/plugins/rimir/outline/outline-widget.js
type: application/javascript
module-type: widget

The $outline widget: wraps the normal body transclusion of a tiddler, maps the units of its
text to the rendered DOM nodes and stamps them with data-ol-* attributes.

<$outline tiddler=<<currentTiddler>>><$transclude $tiddler=<<currentTiddler>> $mode="block"/></$outline>

After render and refresh:
  widget.model      - buildModel() of the tiddler text
  widget.units      - [{unit, domNodes:[Element]}] in model order
  widget.selectedId - selected unit id or -1 (selection and keys: outline-keys.js)
  widget.editor     - open in-place editor or null (outline-editor.js); re-attached after each mapping

Matching rule (unit <-> widget): a widget matches a unit when its parseTreeNode.start equals the
unit's anchor (the unit start; for $$$ typed blocks the start of the line after the $$$ header,
where the parser starts the node) and its tag (element tag, else parse node type) equals unit.tag.
Each unit matches once, in document order. `end` is only a tie-breaker, because the model trims
trailing line breaks and extends lists to their subtree end.

\*/
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget,
	buildModel = require("$:/plugins/rimir/outline/model.js").buildModel,
	keys = require("$:/plugins/rimir/outline/outline-keys.js"),
	editor = require("$:/plugins/rimir/outline/outline-editor.js"),
	menu = require("$:/plugins/rimir/outline/outline-menu.js"),
	undo = require("$:/plugins/rimir/outline/outline-undo.js"),
	clipboard = require("$:/plugins/rimir/outline/outline-clipboard.js"),
	overlay = require("$:/plugins/rimir/outline/outline-overlay.js"),
	dom = require("$:/plugins/rimir/outline/dom-utils.js"),
	blockTypes = require("$:/plugins/rimir/outline/block-types.js");

// One {{...}} or one <$transclude .../> and nothing else (an item's content, see stamp)
var ONLY_TRANSCLUSION = /^\s*(?:\{\{[^{}]+\}\}|<\$transclude\b(?:[^>"']|"[^"]*"|'[^']*')*\/>)\s*$/,
	AWAKE_CLASS = "rr-ol-awake",
	MARKER_TIDDLER = "$:/plugins/rimir/outline/ui/transclusion-marker",
	EMPTY_HINT = "$:/plugins/rimir/outline/language/block/empty-hint",
	EMPTY_IDLE_HINT = "$:/plugins/rimir/outline/language/block/empty-idle-hint",
	LIST_TAGS = {ul: true, ol: true, dl: true, blockquote: true},
	// Kinds whose widgets may contain further units
	DESCEND_KINDS = {list: true, item: true, container: true},
	// A <span> directly inside these is invalid HTML: the marker goes into their first cell/item
	MARKER_INTO = {ul: "li", ol: "li", dl: "dt dd", table: "td th"};

var OutlineWidget = function(parseTreeNode, options) {
	this.initialise(parseTreeNode, options);
};

OutlineWidget.prototype = new Widget();

// Selection, keys and structural operations: select, step, operate, applyResult, handleKeydown, handleClick
keys.install(OutlineWidget.prototype);
// In-place editor: startEdit, saveEdit, cancelEdit, reattachEditor, handleEditorKeydown, openTarget
editor.install(OutlineWidget.prototype);
// Block menu (Alt-Enter): openMenu, closeMenu, handleMenuKeydown
menu.install(OutlineWidget.prototype);
undo.install(OutlineWidget.prototype);
// System clipboard (copy, cut, paste events): handleCopy, handleCut, handlePaste
clipboard.install(OutlineWidget.prototype);
overlay.install(OutlineWidget.prototype);

OutlineWidget.prototype.render = function(parent, nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();
	var domNode = this.document.createElement("div");
	domNode.className = "rr-ol";
	domNode.setAttribute("data-ol-tiddler", this.tiddlerTitle);
	var self = this;
	domNode.addEventListener("keydown", function(event) { self.handleKeydown(event); }, false);
	domNode.addEventListener("click", function(event) { self.handleClick(event); }, false);
	domNode.addEventListener("dblclick", function(event) { self.handleDblClick(event); }, false);
	domNode.addEventListener("copy", function(event) { self.handleCopy(event); }, false);
	domNode.addEventListener("cut", function(event) { self.handleCut(event); }, false);
	domNode.addEventListener("paste", function(event) { self.handlePaste(event); }, false);
	// The block menu closes when the focus leaves the outline
	domNode.addEventListener("focusout", function(event) {
		if(!event.relatedTarget || !domNode.contains(event.relatedTarget)) {
			self.closeMenu();
		}
	}, false);
	parent.insertBefore(domNode, nextSibling);
	this.renderChildren(domNode, null);
	this.domNodes.push(domNode);
	this.domNode = domNode;
	// Idle until woken (Ctrl-Click), unless this tiddler is being worked on (a re-render, another view)
	if(this.wakesItself()) {
		this.wake();
	} else {
		this.showEmptyHint();
	}
};

// True when the tiddler has a selection or an open edit (their temp tiddlers): a new widget of it starts awake
OutlineWidget.prototype.wakesItself = function() {
	return this.wiki.tiddlerExists(this.selectionTitle()) || this.wiki.tiddlerExists(this.bufferTitle());
};

/*
Wake the outline: map and stamp the units, take keyboard focus (tabindex), watch the layout and mousedowns outside
the tiddler (they put it to sleep). Returns true when it woke, false when it already was awake.
*/
OutlineWidget.prototype.wake = function() {
	if(this.awake) {
		return false;
	}
	var self = this,
		domNode = this.domNode,
		view = this.document.defaultView;
	this.awake = true;
	dom.setClass(domNode, AWAKE_CLASS, true);
	domNode.setAttribute("tabindex", "0");
	this.mapUnits();
	// Layout changes (window width, images, the editor) move the item selection frame
	if($tw.browser && view && view.ResizeObserver) {
		this.resizeObserver = new view.ResizeObserver(function() { self.drawSelectionBox(); });
		this.resizeObserver.observe(domNode);
	}
	if($tw.browser && this.document.addEventListener) {
		this.outsideListener = function(event) {
			if(!self.ownsTarget(event.target)) {
				self.sleep();
			}
		};
		this.document.addEventListener("mousedown", this.outsideListener, true);
	}
	return true;
};

/*
Back to idle: no stamps, markers, selection, menu, key overview or empty hint; no focus stop. Refused (false) while
an editor is open.
*/
OutlineWidget.prototype.sleep = function() {
	if(!this.awake || this.editor) {
		return false;
	}
	// The outline inside an overlay does not sleep on its own: its overlay closes (outline-overlay.js)
	var host = this.overlayHost();
	if(host) {
		return host.closeOverlay();
	}
	// Not while an editor is open in this outline's overlay either
	if(this.overlayBusy()) {
		return false;
	}
	this.closeOverlay();
	this.closeMenu();
	this.stopWatching();
	this.clearStamps();
	this.showSelection(-1);
	this.units = [];
	this.awake = false;
	this.showEmptyHint();
	this.wiki.deleteTiddler(this.selectionTitle());
	this.wiki.deleteTiddler(this.helpTitle());
	dom.setClass(this.domNode, AWAKE_CLASS, false);
	this.domNode.removeAttribute("tabindex");
	return true;
};

/*
True when `node` is in a view of this outline's tiddler: in an outline of the same tiddler (this one or another view
of it, which shares the selection) or in the frame around one (its ? button and key overview).
*/
OutlineWidget.prototype.ownsTarget = function(node) {
	var title = this.tiddlerTitle,
		host = this.overlayHost();
	// This outline's overlay is its own; the outline inside an overlay owns its whole overlay (title bar too)
	if(this.inOverlay(node) || (host && host.inOverlay(node))) {
		return true;
	}
	for(var n = node; n && n.getAttribute; n = n.parentNode) {
		var classes = " " + (n.getAttribute("class") || "") + " ";
		if(classes.indexOf(" rr-ol ") !== -1) {
			return n.getAttribute("data-ol-tiddler") === title;
		}
		if(classes.indexOf(" rr-ol-frame ") !== -1) {
			var own = firstOutline(n);
			return !!own && own.getAttribute("data-ol-tiddler") === title;
		}
	}
	return false;
};

// The first .rr-ol element below `node` (document order), or null
function firstOutline(node) {
	var children = node.children || [];
	for(var i = 0; i < children.length; i++) {
		var child = children[i];
		if(child.getAttribute && (" " + (child.getAttribute("class") || "") + " ").indexOf(" rr-ol ") !== -1) {
			return child;
		}
		var found = firstOutline(child);
		if(found) {
			return found;
		}
	}
	return null;
}

// Stop the layout observer and the outside mousedown listener of an awake outline
OutlineWidget.prototype.stopWatching = function() {
	if(this.resizeObserver) {
		this.resizeObserver.disconnect();
		this.resizeObserver = null;
	}
	if(this.outsideListener) {
		this.document.removeEventListener("mousedown", this.outsideListener, true);
		this.outsideListener = null;
	}
};

OutlineWidget.prototype.execute = function() {
	this.tiddlerTitle = this.getAttribute("tiddler", this.getVariable("currentTiddler"));
	this.model = null;
	this.units = [];
	this.markers = [];
	this.selectedId = -1;
	// The other end of a range of siblings (Shift-Up/Down, Shift-Click), -1 for a single unit (see rangeIds)
	this.rangeAnchor = -1;
	this.selectedNodes = [];
	this.selectionBox = null;
	this.menu = null;
	this.editor = null;
	this.pendingContinue = null;
	this.markerHtml = null;
	this.lastWritten = null;
	this.undoGroupState = null;
	this.emptyHint = null;
	this.awake = false;
	this.resizeObserver = null;
	this.outsideListener = null;
	this.makeChildWidgets();
};

OutlineWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if(changedAttributes.tiddler) {
		// The re-render does not destroy this widget: let go of what the awake outline holds first (quietly: no
		// selection is written for the old tiddler)
		this.closeOverlay(true, true);
		this.closeMenu();
		this.releaseEditor();
		this.stopWatching();
		this.refreshSelf();
		return true;
	}
	if(changedTiddlers[MARKER_TIDDLER]) {
		this.markerHtml = null;
	}
	var refreshed = this.refreshChildren(changedTiddlers);
	if(!this.awake) {
		// Another view of this tiddler started working on it (selection, edit): this one wakes too
		if((changedTiddlers[this.selectionTitle()] || changedTiddlers[this.bufferTitle()]) && this.wakesItself()) {
			this.wake();
		} else if(refreshed || changedTiddlers[this.tiddlerTitle]) {
			this.showEmptyHint();
		}
		return refreshed;
	}
	if(this.editor && this.editor.widget) {
		this.editor.widget.refresh(changedTiddlers);
	}
	// The overlay is outside the children too (outline-overlay.js)
	if(this.overlay) {
		this.overlay.widget.refresh(changedTiddlers);
	}
	if(refreshed || changedTiddlers[this.tiddlerTitle]) {
		this.mapUnits();
	} else if(changedTiddlers[this.selectionTitle()]) {
		this.restoreSelection();
	}
	return refreshed;
};

/*
Remove the editor (it is not part of the children). A changed buffer is kept and reopened by the next widget of
this tiddler (an ancestor re-render destroys this widget); an unchanged one is discarded (releaseEditor).
*/
OutlineWidget.prototype.destroy = function(options) {
	// The outline of a closing overlay leaves like a closed tiddler (its state is its own, see stateTitle)
	var leaving = this.closingOverlay || this.leftStory();
	this.closeOverlay(true);
	this.stopWatching();
	this.closeMenu();
	// A forced close of an overlay with an open editor keeps that edit (like an edit over a re-render)
	var keepEdit = this.closingOverlay && !!this.editor;
	if(keepEdit) {
		this.releaseEditor();
	}
	if(leaving) {
		// Closed (any way: close, close all, close others, a changed story list): forget its outline state, also a
		// changed edit; a reopened tiddler starts idle
		if(this.editor) {
			this.closeEditor(true);
		}
		var wiki = this.wiki;
		$tw.utils.each([this.selectionTitle(), keepEdit ? null : this.bufferTitle(), this.helpTitle()], function(title) {
			if(title && wiki.tiddlerExists(title)) {
				wiki.deleteTiddler(title);
			}
		});
	} else if(!keepEdit) {
		this.releaseEditor();
	}
	Widget.prototype.destroy.call(this, options);
};

// True when this outline is in a story river (tv-story-list) whose list no longer has its tiddler
OutlineWidget.prototype.leftStory = function() {
	var story = this.getVariable("tv-story-list");
	return !!story && this.wiki.getTiddlerList(story).indexOf(this.tiddlerTitle) === -1;
};

/*
Re-render the children into the same container (keeps the focus) and remap. Used when the text changed
before the change was rendered.
*/
OutlineWidget.prototype.rebuild = function() {
	this.clearStamps();
	this.showSelection(-1);
	$tw.utils.each(this.children, function(child) {
		child.destroy({removeDOMNodes: true});
	});
	this.makeChildWidgets();
	this.renderChildren(this.domNode, null);
	if(this.awake) {
		this.mapUnits();
	}
};

/*
Rebuild the model (when the text changed), match units to widgets, stamp the DOM nodes and
add the transclusion markers. Fills this.model and this.units.
*/
OutlineWidget.prototype.mapUnits = function() {
	this.updateModel();
	this.clearStamps();
	var units = this.model.units,
		domNodes = this.matchUnits(),
		self = this;
	this.units = units.map(function(unit) {
		return {unit: unit, domNodes: domNodes[unit.id] || []};
	});
	$tw.utils.each(this.units, function(entry) {
		self.stamp(entry);
	});
	this.mapDiagrams();
	this.restoreSelection();
	this.placeOverlay();
	this.showEmptyHint();
	this.reattachEditor();
};

// Rebuild this.model when the tiddler text changed
OutlineWidget.prototype.updateModel = function() {
	var text = this.wiki.getTiddlerText(this.tiddlerTitle, "");
	if(!this.model || this.model.text !== text) {
		this.model = buildModel(this.wiki, text, this.tiddlerTitle);
	}
	return this.model;
};

/*
A tiddler without units (empty, or only whitespace and comments) has nothing to select. Awake, a hint says that Enter
writes a first paragraph and Alt-Enter offers the block types. Idle, a hint says to Ctrl-Click it: without it the
outline has no height and nothing to click. Not part of the body's widget tree; hidden while editing.
*/
OutlineWidget.prototype.showEmptyHint = function() {
	var show = !this.isReadOnly() && !!this.getAdapter() &&
			(this.awake ? !this.hasSelectable() : this.updateModel().units.length === 0),
		text = show ? this.wiki.getTiddlerText(this.awake ? EMPTY_HINT : EMPTY_IDLE_HINT, "") : null;
	if(this.emptyHint && this.emptyHintText !== text) {
		if(this.emptyHint.parentNode) {
			this.emptyHint.parentNode.removeChild(this.emptyHint);
		}
		this.emptyHint = null;
	}
	if(show && !this.emptyHint) {
		this.emptyHint = this.document.createElement("div");
		this.emptyHint.className = "rr-ol-empty";
		this.emptyHint.appendChild(this.document.createTextNode(text));
		this.domNode.appendChild(this.emptyHint);
	}
	this.emptyHintText = this.emptyHint ? text : null;
};

// Remove stamps and markers of the previous mapping (DOM nodes that were not re-rendered keep them otherwise)
OutlineWidget.prototype.clearStamps = function() {
	$tw.utils.each(this.units, function(entry) {
		$tw.utils.each(entry.domNodes, function(node) {
			node.removeAttribute("data-ol-id");
			node.removeAttribute("data-ol-kind");
			node.removeAttribute("data-ol-start");
			node.removeAttribute("data-ol-type");
			node.removeAttribute("data-ol-typed");
			node.removeAttribute("data-ol-only-transclusion");
		});
	});
	$tw.utils.each(this.markers, function(marker) {
		if(marker.parentNode) {
			marker.parentNode.removeChild(marker);
		}
	});
	this.markers = [];
	$tw.utils.each(this.diagrams, function(d) {
		d.node.removeAttribute("data-ol-diagram-target");
		d.node.removeAttribute("data-ol-diagram");
	});
	this.diagrams = [];
};

/*
Diagram transclusions: transclude widgets below the body whose target tiddler is of a registered typed block type's
content type (block-types.js), inline inside a unit ({{...}} in a list item) or a block-level transclusion unit. Their
first element gets data-ol-diagram-target (and, for a transclusion unit itself, data-ol-diagram). They are no units of
their own. Only the host's own content is searched: a diagram inside another transcluded tiddler belongs to that one. Fills this.diagrams = [{title, node, id}] (id: the unit whose element contains it).
*/
OutlineWidget.prototype.mapDiagrams = function() {
	var self = this,
		wiki = this.wiki,
		body = this.findBodyTransclude(this),
		types = blockTypes.getBlockTypes(wiki);
	this.diagrams = [];
	if(!body || !types.some(function(t) { return t.behaviour === "typed"; })) {
		return;
	}
	function walk(widget) {
		$tw.utils.each(widget.children, function(child) {
			// Only the whole tiddler (or its text field): a field or an index of a diagram tiddler is not a diagram
			var whole = !child.transcludeIndex && (!child.transcludeField || child.transcludeField === "text"),
				title = child.parseTreeNode && child.parseTreeNode.type === "transclude" && !child.transcludeVariable && whole ?
					child.transcludeTitle : null,
				tiddler = title && wiki.getTiddler(title),
				node = tiddler && blockTypes.typeForContentType(wiki, tiddler.fields.type) ? elementNodes(child)[0] : null;
			if(node) {
				var owner = node;
				while(owner && !(owner.getAttribute && owner.getAttribute("data-ol-id") !== null && owner.getAttribute("data-ol-id") !== undefined)) {
					owner = owner.parentNode;
				}
				if(owner && owner !== self.domNode) {
					node.setAttribute("data-ol-diagram-target", title);
					if(owner === node) {
						node.setAttribute("data-ol-diagram", "yes");
					}
					self.diagrams.push({title: title, node: node, id: parseInt(owner.getAttribute("data-ol-id"), 10)});
				}
			} else if(!isForeign(child, self.tiddlerTitle)) {
				walk(child);
			}
		});
	}
	walk(body);
};

// Diagram transclusions inside unit `id` (see mapDiagrams): [{title, node}]
OutlineWidget.prototype.diagramTargets = function(id) {
	return (this.diagrams || []).filter(function(d) { return d.id === id; }).map(function(d) {
		return {title: d.title, node: d.node};
	});
};

OutlineWidget.prototype.stamp = function(entry) {
	var unit = entry.unit;
	$tw.utils.each(entry.domNodes, function(node) {
		node.setAttribute("data-ol-id", unit.id);
		node.setAttribute("data-ol-kind", unit.kind);
		node.setAttribute("data-ol-start", unit.start);
	});
	// The type badge (CSS, when on) goes on the first node only; a registered typed block ($$$type) shows its type's
	// badge and is marked data-ol-typed (placed like a code block's badge)
	if(entry.domNodes.length) {
		var adapter = this.getAdapter(),
			typed = adapter && adapter.typedBlockType ? adapter.typedBlockType(this.model.text, unit, blockTypes.getBlockTypes(this.wiki)) : null;
		entry.domNodes[0].setAttribute("data-ol-type", typed ? typed.badge : dom.unitType(unit.kind, entry.domNodes[0]));
		if(typed) {
			entry.domNodes[0].setAttribute("data-ol-typed", "yes");
		}
		// A list item whose content is only a transclusion: another tiddler's content, framed like a transclusion
		if(unit.kind === "item" && adapter && ONLY_TRANSCLUSION.test(adapter.editSource(this.model.text, this.model, unit.id))) {
			entry.domNodes[0].setAttribute("data-ol-only-transclusion", "yes");
		}
	}
	if(unit.kind === "transclusion" && entry.domNodes.length) {
		this.addMarker(entry.domNodes[0], unit.target);
	}
};

OutlineWidget.prototype.addMarker = function(node, target) {
	var marker = this.document.createElement("span");
	marker.className = "rr-ol-tmark";
	marker.setAttribute("title", target);
	marker.setAttribute("data-ol-target", target);
	if(this.markerHtml === null) {
		this.markerHtml = this.wiki.renderTiddler("text/html", MARKER_TIDDLER, {parseAsInline: true});
	}
	marker.innerHTML = this.markerHtml;
	markerParent(node).appendChild(marker);
	this.markers.push(marker);
};

// The element that takes the marker: the node itself, or for lists and tables their first item/cell
function markerParent(node) {
	var into = MARKER_INTO[(node.tagName || "").toLowerCase()];
	return (into && firstDescendant(node, into.split(" "))) || node;
}

function firstDescendant(node, tags) {
	var children = node.childNodes || [];
	for(var i = 0; i < children.length; i++) {
		var child = children[i];
		if(child.nodeType !== 1) {
			continue;
		}
		if(tags.indexOf((child.tagName || "").toLowerCase()) !== -1) {
			return child;
		}
		var found = firstDescendant(child, tags);
		if(found) {
			return found;
		}
	}
	return null;
}

/*
Walk the widget tree below the body transclusion of the tiddler and return {unitId: [Element]}.
*/
OutlineWidget.prototype.matchUnits = function() {
	var self = this,
		text = this.model.text,
		result = {},
		used = {},
		byAnchor = {};
	$tw.utils.each(this.model.units, function(unit) {
		var anchor = unitAnchor(text, unit);
		(byAnchor[anchor] = byAnchor[anchor] || []).push(unit);
	});
	var body = this.findBodyTransclude(this);
	if(!body) {
		return result;
	}
	var lastStart = 0;
	function walk(widget) {
		$tw.utils.each(widget.children, function(child) {
			var unit = self.matchWidget(child, byAnchor, used) || self.matchOverride(child, used, lastStart);
			if(unit) {
				used[unit.id] = true;
				lastStart = unit.start;
				result[unit.id] = elementNodes(child);
				if(DESCEND_KINDS[unit.kind]) {
					walk(child);
				}
			} else if(!isForeign(child, self.tiddlerTitle)) {
				walk(child);
			}
		});
	}
	walk(body);
	return result;
};

/*
A core widget overridden by a custom widget definition (for example `\widget $codeblock` of a plugin) is built as a
transclude of the variable "$<type>" without source positions. The walk is in document order, so it stands for the
next unmatched unit of that type at or after the last matched one. Its rendered elements become the unit's nodes;
its inside stays opaque.
*/
OutlineWidget.prototype.matchOverride = function(widget, used, after) {
	var node = widget.parseTreeNode,
		name = widget.transcludeVariable;
	if(!node || node.type !== "transclude" || !name || name.charAt(0) !== "$" || name.length < 2) {
		return null;
	}
	var type = name.substring(1),
		units = this.model.units;
	for(var i = 0; i < units.length; i++) {
		if(!used[units[i].id] && units[i].tag === type && units[i].start >= after) {
			return units[i];
		}
	}
	return null;
};

// First descendant transclude widget that renders this tiddler
OutlineWidget.prototype.findBodyTransclude = function(widget) {
	for(var i = 0; i < widget.children.length; i++) {
		var child = widget.children[i];
		if(child.parseTreeNode && child.parseTreeNode.type === "transclude" &&
			!child.transcludeVariable && child.transcludeTitle === this.tiddlerTitle && rendersText(child)) {
			return child;
		}
		var found = this.findBodyTransclude(child);
		if(found) {
			return found;
		}
	}
	return null;
};

OutlineWidget.prototype.matchWidget = function(widget, byAnchor, used) {
	var node = widget.parseTreeNode;
	if(!node || typeof node.start !== "number") {
		return null;
	}
	var tag = node.type === "element" ? node.tag : node.type,
		candidates = (byAnchor[node.start] || []).filter(function(unit) {
			return !used[unit.id] && unit.tag === tag;
		});
	if(!candidates.length || isSyntheticItem(node)) {
		return null;
	}
	// Tie-breaker: same end (the model trims trailing line breaks, so compare trimmed)
	for(var i = 0; i < candidates.length; i++) {
		if(candidates[i].end === node.end || candidates[i].end === trimEnd(this.model.text, node.start, node.end)) {
			return candidates[i];
		}
	}
	return candidates[0];
};

// Where the parser starts the node of a unit: $$$ typed blocks start after their header line
function unitAnchor(text, unit) {
	if(unit.kind === "block" && text.substr(unit.start, 3) === "$$$") {
		var nl = text.indexOf("\n", unit.start);
		if(nl !== -1) {
			return nl + 1;
		}
	}
	return unit.start;
}

function trimEnd(text, start, end) {
	end = Math.min(end, text.length);
	while(end > start && (text.charAt(end - 1) === "\n" || text.charAt(end - 1) === "\r")) {
		end--;
	}
	return end;
}

// Skipped list levels produce an item that only holds a deeper list starting at the same position
function isSyntheticItem(node) {
	var first = node.children && node.children[0];
	return node.type === "element" && !!first && first.type === "element" &&
		LIST_TAGS[first.tag] && first.start === node.start;
}

/*
A transclude widget of another tiddler, of a variable, or of another field or an index of this tiddler: its
positions refer to another text
*/
function isForeign(widget, title) {
	var node = widget.parseTreeNode;
	return !!node && node.type === "transclude" &&
		(!!widget.transcludeVariable || widget.transcludeTitle !== title || !rendersText(widget));
}

// True when a transclude widget renders the text field (no other field, no index)
function rendersText(widget) {
	return (!widget.transcludeField || widget.transcludeField === "text") && !widget.transcludeIndex;
}

// The widget's own element nodes, or for DOM-less widgets the top-level element nodes of its descendants
function elementNodes(widget) {
	var own = (widget.domNodes || []).filter(isElement);
	if(own.length || (widget.domNodes || []).length) {
		return own;
	}
	var out = [];
	$tw.utils.each(widget.children, function(child) {
		out.push.apply(out, elementNodes(child));
	});
	return out;
}

function isElement(node) {
	return !!node && node.nodeType === 1;
}

exports.outline = OutlineWidget;
