title: $:/plugins/rimir/outline/test/fixtures.js
type: application/javascript
module-type: library

Fixture notes and invariant helpers for the outline specs.

\*/
"use strict";

var NOTES = {};

// Plain nested lists, 3+ deep, with a trailing newline
NOTES.nestedLists = [
	"! Shopping",
	"",
	"* Fruit",
	"** Apples",
	"*** Granny Smith",
	"*** Braeburn",
	"**** from the local market",
	"** Pears",
	"* Vegetables",
	"** Carrots",
	"* Dairy",
	""
].join("\n");

// Mixed list markers: * and # and ; : and >
NOTES.mixedMarkers = [
	"* Setup",
	"*# install the package",
	"*# configure the wiki",
	"*#* check the port",
	"* Terms",
	"; Outline",
	": a tree of blocks",
	"; Unit",
	": one selectable piece",
	"",
	"> quoted line one",
	"> quoted line two",
	"",
	"# first",
	"#* inner bullet",
	"# second",
	""
].join("\n");

// Headings ! to !!! with paragraphs and lists inside the sections
NOTES.headings = [
	"! Project",
	"",
	"Intro paragraph for the project.",
	"",
	"!! Goals",
	"",
	"* Ship the plugin",
	"* Write the docs",
	"",
	"!!! Details",
	"",
	"A detail paragraph",
	"spanning two lines.",
	"",
	"* Detail item",
	"** Nested detail",
	"",
	"!! Risks",
	"",
	"Some risks are listed here.",
	"",
	"! Appendix",
	"",
	"Closing words.",
	""
].join("\n");

// Code block, table, {{X}} and {{X||T}} lines, macro line, $list block
NOTES.blocks = [
	"! Reference",
	"",
	"```js",
	"var x = 1;",
	"```",
	"",
	"|!Name |!Value |",
	"|alpha |1 |",
	"|beta |2 |",
	"",
	"{{Some Tiddler}}",
	"",
	"{{Some Tiddler||Some Template}}",
	"",
	"<<my-macro arg>>",
	"",
	"<$list filter=\"[tag[Task]]\">",
	"",
	"<$text text=<<currentTiddler>>/>",
	"",
	"</$list>",
	"",
	"After the blocks.",
	""
].join("\n");

// <div> container holding blocks
NOTES.container = [
	"Before the container.",
	"",
	"<div class=\"box\">",
	"",
	"! Inside heading",
	"",
	"* inside item one",
	"* inside item two",
	"",
	"Inside paragraph.",
	"",
	"</div>",
	"",
	"* after item",
	""
].join("\n");

// \procedure pragma at the top
NOTES.procedure = [
	"\\procedure greet(name)",
	"Hello <<name>>",
	"\\end",
	"",
	"! Greetings",
	"",
	"* <<greet World>>",
	"** nested after pragma",
	"* second",
	""
].join("\n");

// """ list item, item with class (*.cls), multi-line content
NOTES.specialItems = [
	"* normal item",
	"*.cls classed item",
	"** nested classed",
	"*.cls2 another classed item",
	"* \"\"\"multi",
	"line item\"\"\"",
	"* after the triple-quote item",
	"** its child",
	""
].join("\n");

// CRLF note (file from Windows)
NOTES.crlf = [
	"! Windows note",
	"",
	"* one",
	"** two",
	"*** three",
	"* four",
	"",
	"Final paragraph.",
	""
].join("\r\n");

// No trailing newline: last line is a list item
NOTES.noTrailingNewline = [
	"! Tail",
	"",
	"* first",
	"* last item without newline"
].join("\n");

// Headings and list items that skip levels
NOTES.mixedLevels = [
	"! P",
	"",
	"!!! c",
	"",
	"!! d",
	"",
	"* a",
	"*** c",
	"** d",
	""
].join("\n");

// Lists, a code block and a table followed by a paragraph after a single line break (no blank line)
NOTES.touchingBlocks = [
	"Intro line.",
	"",
	"* a",
	"* b",
	"Paragraph right after the list.",
	"",
	"```",
	"code",
	"```",
	"Paragraph right after the code block.",
	"",
	"|x |y |",
	"|1 |2 |",
	"Paragraph right after the table.",
	"",
	"# one",
	"# two",
	"Last paragraph.",
	""
].join("\n");

// Empty text and pragma-only text
NOTES.empty = "";
NOTES.pragmaOnly = "\\define m() x\n\\procedure p()\nbody\n\\end\n";

exports.NOTES = NOTES;

/*
Assert that, in `after`, the text before the smallest range start and after the largest
range end (mapped to the same lengths relative to the end of the text) is unchanged.
`ranges` are [[start,end]] in `before`. The tail is compared against the same
suffix of `before` that follows the largest end.
*/
exports.assertOnlyRangesChanged = function(before, after, ranges, expect) {
	// `expect` must be passed from the spec: Jasmine's global is not visible inside TW modules
	if(typeof expect !== "function") {
		throw new Error("assertOnlyRangesChanged: the expect argument is required");
	}
	var min = Infinity, max = -Infinity;
	(ranges || []).forEach(function(r) {
		if(r[0] < min) { min = r[0]; }
		if(r[1] > max) { max = r[1]; }
	});
	if(min === Infinity) {
		expect(after).toBe(before);
		return;
	}
	var prefix = before.substring(0, min),
		suffix = before.substring(max);
	expect(after.substring(0, min)).toBe(prefix);
	expect(after.length).not.toBeLessThan(prefix.length + suffix.length);
	expect(after.substring(after.length - suffix.length)).toBe(suffix);
};

/* Array of "kind:level:parent" per unit, for structure comparisons */
exports.unitSignature = function(model) {
	return model.units.map(function(u) {
		return u.kind + ":" + u.level + ":" + u.parent;
	});
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/outline/test/test-block-types.js":{"title":"$:/plugins/rimir/outline/test/test-block-types.js","text":"/*\
title: $:/plugins/rimir/outline/test/test-block-types.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for the block type registry (block-types.js): built-in shadows, types added by tagged tiddlers, broken types.

\*/
"use strict";

describe("outline block types", function() {

	var blockTypes = require("$:/plugins/rimir/outline/block-types.js"),
		TAG = "$:/tags/rimir/outline/BlockType",
		PLUGIN = "$:/plugins/rimir/outline";

	// A wiki with the outline plugin's shadow tiddlers and `tiddlers`
	function pluginWiki(tiddlers) {
		var wiki = new $tw.Wiki();
		wiki.addTiddler($tw.wiki.getTiddler(PLUGIN));
		wiki.readPluginInfo();
		wiki.registerPluginTiddlers("plugin");
		wiki.unpackPluginTiddlers();
		wiki.addTiddlers(tiddlers || []);
		return wiki;
	}

	function names(types) {
		return types.map(function(t) { return t.name; });
	}

	var OUTLINE = pluginWiki();

	var GRAPHVIZ = {title: "T/graphviz", tags: TAG, name: "graphviz", caption: "Graphviz graph", badge: "graphviz",
		behaviour: "typed", "content-type": "text/vnd.graphviz", starter: "digraph {}", contexts: "block item",
		inline: "transclude", docs: "https://graphviz.org/documentation/", "list-after": "$:/plugins/rimir/outline/blocktypes/code"};

	it("lists the built-ins in order with their badges", function() {
		var types = blockTypes.getBlockTypes(pluginWiki());
		expect(names(types)).toEqual(["paragraph", "heading1", "heading2", "heading3", "bulleted", "numbered", "quote", "quote-block", "code"]);
		expect(types.map(function(t) { return t.badge; })).toEqual(["paragraph", "h1", "h2", "h3", "bullet", "numbered", "quote", "quote", "code-block"]);
		expect(types.map(function(t) { return t.kind; })).toEqual(["block", "heading", "heading", "heading", "item", "item", "item", "block", "block"]);
		expect(blockTypes.getBlockType(OUTLINE, "heading2").make("a\nb", "\n")).toBe("!! a<br>b");
		expect(blockTypes.getBlockType(OUTLINE, "code").make("a\nb", "\n")).toBe("```\na\nb\n```");
		expect(blockTypes.getBlockType(OUTLINE, "numbered").make("x", "\n")).toBe("# x");
		expect(blockTypes.getBlockType(OUTLINE, "paragraph").make("x", "\n")).toBe("x");
		expect(blockTypes.getBlockType(OUTLINE, "paragraph").contexts).toEqual(["block"]);
		expect(blockTypes.getBlockType(OUTLINE, "heading1").singleLine).toBe(true);
		expect(blockTypes.getBlockType(OUTLINE, "code").singleLine).toBe(false);
	});

	it("takes the captions of the built-ins as labels", function() {
		expect(blockTypes.getBlockType(OUTLINE, "bulleted").caption).toBe("Bulleted list");
	});

	it("adds a type from a tagged tiddler", function() {
		var wiki = pluginWiki([GRAPHVIZ]),
			types = blockTypes.getBlockTypes(wiki),
			gv = types[types.length - 1];
		expect(gv.name).toBe("graphviz");
		expect(gv.contentType).toBe("text/vnd.graphviz");
		expect(gv.contexts).toEqual(["block", "item"]);
		expect(gv.inline).toBe("transclude");
		expect(gv.starter).toBe("digraph {}");
		expect(gv.docs).toBe("https://graphviz.org/documentation/");
		expect(gv.make("x", "\n")).toBe("$$$text/vnd.graphviz\nx\n$$$");
		expect(blockTypes.typeForContentType(wiki, "text/vnd.graphviz")).toBe(gv);
		expect(blockTypes.typeForContentType(wiki, "text/plain")).toBeNull();
		expect(blockTypes.getBlockType(wiki, "nope")).toBeNull();
	});

	it("skips broken types", function() {
		var wiki = pluginWiki([
			{title: "T/a", tags: TAG, name: "a", caption: "A", behaviour: "heading"},
			{title: "T/b", tags: TAG, name: "b", caption: "B", behaviour: "nope"},
			{title: "T/c", tags: TAG, name: "c", caption: "C", behaviour: "fenced", open: "<<<"},
			{title: "T/d", tags: TAG, caption: "D", behaviour: "paragraph"},
			{title: "T/e", tags: TAG, name: "e", caption: "E", behaviour: "typed"},
			// One marker character only: the level comes from repeating it
			{title: "T/f", tags: TAG, name: "f", caption: "F", behaviour: "item", marker: "**"},
			{title: "T/g", tags: TAG, name: "g", caption: "G", behaviour: "item", marker: "*#"}
		]);
		expect(names(blockTypes.getBlockTypes(wiki))).toEqual(["paragraph", "heading1", "heading2", "heading3", "bulleted", "numbered", "quote", "quote-block", "code"]);
	});

	it("finds a type by name and by content type in a list of types", function() {
		var types = blockTypes.getBlockTypes(pluginWiki([{title: "T/x", tags: TAG, name: "x", caption: "X", behaviour: "typed", "content-type": "text/x"}]));
		expect(blockTypes.byName(types, "x").caption).toBe("X");
		expect(blockTypes.byName(types, "nope")).toBe(null);
		expect(blockTypes.byContentType(types, "text/x").name).toBe("x");
		expect(blockTypes.byContentType(types, "text/vnd.tiddlywiki")).toBe(null);
	});

	it("follows changes of the type tiddlers", function() {
		var wiki = pluginWiki();
		expect(names(blockTypes.getBlockTypes(wiki)).indexOf("graphviz")).toBe(-1);
		wiki.addTiddler(GRAPHVIZ);
		expect(names(blockTypes.getBlockTypes(wiki)).indexOf("graphviz")).toBe(9);
		wiki.deleteTiddler(GRAPHVIZ.title);
		expect(names(blockTypes.getBlockTypes(wiki)).indexOf("graphviz")).toBe(-1);
	});
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/outline/test/test-clipboard.js":{"title":"$:/plugins/rimir/outline/test/test-clipboard.js","text":"/*\
title: $:/plugins/rimir/outline/test/test-clipboard.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for copy and paste in format-wikitext.js (outline clipboard: levels adapted to the paste place).

\*/
"use strict";

var model = require("$:/plugins/rimir/outline/model.js"),
	fmt = require("$:/plugins/rimir/outline/format-wikitext.js");

describe("outline clipboard", function() {

	function build(text) { return model.buildModel($tw.wiki, text); }
	function idOf(m, s, kind) {
		var all = m.units.filter(function(u) { return m.text.substring(u.start, u.end) === s && (!kind || u.kind === kind); });
		return all[all.length - 1].id;
	}
	// Copy unit `s` of `from`, paste it after unit `at` of `text` (null: the end, as in an empty tiddler)
	function paste(text, at, from, s, kinds) {
		kinds = kinds || {};
		var fm = build(from),
			clip = fmt.copy(from, fm, idOf(fm, s, kinds.from)),
			m = build(text);
		return fmt.paste(text, m, at === null ? -1 : idOf(m, at, kinds.at), clip, build(clip.source));
	}

	it("copy: the unit with its subtree, by kind", function() {
		var text = "! H\n\npara\n\n!! S\n\n* a\n** a1\n* b\n\n! I", m = build(text);
		expect(fmt.copy(text, m, idOf(m, "* a"))).toEqual({kind: "items", source: "* a\n** a1"});
		expect(fmt.copy(text, m, idOf(m, "* a\n** a1\n* b", "list"))).toEqual({kind: "items", source: "* a\n** a1\n* b"});
		expect(fmt.copy(text, m, idOf(m, "! H"))).toEqual({kind: "heading", source: "! H\n\npara\n\n!! S\n\n* a\n** a1\n* b"});
		expect(fmt.copy(text, m, idOf(m, "para"))).toEqual({kind: "block", source: "para"});
		expect(fmt.copy(text, m, 99)).toBeNull();
	});

	it("items after an item: its level, deeper items keep their extra marker characters", function() {
		var r = paste("# x\n## y\n# z", "## y", "* a\n** a1", "* a");
		expect(r.text).toBe("# x\n## y\n## a\n##* a1\n# z");
		expect(r.select).toBe(9);
		expect(r.kind).toBe("item");
		// After the item's whole subtree
		expect(paste("* x\n** x1\n* y", "* x", "* a", "* a").text).toBe("* x\n** x1\n* a\n* y");
	});

	it("items after a whole list: at its end, at its top level", function() {
		expect(paste("para\n\n# x\n# y", "# x\n# y", "* a\n** a1", "* a", {at: "list"}).text).toBe("para\n\n# x\n# y\n# a\n#* a1");
	});

	it("items after a heading or a block: a new list at level 1", function() {
		expect(paste("! H\n\npara", "! H", "#* a\n#** b", "#* a").text).toBe("! H\n\n* a\n** b\n\npara");
		expect(paste("para\n\nmore", "para", "#* a\n#** b", "#* a").text).toBe("para\n\n* a\n** b\n\nmore");
		// A whole list copied
		expect(paste("para", "para", "** a\n** b", "** a\n** b", {from: "list"}).text).toBe("para\n\n* a\n* b");
	});

	it("heading after a heading: after its section, at its level; sub-headings keep their distance", function() {
		var r = paste("! A\n\nx\n\n! B", "! A", "!! S\n\ny\n\n!!! T\n\nz", "!! S");
		expect(r.text).toBe("! A\n\nx\n\n! S\n\ny\n\n!! T\n\nz\n\n! B");
		expect(r.select).toBe(8);
		expect(r.kind).toBe("heading");
	});

	it("heading after a non-heading: one below the section's heading, levels stop at 6", function() {
		expect(paste("!!!!! A\n\npara", "para", "! S\n\n!! T", "! S").text).toBe("!!!!! A\n\npara\n\n!!!!!! S\n\n!!!!!! T");
		expect(paste("para", "para", "!!! S", "!!! S").text).toBe("para\n\n! S");
		expect(paste("!! A\n\n* a\n* b", "* a", "! S", "! S").text).toBe("!! A\n\n* a\n* b\n\n!!! S");
	});

	it("blocks: after the outermost list of an item, right below a heading line, after other blocks", function() {
		expect(paste("* a\n** a1\n* b\n\nend", "** a1", "hello", "hello").text).toBe("* a\n** a1\n* b\n\nhello\n\nend");
		expect(paste("! H\n\npara", "! H", "hello", "hello").text).toBe("! H\n\nhello\n\npara");
		expect(paste("para", "para", "hello", "hello").text).toBe("para\n\nhello");
		expect(paste("para", "para", "hello", "hello").kind).toBe("block");
	});

	it("only real markers and headings are rewritten (not lines in a code block)", function() {
		expect(paste("! A", "! A", "!! S\n\n```\n* x\n! y\n```", "!! S").text).toBe("! A\n\n! S\n\n```\n* x\n! y\n```");
	});

	it("line breaks follow the target text", function() {
		expect(paste("* a\r\n* b", "* a", "* n\n** m", "* n").text).toBe("* a\r\n* n\r\n** m\r\n* b");
	});

	it("empty tiddler: at the end, items at level 1, a heading at level 1", function() {
		expect(paste("", null, "** a", "** a").text).toBe("* a");
		expect(paste("", null, "!!! S", "!!! S").text).toBe("! S");
		expect(paste("<!-- c -->", null, "hello", "hello").text).toBe("<!-- c -->\n\nhello");
	});

	it("clipKind (plain text from outside): one list, one heading, else block", function() {
		expect(fmt.clipKind(build("* a\n** b\n* c"))).toBe("items");
		expect(fmt.clipKind(build("!! S\n\ntext\n\n* a"))).toBe("heading");
		expect(fmt.clipKind(build("para"))).toBe("block");
		expect(fmt.clipKind(build("* a\n\npara"))).toBe("block");
		expect(fmt.clipKind(build("para\n\n! H"))).toBe("block");
		// Outside plain text pasted with its kind: a list adapts to the item it lands after
		var cm = build("* n\n** m");
		expect(fmt.paste("# x\n# y", build("# x\n# y"), 1, {kind: fmt.clipKind(cm), source: cm.text}, cm).text)
			.toBe("# x\n# n\n#* m\n# y");
	});

	it("nothing to paste or no such unit: null", function() {
		var m = build("para");
		expect(fmt.paste("para", m, 0, null, null)).toBeNull();
		expect(fmt.paste("para", m, 5, {kind: "block", source: "x"}, build("x"))).toBeNull();
	});
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/outline/test/test-delete.js":{"title":"$:/plugins/rimir/outline/test/test-delete.js","text":"/*\
title: $:/plugins/rimir/outline/test/test-delete.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for deleteUnit, deleteCount, merge and itemBefore in format-wikitext.js, and their post-op guard.

\*/
"use strict";

var model = require("$:/plugins/rimir/outline/model.js"),
	fmt = require("$:/plugins/rimir/outline/format-wikitext.js"),
	fixtures = require("$:/plugins/rimir/outline/test/fixtures.js");

describe("outline delete and merge", function() {

	function build(text) { return model.buildModel($tw.wiki, text); }
	function idOf(m, s, kind) {
		var all = m.units.filter(function(u) { return m.text.substring(u.start, u.end) === s && (!kind || u.kind === kind); });
		return all[all.length - 1].id;
	}
	function del(text, s, mode, kind) {
		var m = build(text), id = idOf(m, s, kind), r = fmt.deleteUnit(text, m, id, mode);
		if(r) {
			expect(model.checkOp($tw.wiki, m, id, "deleteUnit", r.text, undefined, r)).withContext(s).toBe(true);
		}
		return r;
	}
	function merge(text, s, content) {
		var m = build(text), id = idOf(m, s), r = fmt.merge(text, m, id, content);
		if(r) {
			expect(model.checkOp($tw.wiki, m, id, "merge", r.text, undefined, r)).withContext(s).toBe(true);
		}
		return r;
	}

	it("deletes an item with its sub-items", function() {
		expect(del("* a\n* b\n** b1\n*** b2\n* c", "* b").text).toBe("* a\n* c");
		expect(del("* a\n* b\n** b1", "* b").text).toBe("* a");
		expect(del("* a\n** a1\n* b", "** a1").text).toBe("* a\n* b");
	});

	it("an only item takes its list along", function() {
		var r = del("para\n\n* only\n\nend", "* only", undefined, "item");
		expect(r.text).toBe("para\n\nend");
		expect(r.removed.length).toBe(2);
		var m = build("para\n\n* only\n\nend");
		expect(fmt.deleteCount(m, idOf(m, "* only", "item"))).toBe(1);
	});

	it("deletes a heading with its section, or only its line", function() {
		var t = "! A\n\nx\n\n!! B\n\ny\n\n! C\n\nz";
		expect(del(t, "! A").text).toBe("! C\n\nz");
		expect(del(t, "!! B").text).toBe("! A\n\nx\n\n! C\n\nz");
		// Only the heading: its section joins the one above
		expect(del(t, "!! B", "own").text).toBe("! A\n\nx\n\ny\n\n! C\n\nz");
		expect(del(t, "! A", "own").text).toBe("x\n\n!! B\n\ny\n\n! C\n\nz");
		var m = build(t);
		expect(fmt.deleteCount(m, idOf(m, "! A"))).toBe(3);
		expect(fmt.deleteCount(m, idOf(m, "! A"), "own")).toBe(0);
		// "own" is for headings only
		expect(fmt.deleteUnit(t, m, idOf(m, "x"), "own")).toBe(null);
	});

	it("an only child takes its container along", function() {
		var t = "p\n\n<div>\n\n! H\n\nx\n\n</div>\n\nend";
		var r = del(t, "! H");
		expect(r.text).toBe("p\n\nend");
		var m = build(t);
		expect(fmt.deleteCount(m, idOf(m, "! H"))).toBe(2);
		// Only the heading's line: the section keeps the container alive
		expect(del(t, "! H", "own").text).toBe("p\n\n<div>\n\nx\n\n</div>\n\nend");
	});

	it("deletes a whole list, a block, the last unit", function() {
		var t = "p1\n\n* a\n** a1\n* b\n\np2";
		var m = build(t), list = m.units.filter(function(u) { return u.kind === "list"; })[0];
		var r = fmt.deleteUnit(t, m, list.id);
		expect(r.text).toBe("p1\n\np2");
		expect(r.removed.length).toBe(4);
		expect(fmt.deleteCount(m, list.id)).toBe(3);
		expect(del(t, "p1").text).toBe("* a\n** a1\n* b\n\np2");
		expect(del(t, "p2").text).toBe("p1\n\n* a\n** a1\n* b");
		expect(del("p\n\n```\nc\n```\n", "```\nc\n```").text).toBe("p\n");
	});

	it("deletes every unit of the corpus with a guarded, plausible result", function() {
		var n = 0;
		Object.keys(fixtures.NOTES).forEach(function(k) {
			var t = fixtures.NOTES[k], m = build(t);
			m.units.forEach(function(u) {
				var r = fmt.deleteUnit(t, m, u.id);
				if(!r) { return; }
				n++;
				expect(r.text.length).toBeLessThan(t.length);
				expect(model.checkOp($tw.wiki, m, u.id, "deleteUnit", r.text, undefined, r)).withContext(k + " " + u.id).toBe(true);
			});
		});
		expect(n).toBeGreaterThan(20);
	});

	it("the guard refuses a delete that merges neighbours", function() {
		var t = "* a\n\npara\n\n* b", m = build(t), id = idOf(m, "para");
		// Removing the paragraph without a separator would merge the two lists into one
		expect(model.checkOp($tw.wiki, m, id, "deleteUnit", "* a\n* b", undefined, {removed: [id]})).toBe(false);
		expect(model.checkOp($tw.wiki, m, id, "deleteUnit", "* a\n\n* b", undefined, undefined)).toBe(false);
	});

	it("merges an item into the item above", function() {
		var r = merge("* a\n* b\n* c", "* b");
		expect(r.text).toBe("* ab\n* c");
		expect(r.caret).toBe(1);
		expect(r.select).toBe(0);
		// Into the parent, into the last sub-item of the previous sibling
		expect(merge("* a\n** b", "** b").text).toBe("* ab");
		expect(merge("* a\n** a1\n* b", "* b").text).toBe("* a\n** a1b");
		// Its sub-items keep their lines and levels
		expect(merge("* a\n* b\n** b1\n* c", "* b").text).toBe("* ab\n** b1\n* c");
		// Editor text instead of the current content; "" deletes the item; line breaks become <br>
		expect(merge("* a\n* b\n* c", "* b", "new").text).toBe("* anew\n* c");
		expect(merge("* a\n* b\n** b1", "* b", "").text).toBe("* a\n** b1");
		expect(merge("# a\n# b", "# b", "x\ny").text).toBe("# ax<br>y");
		// The caret goes to the end of the target's editor text
		expect(merge("* x<br>y\n* b", "* b").caret).toBe(3);
	});

	it("merge needs an item above in the same list", function() {
		// A blank line between items is still one list: it goes with the merge
		expect(merge("* a\n\n* b", "* b").text).toBe("* ab");
		var t = "* a\n\npara\n\n* b", m = build(t);
		// Two lists: b is the first item of its own list
		expect(fmt.mergeTarget(m, idOf(m, "* b"))).toBe(-1);
		expect(fmt.merge(t, m, idOf(m, "* b"))).toBe(null);
		m = build("para\n\n* a");
		expect(fmt.merge("para\n\n* a", m, idOf(m, "* a", "item"))).toBe(null);
		m = build("p");
		expect(fmt.mergeTarget(m, 0)).toBe(-1);
	});

	it("mergeSource: the item below that merges into an item (Delete at its end)", function() {
		var t = "* a\n* b\n** b1\n* c\n\npara\n\n* d", m = build(t);
		expect(fmt.mergeSource(m, idOf(m, "* a"))).toBe(idOf(m, "* b"));
		// An item with sub-items: its first sub-item
		expect(fmt.mergeSource(m, idOf(m, "* b"))).toBe(idOf(m, "** b1"));
		expect(fmt.mergeSource(m, idOf(m, "** b1"))).toBe(idOf(m, "* c"));
		// The last item of a list: the next list is another one
		expect(fmt.mergeSource(m, idOf(m, "* c"))).toBe(-1);
		expect(fmt.mergeSource(m, idOf(m, "* d"))).toBe(-1);
		expect(fmt.mergeSource(m, idOf(m, "para"))).toBe(-1);
	});

	it("splits an item: the rest goes to a new item right below", function() {
		function split(text, s, rest) {
			var m = build(text), id = idOf(m, s), r = fmt.split(text, m, id, rest);
			if(r) {
				expect(model.checkOp($tw.wiki, m, id, "split", r.text, undefined, r)).withContext(s).toBe(true);
			}
			return r;
		}
		var r = split("* ab\n* c", "* ab", "cd");
		expect(r.text).toBe("* ab\n* cd\n* c");
		expect(r.select).toBe(5);
		// With sub-items the new item becomes the first sub-item: they stay with the item
		expect(split("# a\n#* a1\n# b", "# a", "x").text).toBe("# a\n#* x\n#* a1\n# b");
		// Line breaks become <br>; nothing to split off: null
		expect(split("* a", "* a", "x\ny").text).toBe("* a\n* x<br>y");
		expect(split("* a", "* a", "  ")).toBe(null);
		var m = build("para");
		expect(fmt.split("para", m, 0, "x")).toBe(null);
		// The inverse of merge
		var t = "* one\n** a\n* two", s1 = split(t, "* one", "rest"), m1 = build(s1.text);
		var back = fmt.merge(s1.text, m1, idOf(m1, "** rest"));
		expect(back.text).toBe("* onerest\n** a\n* two");
	});

	it("itemBefore finds the item visually above a position", function() {
		var t = "* a\n** a1\n*** a2\n* b", m = build(t), a = idOf(m, "* a");
		expect(m.text.substring(m.units[fmt.itemBefore(m, a, m.units[a].subtreeEnd)].start).indexOf("*** a2")).toBe(0);
	});
	it("a heading or paragraph turned into a bullet joins a list next to it", function() {
		function conv(text, src, type) {
			var m = build(text);
			return fmt.convert(text, m, idOf(m, src), type);
		}
		expect(conv("! H\n* a\n* b", "! H", "bulleted").text).toBe("* H\n\n* a\n* b");
		expect(conv("! H\n\n* a", "! H", "numbered").text).toBe("# H\n\n* a");
		expect(conv("* z\n\npara\n\n* a", "para", "bulleted").text).toBe("* z\n\n* para\n\n* a");
		expect(conv("! H\n\npara", "! H", "bulleted").text).toBe("* H\n\npara");
	});
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/outline/test/test-edit.js":{"title":"$:/plugins/rimir/outline/test/test-edit.js","text":"/*\
title: $:/plugins/rimir/outline/test/test-edit.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for replace, insertNew, editSource and isMultiline in format-wikitext.js.

\*/
"use strict";

var model = require("$:/plugins/rimir/outline/model.js"),
	fmt = require("$:/plugins/rimir/outline/format-wikitext.js"),
	fixtures = require("$:/plugins/rimir/outline/test/fixtures.js");

describe("outline edit", function() {

	function build(text) { return model.buildModel($tw.wiki, text); }
	// Outline's own block types only: other plugins in the test wiki (graphviz, ...) add theirs
	var OWN = require("$:/plugins/rimir/outline/block-types.js").getBlockTypes($tw.wiki).filter(function(t) {
		return t.title.indexOf("$:/plugins/rimir/outline/blocktypes/") === 0;
	});
	function unit(m, pred) { return m.units.filter(pred)[0]; }
	function idOf(m, s) {
		// last match = innermost (a list and its only item can share a source)
		var all = m.units.filter(function(u) { return m.text.substring(u.start, u.end) === s; });
		return all[all.length - 1].id;
	}

	it("replace keeps rest", function() {
		var text = "* a\n** a1\n* b", m = build(text), u = m.units[idOf(m, "* a")],
			r = fmt.replace(text, m, u.id, "changed");
		expect(r.text).toBe("* changed\n** a1\n* b");
		expect(r.select).toBe(0);
		fixtures.assertOnlyRangesChanged(text, r.text, [[u.start, u.end]], expect);
	});

	it("editSource returns own source", function() {
		var text = "* a\n** a1\n* b", m = build(text);
		expect(fmt.editSource(text, m, idOf(m, "* a"))).toBe("a");
	});

	it("editor shows and replaces content only: item markers and heading prefixes stay", function() {
		var text = "! Head\n\n* a\n**#  deep\n;term\n:def\n\npara", m = build(text);
		expect(fmt.editSource(text, m, idOf(m, "! Head"))).toBe("Head");
		expect(fmt.editSource(text, m, idOf(m, "**#  deep"))).toBe("deep");
		expect(fmt.editSource(text, m, idOf(m, ";term"))).toBe("term");
		expect(fmt.editSource(text, m, idOf(m, "para"))).toBe("para");
		expect(fmt.replace(text, m, idOf(m, "! Head"), "New").text).toBe("! New\n\n* a\n**#  deep\n;term\n:def\n\npara");
		expect(fmt.replace(text, m, idOf(m, "**#  deep"), "x").text).toBe("! Head\n\n* a\n**#  x\n;term\n:def\n\npara");
		expect(fmt.replace(text, m, idOf(m, ":def"), "d2").text).toBe("! Head\n\n* a\n**#  deep\n;term\n:d2\n\npara");
		// Content that looks like markup stays content; the own marker typed out of habit is not doubled
		expect(fmt.replace(text, m, idOf(m, "* a"), "*bold*").text).toContain("\n* *bold*\n");
		expect(fmt.replace(text, m, idOf(m, "* a"), "* b").text).toContain("\n* b\n");
	});

	it("code blocks and <<< quotes: the editor leaves out their fence lines, they stay", function() {
		var text = "```js\nvar a;\nvar b;\n```\n\n<<<.cls\nsaid\n<<< Someone\n\n```\n```", m = build(text),
			code = idOf(m, "```js\nvar a;\nvar b;\n```"), q = idOf(m, "<<<.cls\nsaid\n<<< Someone");
		expect(fmt.editSource(text, m, code)).toBe("var a;\nvar b;");
		expect(fmt.editSource(text, m, q)).toBe("said");
		expect(fmt.editSource(text, m, idOf(m, "```\n```"))).toBe("");
		expect(fmt.replace(text, m, code, "x()").text).toBe("```js\nx()\n```\n\n<<<.cls\nsaid\n<<< Someone\n\n```\n```");
		expect(fmt.replace(text, m, q, "one\ntwo").text).toBe("```js\nvar a;\nvar b;\n```\n\n<<<.cls\none\ntwo\n<<< Someone\n\n```\n```");
		// CRLF text: the inserted line breaks follow it
		var crlf = "```\r\na\r\n```", cm = build(crlf);
		expect(fmt.editSource(crlf, cm, 0)).toBe("a");
		expect(fmt.replace(crlf, cm, 0, "b\r\nc").text).toBe("```\r\nb\r\nc\r\n```");
	});

	it("a whole > quote: the editor shows its lines without their first >, saving puts it back", function() {
		var text = "para\n\n> q1\n>> deeper\n>* item\n> q2\n\nend", m = build(text),
			list = unit(m, function(u) { return u.kind === "list"; }).id;
		expect(fmt.editSource(text, m, list)).toBe("q1\n> deeper\n* item\nq2");
		expect(fmt.replace(text, m, list, "q1\n> deeper\n\nnew\n* item").text)
			.toBe("para\n\n> q1\n>> deeper\n> new\n>* item\n\nend");
		// Unchanged: the same source
		expect(fmt.replace(text, m, list, fmt.editSource(text, m, list)).text).toBe(text);
	});

	it("line breaks in items and headings are stored as <br>, shown as line breaks", function() {
		var text = "! H\n\n* a\n** a1\n* b\n\npara", m = build(text);
		var r = fmt.replace(text, m, idOf(m, "* a"), "a\nsecond\r\nthird");
		expect(r.text).toBe("! H\n\n* a<br>second<br>third\n** a1\n* b\n\npara");
		// The list keeps its structure
		var m2 = build(r.text);
		expect(m2.units.length).toBe(m.units.length);
		expect(fmt.editSource(r.text, m2, idOf(m2, "* a<br>second<br>third"))).toBe("a\nsecond\nthird");
		expect(fmt.editSource("* x<br/>y<BR />z", build("* x<br/>y<BR />z"), 1)).toBe("x\ny\nz");
		// Headings too; leading/trailing line breaks are dropped
		expect(fmt.replace(text, m, idOf(m, "! H"), "H\nsub\n").text).toBe("! H<br>sub\n\n* a\n** a1\n* b\n\npara");
		// A new item
		expect(fmt.insertNew(text, m, idOf(m, "* b"), "n1\nn2").text).toBe("! H\n\n* a\n** a1\n* b\n* n1<br>n2\n\npara");
		// Paragraphs keep real line breaks
		expect(fmt.replace(text, m, idOf(m, "para"), "p1\np2").text).toBe("! H\n\n* a\n** a1\n* b\n\np1\np2");
		// Single-line units: Enter stays save-and-continue
		expect(fmt.isMultiline(m2, idOf(m2, "* a<br>second<br>third"))).toBe(false);
	});

	describe("insertBlock", function() {
		it("after a block, a list or a heading's section", function() {
			var text = "! H\n\npara\n\n* a\n** a1\n\n! I", m = build(text);
			expect(fmt.insertBlock(text, m, idOf(m, "para"), "heading2", "New", "after", OWN).text).toBe("! H\n\npara\n\n!! New\n\n* a\n** a1\n\n! I");
			var list = m.units.filter(function(u) { return u.kind === "list"; })[0].id;
			expect(fmt.insertBlock(text, m, list, "paragraph", "p2", "after", OWN).text).toBe("! H\n\npara\n\n* a\n** a1\n\np2\n\n! I");
			// A heading: a new heading goes after its whole section, other blocks right after the heading line
			expect(fmt.insertBlock(text, m, idOf(m, "! H"), "heading1", "G", "after", OWN).text).toBe("! H\n\npara\n\n* a\n** a1\n\n! G\n\n! I");
			expect(fmt.insertBlock(text, m, idOf(m, "! H"), "bulleted", "first", "after", OWN).text).toBe("! H\n\n* first\n\npara\n\n* a\n** a1\n\n! I");
			var r = fmt.insertBlock(text, m, idOf(m, "! I"), "code", "x\ny", "after", OWN);
			expect(r.text).toBe(text + "\n\n```\nx\ny\n```");
			expect(r.select).toBe(text.length + 2);
			expect(r.kind).toBe("block");
			expect(fmt.insertBlock(text, m, idOf(m, "para"), "numbered", "n1\nn2", "after", OWN).text).toContain("\n\n# n1<br>n2\n\n");
			expect(fmt.insertBlock(text, m, idOf(m, "para"), "quote", "q", "after", OWN).kind).toBe("item");
			// Blank content: nothing
			expect(fmt.insertBlock(text, m, idOf(m, "para"), "paragraph", "  ", "after", OWN)).toBeNull();
		});
		it("at a list item: an item type inserts a sibling, other types go before or after the whole list", function() {
			var text = "para\n\n* a\n** a1\n* b\n\nend", m = build(text);
			var r = fmt.insertBlock(text, m, idOf(m, "* a"), "bulleted", "new", "before", OWN);
			expect(r.text).toBe("para\n\n* new\n* a\n** a1\n* b\n\nend");
			expect(r.select).toBe(6);
			expect(r.kind).toBe("item");
			expect(fmt.insertBlock(text, m, idOf(m, "* a"), "bulleted", "new", "after", OWN).text).toBe("para\n\n* a\n** a1\n* new\n* b\n\nend");
			// The item's own level: a numbered sibling of a sub-item keeps the parent's marker
			expect(fmt.insertBlock(text, m, idOf(m, "** a1"), "numbered", "n", "after", OWN).text).toBe("para\n\n* a\n** a1\n*# n\n* b\n\nend");
			expect(fmt.insertBlock(text, m, idOf(m, "** a1"), "paragraph", "p", "before", OWN).text).toBe("para\n\np\n\n* a\n** a1\n* b\n\nend");
			expect(fmt.insertBlock(text, m, idOf(m, "* b"), "heading2", "h", "after", OWN).text).toBe("para\n\n* a\n** a1\n* b\n\n!! h\n\nend");
			expect(fmt.insertAnchor(m, idOf(m, "** a1"), "paragraph", OWN)).toBe(m.units[idOf(m, "* a")].parent);
			expect(fmt.insertAnchor(m, idOf(m, "** a1"), "numbered", OWN)).toBe(idOf(m, "** a1"));
		});
	});

	describe("convert", function() {
		function conv(text, source, type) {
			var m = build(text), id = typeof source === "number" ? source : idOf(m, source);
			return fmt.convert(text, m, id, type, OWN);
		}
		it("offers the types that fit the unit", function() {
			var text = "! H\n\npara\n\n* a\n** a1\n\n```\nc\n```\n\n<div>\n\nx\n\n</div>", m = build(text);
			expect(fmt.convertTypes(m, idOf(m, "para"), OWN)).toEqual(["heading1", "heading2", "heading3", "bulleted", "numbered", "quote", "quote-block", "code"]);
			expect(fmt.convertTypes(m, idOf(m, "! H"), OWN)).toEqual(["paragraph", "heading2", "heading3", "bulleted", "numbered", "quote", "quote-block", "code"]);
			expect(fmt.convertTypes(m, idOf(m, "* a"), OWN)).toEqual(["paragraph", "heading1", "heading2", "heading3", "numbered", "quote", "quote-block", "code"]);
			// A sub-item: only the other item types (a block cannot sit inside a list)
			expect(fmt.convertTypes(m, idOf(m, "** a1"), OWN)).toEqual(["numbered", "quote"]);
			expect(fmt.convertTypes(m, idOf(m, "```\nc\n```"), OWN)).toEqual(["paragraph", "heading1", "heading2", "heading3", "bulleted", "numbered", "quote", "quote-block"]);
			var div = m.units.filter(function(u) { return u.kind === "container"; })[0].id;
			expect(fmt.convertTypes(m, div, OWN)).toEqual([]);
		});
		it("paragraphs, headings and code blocks are rewritten from their content", function() {
			expect(conv("para\n\nnext", "para", "heading2").text).toBe("!! para\n\nnext");
			expect(conv("! Head\n\nnext", "! Head", "paragraph").text).toBe("Head\n\nnext");
			// Several lines do not go into a one-line type
			expect(conv("a\nb\n\nnext", "a\nb", "bulleted")).toBeNull();
			expect(conv("line1\nline2", "line1\nline2", "code").text).toBe("```\nline1\nline2\n```");
			expect(conv("```js\nx = 1\n```", "```js\nx = 1\n```", "paragraph").text).toBe("x = 1");
			var r = conv("p", "p", "numbered");
			expect(r.text).toBe("# p");
			expect(r.kind).toBe("item");
		});
		it("a heading changes its level: only its own !s, its class stays, its section is not touched", function() {
			var text = "!! H\n\npara\n\n!!! S\n\nx", m = build(text);
			expect(fmt.convertTypes(m, idOf(m, "!! H"), OWN)).toEqual(["paragraph", "heading1", "heading3", "bulleted", "numbered", "quote", "quote-block", "code"]);
			var r = conv(text, "!! H", "heading1");
			expect(r.text).toBe("! H\n\npara\n\n!!! S\n\nx");
			expect(r.kind).toBe("heading");
			expect(r.select).toBe(0);
			expect(conv(text, "!! H", "heading3").text).toBe("!!! H\n\npara\n\n!!! S\n\nx");
			expect(conv("!!.cls H<br>two", "!!.cls H<br>two", "heading1").text).toBe("!.cls H<br>two");
			// Deeper than the menu's levels: all three are offered
			expect(fmt.convertTypes(build("!!!! D"), 0, OWN)).toEqual(["paragraph", "heading1", "heading2", "heading3", "bulleted", "numbered", "quote", "quote-block", "code"]);
			expect(conv("!!.cls H", "!!.cls H", "heading2")).toBeNull();
		});
		it("neighbours stay apart: a converted heading does not merge with the paragraph after it", function() {
			var r = conv("! H\npara", "! H", "paragraph");
			expect(r.text).toBe("H\n\npara");
			expect(conv("* a\n```\nc\n```", "```\nc\n```", "paragraph").text).toBe("* a\n\nc");
		});
		it("a bullet switches with its siblings of the same level; their sub-items follow", function() {
			var text = "* a\n** a1\n* b\n** b1\n*** b1x";
			expect(conv(text, "* b", "numbered").text).toBe("# a\n#* a1\n# b\n#* b1\n#** b1x");
			expect(conv(text, "** b1", "numbered").text).toBe("* a\n** a1\n* b\n*# b1\n*#* b1x");
			// Only the siblings under the same parent
			expect(conv("* a\n** a1\n* b\n** b1", "** a1", "numbered").text).toBe("* a\n*# a1\n* b\n** b1");
		});
		it("a whole list switches at all levels", function() {
			var text = "* a\n** a1\n*# a2", m = build(text),
				list = m.units.filter(function(u) { return u.kind === "list"; })[0].id;
			var r = fmt.convert(text, m, list, "numbered");
			expect(r.text).toBe("# a\n## a1\n## a2");
			expect(r.kind).toBe("list");
		});
		it("types that are not offered do nothing", function() {
			expect(conv("para", "para", "paragraph")).toBeNull();
			expect(conv("* a", "* a", "bulleted")).toBeNull();
			expect(conv("* a\n** b", "** b", "heading1")).toBeNull();
		});
		it("multi-line content turns into one-line types only while it is one line", function() {
			var m = build("line1\nline2\n\n```\nx\ny\n```");
			expect(fmt.convertTypes(m, idOf(m, "line1\nline2"), OWN)).toEqual(["quote-block", "code"]);
			expect(fmt.convertTypes(m, idOf(m, "```\nx\ny\n```"), OWN)).toEqual(["paragraph", "quote-block"]);
		});
		it("quotes turn into the other types", function() {
			var m = build("> q\n\n<<<\nb\n<<<\n\n<<<\nb1\nb2\n<<<");
			expect(fmt.convertTypes(m, idOf(m, "> q"), OWN)).toEqual(["paragraph", "heading1", "heading2", "heading3", "bulleted", "numbered", "quote-block", "code"]);
			expect(fmt.convertTypes(m, idOf(m, "<<<\nb\n<<<"), OWN)).toEqual(["paragraph", "heading1", "heading2", "heading3", "bulleted", "numbered", "quote", "code"]);
			expect(fmt.convertTypes(m, idOf(m, "<<<\nb1\nb2\n<<<"), OWN)).toEqual(["paragraph", "code"]);
			expect(conv("> q", "> q", "paragraph").text).toBe("q");
			expect(conv("> q\n> r", "> q", "bulleted").text).toBe("* q\n* r");
			expect(conv("para", "para", "quote-block").text).toBe("<<<\npara\n<<<");
			expect(conv("<<<\nb\n<<< cite", "<<<\nb\n<<< cite", "heading2").text).toBe("!! b");
		});
		it("a list item becomes a block: the list splits, its sub-items move up one level below the block", function() {
			var r = conv("* a\n* b\n** b1\n* c", "* b", "paragraph");
			expect(r.text).toBe("* a\n\nb\n\n* b1\n\n* c");
			expect(r.select).toBe(5);
			expect(r.kind).toBe("block");
			expect(conv("* a\n* b", "* a", "heading1").text).toBe("! a\n\n* b");
			expect(conv("para\n\n* only", "* only", "code").text).toBe("para\n\n```\nonly\n```");
			expect(conv("* x<br>y", "* x<br>y", "paragraph").text).toBe("x\ny");
		});
		it("the turn-into field of the unit's type narrows the list", function() {
			var types = OWN.map(function(t) {
				return t.name === "paragraph" ? $tw.utils.extend({}, t, {turnInto: "[[code]] [[heading1]]"}) : t;
			}), m = build("para");
			expect(fmt.convertTypes(m, 0, types)).toEqual(["heading1", "code"]);
			// A filter runs over the type names
			var byPrefix = OWN.map(function(t) {
				return t.name === "paragraph" ? $tw.utils.extend({}, t, {turnInto: "[!prefix[heading]]"}) : t;
			});
			expect(fmt.convertTypes(m, 0, byPrefix)).toEqual(["bulleted", "numbered", "quote", "quote-block", "code"]);
		});
	});

	describe("externalize", function() {
		function ext(text, sources, title) {
			var m = build(text),
				ids = sources.map(function(src) { return idOf(m, src); });
			return fmt.externalize(text, m, ids, title || "X");
		}

		it("a block: a {{...}} line in its place", function() {
			var r = ext("a\n\nb\n\nc", ["b"]);
			expect(r.text).toBe("a\n\n{{X}}\n\nc");
			expect(r.source).toBe("b");
			expect(r.kind).toBe("transclusion");
			expect(r.select).toBe(3);
		});

		it("a heading goes with its section", function() {
			var r = ext("p\n\n! H\n\nx\n\n!! S\n\ny\n\n! I", ["! H"]);
			expect(r.text).toBe("p\n\n{{X}}\n\n! I");
			expect(r.source).toBe("! H\n\nx\n\n!! S\n\ny");
		});

		it("a whole list and a range of top-level items: {{...}} lines", function() {
			var text = "p\n\n* a\n* b\n** b1\n* c\n* d", m = build(text),
				list = m.units.filter(function(u) { return u.kind === "list"; })[0].id;
			var whole = fmt.externalize(text, m, [list], "X");
			expect(whole.text).toBe("p\n\n{{X}}");
			expect(whole.source).toBe("* a\n* b\n** b1\n* c\n* d");
			var part = ext(text, ["* b", "* c"]);
			expect(part.text).toBe("p\n\n* a\n\n{{X}}\n\n* d");
			expect(part.source).toBe("* b\n** b1\n* c");
		});

		it("sub-items from the parent's first one: a block transclusion at the end of the parent's line", function() {
			var text = "* a\n** a1\n*** x\n** a2\n** a3\n* b",
				r = ext(text, ["** a1", "** a2"]);
			expect(r.text).toBe("* a <$transclude $tiddler=\"X\" $mode=\"block\"/>\n** a3\n* b");
			expect(r.source).toBe("* a1\n** x\n* a2");
			expect(r.kind).toBe("item");
			expect(r.select).toBe(0);
			var nested = ext("* a\n*# n1\n*# n2", ["*# n1"]);
			expect(nested.source).toBe("# n1");
		});

		it("sibling sub-items of different levels (skipped levels) keep their relative markers", function() {
			var r = ext("* a\n*** x\n** y\n* b", ["*** x", "** y"]);
			expect(r.text).toBe("* a <$transclude $tiddler=\"X\" $mode=\"block\"/>\n* b");
			expect(r.source).toBe("** x\n* y");
		});

		it("top-level items whose first one is deeper: a {{...}} line, the source as it is", function() {
			var r = ext("*** x\n* y\n\np", ["*** x", "* y"]);
			expect(r.text).toBe("{{X}}\n\np");
			expect(r.source).toBe("*** x\n* y");
		});

		it("every result passes the model guard (removed and added units)", function() {
			[["a\n\nb\n\nc", ["b"]], ["p\n\n! H\n\nx\n\n!! S\n\ny\n\n! I", ["! H"]],
				["p\n\n* a\n* b\n** b1\n* c\n* d", ["* b", "* c"]], ["p\n\n* a\n* b\n* c", ["* a", "* b"]],
				["p\n\n* a\n* b", ["* a", "* b"]], ["* a\n** a1\n*** x\n** a2\n** a3\n* b", ["** a1", "** a2"]],
				["* a\n** a1\n** a2\n* b", ["** a1", "** a2"]], ["* a\n*** x\n** y\n* b", ["*** x", "** y"]],
				["<div>\n\nq\n\n</div>", ["q"]]].forEach(function(c) {
				var m = build(c[0]),
					ids = c[1].map(function(src) { return idOf(m, src); }),
					r = fmt.externalize(c[0], m, ids, "X");
				expect(c[0] + " -> " + model.checkOp($tw.wiki, m, ids[0], "externalize", r.text, "T", r)).toBe(c[0] + " -> true");
			});
		});

		it("not for sub-items that do not start at the parent's first one, nor for transclusions", function() {
			var m = build("* a\n** a1\n** a2\n\n{{T}}");
			expect(fmt.canExternalize(m, [idOf(m, "** a2")])).toBe(false);
			expect(fmt.canExternalize(m, [idOf(m, "** a1")])).toBe(true);
			expect(fmt.canExternalize(m, [idOf(m, "{{T}}")])).toBe(false);
			expect(fmt.externalize(m.text, m, [idOf(m, "** a2")], "X")).toBeNull();
		});

		it("a title that would break {{...}}: a transclude widget, set apart by blank lines (a line break after it at the end)", function() {
			var W = "<$transclude $tiddler=\"A|B/parts/part1\" $mode=\"block\"/>";
			expect(ext("a\n\nb", ["b"], "A|B/parts/part1").text).toBe("a\n\n" + W + "\n");
			var r = ext("* a\n* b\n* c", ["* b"], "A|B/parts/part1");
			expect(r.text).toBe("* a\n\n" + W + "\n\n* c");
			var m = build(r.text);
			expect(m.units[fmt.externalize ? model.findUnit(m, r.select, "transclusion") : -1].kind).toBe("transclusion");
			expect(ext("! H\n* a\nPara", ["* a"], "A|B/parts/part1").text).toBe("! H\n\n" + W + "\n\nPara");
		});
	});

	describe("typed blocks", function() {
		var blockTypes = require("$:/plugins/rimir/outline/block-types.js"),
			types = OWN.concat([{name: "graphviz", caption: "Graphviz graph", badge: "graphviz",
				behaviour: "typed", contentType: "text/vnd.graphviz", kind: "block", singleLine: false, contexts: ["block", "item"],
				inline: "transclude", turnInto: "", make: function(c, nl) { return "$$$text/vnd.graphviz" + nl + c + nl + "$$$"; }}]),
			GV = "$$$text/vnd.graphviz\ndigraph{}\n$$$";

		it("edit without the $$$ lines", function() {
			var m = build(GV);
			expect(fmt.editSource(GV, m, 0, types)).toBe("digraph{}");
			expect(fmt.replace(GV, m, 0, "x", types).text).toBe("$$$text/vnd.graphviz\nx\n$$$");
			expect(fmt.isMultiline(m, 0, types)).toBe(true);
		});

		it("turn into and from other types", function() {
			var m = build("para\n\n```\nc\n```\n\n$$$text/vnd.graphviz\na\nb\n$$$");
			expect(fmt.convertTypes(m, idOf(m, "para"), types)).toContain("graphviz");
			expect(fmt.convertTypes(m, idOf(m, "```\nc\n```"), types)).toContain("graphviz");
			expect(fmt.convertTypes(m, idOf(m, "$$$text/vnd.graphviz\na\nb\n$$$"), types)).toEqual(["paragraph", "quote-block", "code"]);
			expect(fmt.convert("```\nc\n```", build("```\nc\n```"), 0, "graphviz", types).text).toBe("$$$text/vnd.graphviz\nc\n$$$");
			expect(fmt.convert(GV, build(GV), 0, "code", types).text).toBe("```\ndigraph{}\n```");
			var text = "para", r = fmt.insertBlock(text, build(text), 0, "graphviz", "a", "after", types);
			expect(r.text).toBe("para\n\n$$$text/vnd.graphviz\na\n$$$");
		});

		it("an unregistered typed block stays as before", function() {
			var text = "$$$text/plain\nx\n$$$", m = build(text);
			expect(fmt.editSource(text, m, 0, types)).toBe(text);
			expect(fmt.convertTypes(m, 0, types)).toEqual([]);
			expect(fmt.typedBlockType(text, m.units[0], types)).toBeNull();
			expect(fmt.typedBlockType(GV, build(GV).units[0], types).name).toBe("graphviz");
		});
	});

	it("new item after subtree", function() {
		var text = "* a\n** a1\n* b", m = build(text),
			r = fmt.insertNew(text, m, idOf(m, "* a"), "x");
		expect(r.text).toBe("* a\n** a1\n* x\n* b");
		expect(r.select).toBe(10);
	});

	it("new item after last line", function() {
		var text = "* a", m = build(text), r = fmt.insertNew(text, m, idOf(m, "* a"), "x");
		expect(r.text).toBe("* a\n* x");
		expect(r.select).toBe(4);
	});

	it("new item: a typed leading marker equal to the item's marker is not doubled", function() {
		var text = "* a\n** a1\n* b", m = build(text);
		expect(fmt.insertNew(text, m, idOf(m, "* a"), "* foo").text).toBe("* a\n** a1\n* foo\n* b");
		expect(fmt.insertNew(text, m, idOf(m, "** a1"), "**  deep").text).toBe("* a\n** a1\n** deep\n* b");
		// Other text that starts with marker characters stays
		expect(fmt.insertNew(text, m, idOf(m, "* a"), "*bold*").text).toBe("* a\n** a1\n* *bold*\n* b");
		expect(fmt.insertNew(text, m, idOf(m, "* a"), "** deeper").text).toBe("* a\n** a1\n* ** deeper\n* b");
		// Only the marker: nothing to insert
		expect(fmt.insertNew(text, m, idOf(m, "* a"), "*  ")).toBeNull();
	});
	it("new item at another level: newItemMarker range and the marker passed to insertNew", function() {
		var text = "* a\n** a1\n*** a2\n* b\n#* c", m = build(text), a = idOf(m, "* a");
		// Deeper: down to one below the last item of a's subtree (a2); higher: down to level 1
		expect(fmt.newItemMarker(m, a, 0)).toBe("*");
		expect(fmt.newItemMarker(m, a, 3)).toBe("****");
		expect(fmt.newItemMarker(m, a, 4)).toBeNull();
		expect(fmt.newItemMarker(m, a, -1)).toBeNull();
		expect(fmt.newItemMarker(m, idOf(m, "*** a2"), -2)).toBe("*");
		// One more of the last marker character, one character less
		expect(fmt.newItemMarker(m, idOf(m, "#* c"), 1)).toBe("#**");
		expect(fmt.newItemMarker(m, idOf(m, "#* c"), -1)).toBe("#");
		// Not an item
		expect(fmt.newItemMarker(build("para"), 0, 0)).toBeNull();
		expect(fmt.insertNew(text, m, a, "x", "**").text).toBe("* a\n** a1\n*** a2\n** x\n* b\n#* c");
	});

	it("new item keeps CRLF", function() {
		var text = "* a\r\n** a1\r\n* b", m = build(text),
			r = fmt.insertNew(text, m, idOf(m, "* a"), "x");
		expect(r.text).toBe("* a\r\n** a1\r\n* x\r\n* b");
		expect(r.text.replace(/\r\n/g, "")).not.toMatch(/[\r\n]/);
	});

	it("new unit before: an item with the item's marker, a paragraph before anything else", function() {
		var t = "* a\n* b\n** b1", m = build(t);
		expect(fmt.insertNew(t, m, idOf(m, "* b"), "x", null, "before")).toEqual({text: "* a\n* x\n* b\n** b1", select: 4});
		expect(fmt.insertNew(t, m, idOf(m, "** b1"), "** y", null, "before").text).toBe("* a\n* b\n** y\n** b1");
		t = "para\n\nnext";
		m = build(t);
		expect(fmt.insertNew(t, m, idOf(m, "next"), "x", null, "before")).toEqual({text: "para\n\nx\n\nnext", select: 6});
		expect(fmt.insertNew(t, m, idOf(m, "para"), "x", null, "before").text).toBe("x\n\npara\n\nnext");
		expect(fmt.insertNew(t, m, idOf(m, "para"), "  ", null, "before")).toBe(null);
		// CRLF
		t = "* a\r\n* b";
		m = build(t);
		expect(fmt.insertNew(t, m, idOf(m, "* b"), "x", null, "before").text).toBe("* a\r\n* x\r\n* b");
	});

	it("heading new paragraph", function() {
		var text = "! H\n\ntext", m = build(text),
			r = fmt.insertNew(text, m, idOf(m, "! H"), "x");
		expect(r.text).toBe("! H\n\nx\n\ntext");
		expect(r.select).toBe(5);
	});

	it("heading new paragraph without blank line after", function() {
		var text = "! H\ntext", m = build(text),
			r = fmt.insertNew(text, m, idOf(m, "! H"), "x");
		expect(r.text).toBe("! H\n\nx\n\ntext");
	});

	it("heading new paragraph at end of text", function() {
		var text = "! H", m = build(text), r = fmt.insertNew(text, m, 0, "x");
		expect(r.text).toBe("! H\n\nx");
	});

	it("block new paragraph", function() {
		var text = "para\n\nnext", m = build(text),
			r = fmt.insertNew(text, m, idOf(m, "para"), "x");
		expect(r.text).toBe("para\n\nx\n\nnext");
		expect(r.select).toBe(6);
	});

	it("blank new unit", function() {
		var text = "* a", m = build(text);
		expect(fmt.insertNew(text, m, 0, "")).toBeNull();
		expect(fmt.insertNew(text, m, 0, "  \n ")).toBeNull();
	});

	it("heading new paragraph keeps trailing newline count", function() {
		var text = "! H\n", m = build(text), r = fmt.insertNew(text, m, 0, "x");
		expect(r.text).toBe("! H\n\nx\n");
	});

	it("isMultiline", function() {
		var t = "|a|b|\n\n```\nx\n```\n\n* a\n\n<$list filter=\"[all[]]\"/>\n\n<div>\n\npara\n\n</div>\n\npa\nrb",
			m = build(t);
		function find(tag, kind) {
			var u = unit(m, function(u) { return (tag && u.tag === tag) || (kind && u.kind === kind); });
			expect(u).toBeDefined();
			return u.id;
		}
		expect(fmt.isMultiline(m, find("table"))).toBe(true);
		expect(fmt.isMultiline(m, find("codeblock"))).toBe(true);
		expect(fmt.isMultiline(m, find(null, "widget"))).toBe(true);
		expect(fmt.isMultiline(m, find(null, "container"))).toBe(true);
		expect(fmt.isMultiline(m, idOf(m, "* a"))).toBe(false);
		var para = unit(m, function(u) { return m.text.substring(u.start, u.end) === "pa\nrb"; });
		expect(para).toBeDefined();
		expect(fmt.isMultiline(m, para.id)).toBe(true);
		var m2 = build(fixtures.NOTES.specialItems),
			multi = unit(m2, function(u) { return u.kind === "item" && /^\* """multi/.test(m2.text.substring(u.start, u.end)); });
		expect(multi).toBeDefined();
		expect(fmt.isMultiline(m2, multi.id)).toBe(true);
	});

	describe("remove", function() {
		function removed(text, source) {
			var m = build(text), r = fmt.remove(text, m, idOf(m, source));
			return r && r.text;
		}

		it("removes an item and one line break", function() {
			expect(removed("* a\n* b\n* c", "* b")).toBe("* a\n* c");
			expect(removed("* a\n* b", "* b")).toBe("* a");
			expect(removed("* a\n* b\n\npara", "* b")).toBe("* a\n\npara");
			expect(removed("* a\r\n* b\r\n* c", "* b")).toBe("* a\r\n* c");
		});

		it("keeps one blank-line separator between remaining blocks", function() {
			expect(removed("p1\n\np2\n\np3", "p2")).toBe("p1\n\np3");
			expect(removed("p1\n\np2", "p2")).toBe("p1");
			expect(removed("p1\n\np2", "p1")).toBe("p2");
			expect(removed("p1\r\n\r\np2\r\n\r\np3", "p2")).toBe("p1\r\n\r\np3");
		});

		it("refuses units with children", function() {
			var text = "* a\n** a1", m = build(text);
			expect(fmt.remove(text, m, idOf(m, "* a"))).toBe(null);
		});

		it("selects the place of the removed unit", function() {
			var text = "* a\n* b\n* c", m = build(text), r = fmt.remove(text, m, idOf(m, "* b"));
			expect(r.select).toBe(4);
		});
	});
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/outline/test/test-editor.js":{"title":"$:/plugins/rimir/outline/test/test-editor.js","text":"/*\
title: $:/plugins/rimir/outline/test/test-editor.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for the in-place editor of the $outline widget (outline-editor.js): start, save, continue,
cancel, conflicts on outside changes, re-attach after re-render, editor keys and the transclusion jump.
Runs on the fake DOM (SimpleEngine). Typing is simulated by writing the buffer tiddler.

\*/
"use strict";

describe("outline editor", function() {

	var SEL = "$:/temp/rimir/outline/selection/",
		BUF = "$:/temp/rimir/outline/edit/",
		EDITOR = "$:/plugins/rimir/outline/ui/editor",
		KEYS = {enter: 13, escape: 27};

	// Shortcut config and the editor template (shadows of the plugin) copied into each test wiki
	function pluginTiddlers() {
		return $tw.wiki.filterTiddlers("[all[shadows+tiddlers]prefix[$:/config/shortcuts/outline-]] [[" + EDITOR + "]] [[$:/plugins/rimir/outline/ui/overlay]] [[$:/plugins/rimir/outline/ui/overlay-diagram]] [[$:/plugins/rimir/outline/ui/overlay-bar]] [[$:/plugins/rimir/outline/ui/diagram-tools]] [[$:/plugins/rimir/outline/ui/diagram-preview]] " +
			"[all[shadows+tiddlers]tag[$:/tags/rimir/outline/BlockType]prefix[$:/plugins/rimir/outline/]] [[$:/tags/rimir/outline/BlockType]]").map(function(title) {
			return $tw.wiki.getTiddler(title).fields;
		});
	}

	function makeWiki(tiddlers) {
		var wiki = new $tw.Wiki();
		wiki.addTiddlers(pluginTiddlers().concat(tiddlers || []));
		wiki.addIndexersToWiki();
		return wiki;
	}

	function findWidget(widget, type) {
		if(widget.parseTreeNode && widget.parseTreeNode.type === type) {
			return widget;
		}
		for(var i = 0; i < (widget.children || []).length; i++) {
			var found = findWidget(widget.children[i], type);
			if(found) {
				return found;
			}
		}
		return null;
	}

	function render(text, others) {
		var wiki = makeWiki([{title: "T", text: text}].concat(others || []));
		var parser = wiki.parseText("text/vnd.tiddlywiki",
				"<$outline tiddler=\"T\"><$transclude $tiddler=\"T\" $mode=\"block\"/></$outline>",
				{parseAsInline: false}),
			root = wiki.makeWidget(parser, {document: $tw.fakeDocument}),
			container = $tw.fakeDocument.createElement("div");
		root.render(container, null);
		var r = {root: root, widget: findWidget(root, "outline"), wiki: wiki};
		r.widget.wake();
		r.refresh = function(extra) {
			var changes = {T: {modified: true}};
			changes[SEL + "T"] = {modified: true};
			changes[BUF + "T"] = {modified: true};
			$tw.utils.each(extra || [], function(t) { changes[t] = {modified: true}; });
			root.refresh(changes);
		};
		r.text = function() { return wiki.getTiddlerText("T"); };
		r.buffer = function() { return wiki.getTiddlerText(BUF + "T"); };
		r.type = function(value) { wiki.addTiddler(new $tw.Tiddler(wiki.getTiddler(BUF + "T"), {text: value})); };
		r.idOf = function(source) {
			var m = r.widget.model;
			for(var i = 0; i < m.units.length; i++) {
				if(m.text.substring(m.units[i].start, m.units[i].end) === source) {
					return i;
				}
			}
			throw new Error("no unit " + source);
		};
		return r;
	}

	// A second <$outline> view of T in the same wiki
	function secondView(r) {
		var parser = r.wiki.parseText("text/vnd.tiddlywiki",
				"<$outline tiddler=\"T\"><$transclude $tiddler=\"T\" $mode=\"block\"/></$outline>",
				{parseAsInline: false}),
			root = r.wiki.makeWidget(parser, {document: $tw.fakeDocument}),
			container = $tw.fakeDocument.createElement("div");
		root.render(container, null);
		var widget = findWidget(root, "outline");
		widget.wake();
		return {root: root, widget: widget};
	}

	function notes(r) {
		return elements(r.widget.editor.host).filter(function(el) { return hasClass(el, "rr-ol-notice"); });
	}

	function hasClass(el, cls) {
		return (el.attributes["class"] || "").split(" ").indexOf(cls) !== -1;
	}

	function siblings(node) {
		return node.parentNode.children;
	}

	function elements(node, out) {
		out = out || [];
		(node.children || []).forEach(function(child) {
			if(child.nodeType === 1) {
				out.push(child);
				elements(child, out);
			}
		});
		return out;
	}

	function editorKey(r, keyCode, mods) {
		mods = mods || {};
		var ev = {
			keyCode: keyCode,
			shiftKey: !!mods.shift, altKey: false, ctrlKey: !!mods.ctrl, metaKey: false,
			target: r.widget.editor.host,
			defaultPrevented: !!mods.defaultPrevented,
			prevented: false,
			preventDefault: function() { this.prevented = true; },
			stopPropagation: function() {}
		};
		r.widget.handleEditorKeydown(ev);
		return ev;
	}

	it("starts an edit next to the unit with the unit's own source", function() {
		var r = render("* a\n** a1\n* b");
		var id = r.idOf("* a"),
			li = r.widget.units[id].domNodes[0];
		expect(r.widget.startEdit(id)).toBe(true);
		var ed = r.widget.editor;
		expect(ed.id).toBe(id);
		expect(ed.isNew).toBe(false);
		expect(ed.origSource).toBe("* a");
		expect(ed.origStart).toBe(0);
		// Items: the host is the first child of the li; only the li's own content is hidden, not its sub-items
		expect(ed.host.tag).toBe("div");
		expect(hasClass(ed.host, "rr-ol-editor-host")).toBe(true);
		expect(ed.host.parentNode).toBe(li);
		expect(li.children[0]).toBe(ed.host);
		expect(hasClass(li, "rr-ol-editing-own")).toBe(true);
		expect(hasClass(li, "rr-ol-editing")).toBe(false);
		expect(r.buffer()).toBe("a");
		// The editor template rendered an edit widget for the buffer
		var textareas = elements(ed.host).filter(function(el) { return el.tag === "textarea"; });
		expect(textareas.length).toBe(1);
		expect(textareas[0].textContent).toBe("a");
	});

	it("compact editor by default, full editor with toolbar when configured", function() {
		function editorOf(r) {
			r.widget.startEdit(r.idOf("* a"));
			var els = elements(r.widget.editor.host);
			return {
				textarea: els.filter(function(el) { return el.tag === "textarea"; })[0],
				toolbar: els.some(function(el) { return hasClass(el, "tc-editor-toolbar"); })
			};
		}
		var compact = editorOf(render("* a"));
		expect(hasClass(compact.textarea, "rr-ol-editor-compact")).toBe(true);
		expect(compact.toolbar).toBe(false);
		var full = editorOf(render("* a", [{title: "$:/config/rimir/outline/full-editor", text: "yes"}]));
		// The fake DOM renders no toolbar (the browser tests check it); the full editor's textarea class differs
		expect(hasClass(full.textarea, "tc-edit-texteditor")).toBe(true);
		expect(hasClass(full.textarea, "rr-ol-editor-compact")).toBe(false);
	});

	describe("double-click on another unit while editing", function() {

		function dbl(r, source) {
			r.widget.handleDblClick({target: r.widget.units[r.idOf(source)].domNodes[0], preventDefault: function() {}});
		}
		function edited(r) { return r.widget.model.text.substring(r.widget.units[r.widget.editor.id].unit.start, r.widget.units[r.widget.editor.id].unit.end); }

		it("saves the edited unit and edits the clicked one, after and before it", function() {
			var r = render("para\n\n* a\n* b\n\nend");
			r.widget.startEdit(r.idOf("* a"));
			r.type("A longer");
			dbl(r, "end");
			expect(r.text()).toBe("para\n\n* A longer\n* b\n\nend");
			expect(edited(r)).toBe("end");
			expect(r.buffer()).toBe("end");
			r.type("END");
			dbl(r, "para");
			expect(r.text()).toBe("para\n\n* A longer\n* b\n\nEND");
			expect(edited(r)).toBe("para");
		});

		it("a blanked unit is deleted, the clicked one is still found", function() {
			var r = render("* a\n* b\n* c");
			r.widget.startEdit(r.idOf("* a"));
			r.type("");
			dbl(r, "* c");
			expect(r.text()).toBe("* b\n* c");
			expect(edited(r)).toBe("* c");
		});

		it("a new unit is saved, then the clicked unit is edited", function() {
			var r = render("* a\n* b");
			r.widget.startEdit(r.idOf("* a"), {isNew: true});
			r.type("new");
			dbl(r, "* b");
			expect(r.text()).toBe("* a\n* new\n* b");
			expect(edited(r)).toBe("* b");
		});

		it("a refused save keeps the editor on its unit", function() {
			var r = render("* a\n** a1\n* b");
			r.widget.startEdit(r.idOf("* a"));
			r.type("");
			dbl(r, "* b");
			expect(r.text()).toBe("* a\n** a1\n* b");
			expect(edited(r)).toBe("* a");
			expect(notes(r).length).toBe(1);
		});
	});

	describe("ctrl-up/down move the editor", function() {

		function key(r, keyCode) { return editorKey(r, keyCode, {ctrl: true}); }
		function edited(r) { return r.widget.model.text.substring(r.widget.units[r.widget.editor.id].unit.start, r.widget.units[r.widget.editor.id].unit.end); }

		it("saves and edits the next and previous unit, sub-items included", function() {
			var r = render("* a\n** a1\n* b");
			r.widget.startEdit(r.idOf("* a"));
			r.type("A");
			var ev = key(r, 40);
			expect(ev.prevented).toBe(true);
			expect(r.text()).toBe("* A\n** a1\n* b");
			expect(edited(r)).toBe("** a1");
			expect(r.buffer()).toBe("a1");
			key(r, 40);
			expect(edited(r)).toBe("* b");
			key(r, 38);
			key(r, 38);
			expect(edited(r)).toBe("* A");
		});

		it("at the edges the editor stays on the unit", function() {
			var r = render("* a\n* b");
			r.widget.startEdit(r.idOf("* b"));
			key(r, 40);
			expect(edited(r)).toBe("* b");
		});

		it("unchanged edits write nothing", function() {
			var r = render("* a\n* b"),
				before = r.wiki.getTiddler("T").fields.modified;
			r.widget.startEdit(r.idOf("* a"));
			key(r, 40);
			expect(edited(r)).toBe("* b");
			expect(r.wiki.getTiddler("T").fields.modified).toBe(before);
		});

		it("a blanked unit is deleted; down edits the unit that took its place", function() {
			var r = render("* a\n* b\n* c");
			r.widget.startEdit(r.idOf("* b"));
			r.type("");
			key(r, 40);
			expect(r.text()).toBe("* a\n* c");
			expect(edited(r)).toBe("* c");
		});

		it("an empty new unit: up edits its anchor", function() {
			var r = render("* a\n* b");
			r.widget.startEdit(r.idOf("* a"), {isNew: true});
			key(r, 38);
			expect(r.text()).toBe("* a\n* b");
			expect(edited(r)).toBe("* a");
		});

		it("a refused save keeps the editor", function() {
			var r = render("* a\n** a1\n* b");
			r.widget.startEdit(r.idOf("* a"));
			r.type("");
			key(r, 40);
			expect(r.widget.editor).not.toBe(null);
			expect(r.text()).toBe("* a\n** a1\n* b");
		});
	});

	describe("tab/shift-tab while editing", function() {

		function tab(r, shift) { return editorKey(r, 9, {shift: !!shift}); }
		function edited(r) {
			var u = r.widget.units[r.widget.editor.id].unit;
			return r.widget.model.text.substring(u.start, u.end);
		}

		it("saves, indents the unit with its subtree and keeps editing it", function() {
			var r = render("* a\n* b\n** b1\n* c");
			r.widget.startEdit(r.idOf("* b"));
			r.type("B");
			expect(tab(r).prevented).toBe(true);
			expect(r.text()).toBe("* a\n** B\n*** b1\n* c");
			expect(r.widget.editor).not.toBe(null);
			expect(edited(r)).toBe("** B");
			expect(r.buffer()).toBe("B");
			tab(r, true);
			expect(r.text()).toBe("* a\n* B\n** b1\n* c");
			expect(edited(r)).toBe("* B");
		});

		it("alt-up/down save, move the unit with its subtree and keep editing it", function() {
			var r = render("* a\n* b\n** b1\n* c");
			r.widget.startEdit(r.idOf("* b"));
			r.type("B");
			var ev = {keyCode: 40, shiftKey: false, altKey: true, ctrlKey: false, metaKey: false,
				target: r.widget.editor.host, defaultPrevented: false, prevented: false,
				preventDefault: function() { this.prevented = true; }, stopPropagation: function() {}};
			r.widget.handleEditorKeydown(ev);
			expect(ev.prevented).toBe(true);
			expect(r.text()).toBe("* a\n* c\n* B\n** b1");
			expect(edited(r)).toBe("* B");
			expect(r.buffer()).toBe("B");
			ev.keyCode = 38; ev.prevented = false;
			r.widget.handleEditorKeydown(ev);
			r.widget.handleEditorKeydown(ev);
			expect(r.text()).toBe("* B\n** b1\n* a\n* c");
			expect(edited(r)).toBe("* B");
		});

		it("headings carry their section", function() {
			var r = render("! A\n\n! B\n\ntext");
			r.widget.startEdit(r.idOf("! B"));
			tab(r);
			expect(r.text()).toBe("! A\n\n!! B\n\ntext");
			expect(edited(r)).toBe("!! B");
		});

		it("no previous sibling: nothing changes, the editor stays", function() {
			var r = render("* a\n* b"),
				before = r.wiki.getTiddler("T");
			r.widget.startEdit(r.idOf("* a"));
			expect(tab(r).prevented).toBe(true);
			expect(r.wiki.getTiddler("T")).toBe(before);
			expect(edited(r)).toBe("* a");
		});

		it("empty text: consumed, nothing deleted", function() {
			var r = render("* a\n* b");
			r.widget.startEdit(r.idOf("* b"));
			r.type("");
			expect(tab(r).prevented).toBe(true);
			expect(r.text()).toBe("* a\n* b");
			expect(r.widget.editor).not.toBe(null);
		});

		it("a new unit with text is inserted, then indented", function() {
			var r = render("* a\n* b");
			r.widget.startEdit(r.idOf("* a"), {isNew: true});
			r.type("n");
			tab(r);
			expect(r.text()).toBe("* a\n** n\n* b");
			expect(edited(r)).toBe("** n");
		});
	});

	describe("block menu", function() {

		function press(r, keyCode, mods) {
			mods = mods || {};
			var ev = {keyCode: keyCode, shiftKey: !!mods.shift, altKey: !!mods.alt, ctrlKey: false, metaKey: false,
				target: r.widget.domNode, defaultPrevented: false, prevented: false,
				preventDefault: function() { this.prevented = true; }, stopPropagation: function() {}};
			r.widget.handleKeydown(ev);
			return ev;
		}
		function labels(r) {
			return r.widget.menu.entries.map(function(e) { return e.action + ":" + e.type; });
		}
		function choose(r, action, type) {
			var i = labels(r).indexOf(action + ":" + type);
			expect(i).not.toBe(-1);
			r.widget.setMenuActive(i);
			press(r, 13);
		}

		it("alt-enter opens it with insert and turn-into entries for the unit", function() {
			var r = render("para\n\n* a\n* b");
			r.widget.select(r.idOf("para"));
			expect(press(r, 13, {alt: true}).prevented).toBe(true);
			var inserts = ["insert:paragraph", "insert:heading1", "insert:heading2", "insert:heading3",
				"insert:bulleted", "insert:numbered", "insert:quote", "insert:quote-block", "insert:code"];
			expect(labels(r)).toEqual(inserts.concat(inserts, [
				"convert:heading1", "convert:heading2", "convert:heading3", "convert:bulleted", "convert:numbered",
				"convert:quote", "convert:quote-block", "convert:code", "externalize:undefined"]));
			expect(r.widget.menu.entries[9].group).toBe("group-insert-before");
			expect(r.widget.menu.entries[9].where).toBe("before");
			expect(hasClass(r.widget.menu.node, "rr-ol-menu")).toBe(true);
			// Escape closes, nothing written
			press(r, 27);
			expect(r.widget.menu).toBe(null);
			// A bullet: insert before/after it too, and it turns into every other type
			r.widget.select(r.idOf("* a"));
			press(r, 13, {alt: true});
			expect(labels(r)).toEqual(inserts.concat(inserts, ["convert:paragraph", "convert:heading1", "convert:heading2",
				"convert:heading3", "convert:numbered", "convert:quote", "convert:quote-block", "convert:code", "externalize:undefined"]));
		});

		it("follows the block type tiddlers: an untagged override drops the type from insert and turn into", function() {
			var r = render("para\n\nnext", [{title: "$:/plugins/rimir/outline/blocktypes/heading3", name: "heading3",
				caption: "Heading 3", behaviour: "heading", level: "3"}]);
			r.widget.select(r.idOf("para"));
			press(r, 13, {alt: true});
			expect(labels(r).filter(function(l) { return /heading3/.test(l); })).toEqual([]);
			expect(labels(r)).toContain("convert:heading2");
		});

		it("insert before the first bullet makes a new first bullet", function() {
			var r = render("* a\n* b");
			r.widget.select(r.idOf("* a"));
			press(r, 13, {alt: true});
			var i = r.widget.menu.entries.findIndex(function(e) { return e.where === "before" && e.type === "bulleted"; });
			r.widget.setMenuActive(i);
			press(r, 13);
			r.type("first");
			r.widget.saveEdit();
			expect(r.wiki.getTiddlerText("T")).toBe("* first\n* a\n* b");
		});

		it("alt-enter in an empty new editor offers every type; picking one changes what it creates, nothing is written", function() {
			var r = render("! H\n\npara");
			r.widget.select(r.idOf("! H"));
			r.widget.startEdit(r.idOf("! H"), {isNew: true});
			expect(r.widget.editor.kind).toBe("block");
			r.widget.editMenu();
			expect(r.widget.menu.entries.map(function(e) { return e.action + ":" + e.type; })).toEqual(["retype:paragraph",
				"retype:heading1", "retype:heading2", "retype:heading3", "retype:bulleted", "retype:numbered", "retype:quote",
				"retype:quote-block", "retype:code"]);
			choose(r, "retype", "heading2");
			expect(r.wiki.getTiddlerText("T")).toBe("! H\n\npara");
			expect(r.widget.editor.isNew).toBe(true);
			expect(r.widget.editor.blockType).toBe("heading2");
			r.type("x");
			r.widget.saveEdit();
			// A new heading at a heading goes after its section (as when inserted from the block menu)
			expect(r.wiki.getTiddlerText("T")).toBe("! H\n\npara\n\n!! x");
		});

		it("the retype menu keeps a new item's Tab depth (picked item type, or Escape)", function() {
			var r = render("* a\n* b");
			r.widget.select(r.idOf("* a"));
			r.widget.startEdit(r.idOf("* a"), {isNew: true});
			editorKey(r, 9);
			expect(r.widget.editor.depth).toBe(1);
			r.widget.editMenu();
			press(r, 27);
			expect(r.widget.editor.depth).toBe(1);
			r.widget.editMenu();
			choose(r, "retype", "numbered");
			expect(r.widget.editor.depth).toBe(1);
			r.type("x");
			r.widget.saveEdit();
			expect(r.text()).toBe("* a\n*# x\n* b");
			// A block type has no depth
			var s = render("* a\n* b");
			s.widget.select(s.idOf("* a"));
			s.widget.startEdit(s.idOf("* a"), {isNew: true});
			editorKey(s, 9);
			s.widget.editMenu();
			choose(s, "retype", "paragraph");
			expect(s.widget.editor.depth).toBe(0);
		});

		it("escape on the retype menu keeps the new editor as it was", function() {
			var r = render("para");
			r.widget.select(r.idOf("para"));
			r.widget.startEdit(r.idOf("para"), {isNew: true});
			r.widget.editMenu();
			press(r, 27);
			expect(r.widget.menu).toBe(null);
			expect(r.widget.editor.isNew).toBe(true);
			expect(r.widget.editor.blockType).toBe("");
		});

		it("a new block's editor has the type's caption as placeholder", function() {
			var r = render("para");
			r.widget.select(r.idOf("para"));
			press(r, 13, {alt: true});
			choose(r, "insert", "heading2");
			var w = r.widget.editor.widget;
			while(w.children && w.children.length) { w = w.children[0]; }
			expect(w.getVariable("outline-edit-placeholder")).toBe("Heading 2");
		});

		it("labels the types with their captions", function() {
			var r = render("para", [{title: "$:/plugins/rimir/outline/blocktypes/paragraph", tags: "$:/tags/rimir/outline/BlockType",
				name: "paragraph", caption: "Text", badge: "paragraph", behaviour: "paragraph"}]);
			r.widget.select(r.idOf("para"));
			press(r, 13, {alt: true});
			expect(r.widget.menu.node.textContent).toContain("Text");
			expect(r.widget.menu.node.textContent).toContain("Heading 1");
		});

		it("up/down move the active entry; another key closes the menu and acts as usual", function() {
			var r = render("para\n\nnext");
			r.widget.select(r.idOf("para"));
			press(r, 13, {alt: true});
			press(r, 40);
			press(r, 40);
			expect(r.widget.menu.active).toBe(2);
			press(r, 38);
			expect(r.widget.menu.active).toBe(1);
			press(r, 38);
			press(r, 38);
			expect(r.widget.menu.active).toBe(0);
			press(r, 9);
			expect(r.widget.menu).toBe(null);
		});

		it("insert opens an editor for the new block; saving inserts it of that type", function() {
			var r = render("para\n\n! H\n\ntext");
			r.widget.select(r.idOf("para"));
			press(r, 13, {alt: true});
			choose(r, "insert", "heading2");
			expect(r.widget.editor).not.toBe(null);
			expect(r.widget.editor.blockType).toBe("heading2");
			expect(r.wiki.getTiddler(BUF + "T").fields["outline-block-type"]).toBe("heading2");
