title: $:/plugins/rimir/outline/test/test-indent.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for indent and promote in format-wikitext.js.

\*/
"use strict";

var model = require("$:/plugins/rimir/outline/model.js"),
	fmt = require("$:/plugins/rimir/outline/format-wikitext.js"),
	formats = require("$:/plugins/rimir/outline/formats.js"),
	fixtures = require("$:/plugins/rimir/outline/test/fixtures.js");

describe("outline indent/promote", function() {

	function build(text) { return model.buildModel($tw.wiki, text); }
	function idOf(m, s) {
		return m.units.filter(function(u) { return m.text.substring(u.start, u.end) === s; })[0].id;
	}
	function run(fn, text, s) {
		var m = build(text);
		return fn(text, m, idOf(m, s));
	}

	it("indent bullet", function() {
		var r = run(fmt.indent, "* a\n* b\n** b1", "* b");
		expect(r.text).toBe("* a\n** b\n*** b1");
		expect(r.select).toBe(4);
	});
	it("indent numbered", function() {
		expect(run(fmt.indent, "# a\n# b", "# b").text).toBe("# a\n## b");
	});
	it("indent mixed", function() {
		expect(run(fmt.indent, "# x\n#* a\n#* b", "#* b").text).toBe("# x\n#* a\n#** b");
	});
	it("indent uses the item's own char for descendants", function() {
		expect(run(fmt.indent, "#* a\n#* b\n#** b1", "#* b").text).toBe("#* a\n#** b\n#*** b1");
	});
	it("no previous sibling", function() {
		expect(run(fmt.indent, "* a\n* b", "* a")).toBe(null);
	});
	it("promote at depth 1", function() {
		expect(run(fmt.promote, "* a\n* b", "* b")).toBe(null);
	});
	it("promote captures following siblings", function() {
		expect(run(fmt.promote, "* a\n** b\n** c", "** b").text).toBe("* a\n* b\n** c");
	});
	it("heading section", function() {
		expect(run(fmt.indent, "! A\n\ntext\n\n!! B", "! A").text).toBe("!! A\n\ntext\n\n!!! B");
	});
	it("heading promote", function() {
		expect(run(fmt.promote, "!! A\n\n!!! B", "!! A").text).toBe("! A\n\n!! B");
		expect(run(fmt.promote, "! A", "! A")).toBe(null);
	});
	it("heading limit", function() {
		expect(run(fmt.indent, "!! A\n\n!!!!!! B", "!! A")).toBe(null);
	});
	it("class item", function() {
		expect(run(fmt.indent, "* a\n*.cls b", "*.cls b").text).toBe("* a\n**.cls b");
	});
	it("other kinds are null", function() {
		var m = build("para\n\n* a");
		expect(fmt.indent("para\n\n* a", m, 0)).toBe(null);
		expect(fmt.promote("para\n\n* a", m, 0)).toBe(null);
	});
	it("indent keeps CRLF", function() {
		var t = fixtures.NOTES.crlf, m = build(t),
			r = fmt.indent(t, m, idOf(m, "* four"));
		expect(r.text.replace(/\r\n/g, "").indexOf("\n")).toBe(-1);
		expect(r.text.split("\r\n").length).toBe(t.split("\r\n").length);
	});
	it("getFormat", function() {
		expect(formats.getFormat("text/vnd.tiddlywiki")).toBeTruthy();
		expect(formats.getFormat("")).toBeTruthy();
		expect(formats.getFormat("text/x-markdown")).toBe(null);
	});
	it("post-op guard refuses a changed unit count and level jumps other than one", function() {
		var t = "* a\n* b\n** b1\n* c", m = build(t), b = idOf(m, "* b");
		expect(model.checkOp($tw.wiki, m, b, "indent", "* a\n** b\n*** b1\n* c")).toBe(true);
		// The subtree stayed behind
		expect(model.checkOp($tw.wiki, m, b, "indent", "* a\n** b\n** b1\n* c")).toBe(false);
		// Two levels
		expect(model.checkOp($tw.wiki, m, b, "indent", "* a\n*** b\n**** b1\n* c")).toBe(false);
		// A unit outside the subtree changed
		expect(model.checkOp($tw.wiki, m, b, "indent", "* a\n** b\n*** b1\n** c")).toBe(false);
		// Unit count changed
		expect(model.checkOp($tw.wiki, m, b, "indent", "* a\n** b\n*** b1\n\npara")).toBe(false);
		expect(model.checkOp($tw.wiki, m, b, "promote", "* a\nb\n* b1\n* c")).toBe(false);
		var h = "! A\n\n!! B\n\nx", mh = build(h);
		expect(model.checkOp($tw.wiki, mh, idOf(mh, "!! B"), "promote", "! A\n\n! B\n\nx")).toBe(true);
		expect(model.checkOp($tw.wiki, mh, idOf(mh, "!! B"), "indent", "! A\n\n!!!! B\n\nx")).toBe(false);
	});
	it("round trip and range", function() {
		Object.keys(fixtures.NOTES).forEach(function(name) {
			var t = fixtures.NOTES[name], m = build(t);
			m.units.forEach(function(u) {
				if(u.kind !== "item" && u.kind !== "heading") { return; }
				var r = fmt.indent(t, m, u.id);
				if(!r) { return; }
				fixtures.assertOnlyRangesChanged(t, r.text, [[u.start, u.subtreeEnd]], expect);
				expect(model.checkOp($tw.wiki, m, u.id, "indent", r.text)).withContext(name + " " + u.id).toBe(true);
				var m2 = build(r.text), nid = m2.units.filter(function(x) { return x.start === r.select; })[0].id,
					back = fmt.promote(r.text, m2, nid);
				expect(back && back.text).toBe(t);
				expect(model.checkOp($tw.wiki, m2, nid, "promote", back.text)).withContext(name + " " + u.id).toBe(true);
			});
		});
	});
});
","type":"application/javascript","tags":"[[$:/tags/test-spec]]"},"$:/plugins/rimir/outline/test/test-keys.js":{"title":"$:/plugins/rimir/outline/test/test-keys.js","text":"/*\
title: $:/plugins/rimir/outline/test/test-keys.js
type: application/javascript
tags: [[$:/tags/test-spec]]

Tests for selection, configurable keys and structural operations of the $outline widget.

\*/
"use strict";

describe("outline selection and keys", function() {

	var SEL = "$:/temp/rimir/outline/selection/",
		KEYS = {z: 90, y: 89, up: 38, down: 40, left: 37, right: 39, tab: 9, escape: 27, enter: 13, del: 46};

	// Shortcut config (shadows of the plugin) copied into each test wiki
	function shortcutTiddlers() {
		return $tw.wiki.filterTiddlers("[all[shadows+tiddlers]prefix[$:/config/shortcuts/outline-]] " +
			"[all[shadows+tiddlers]tag[$:/tags/rimir/outline/BlockType]prefix[$:/plugins/rimir/outline/]] [[$:/tags/rimir/outline/BlockType]]").map(function(title) {
			return $tw.wiki.getTiddler(title).fields;
		});
	}

	function makeWiki(tiddlers) {
		var wiki = new $tw.Wiki();
		wiki.addTiddlers(shortcutTiddlers().concat(tiddlers || []));
		wiki.addIndexersToWiki();
		return wiki;
	}

	function findWidget(widget, type) {
		if(widget.parseTreeNode && widget.parseTreeNode.type === type) {
			return widget;
		}
		for(var i = 0; i < (widget.children || []).length; i++) {
			var found = findWidget(widget.children[i], type);
			if(found) {
				return found;
			}
		}
		return null;
	}

	function renderOutline(wiki, title) {
		var parser = wiki.parseText("text/vnd.tiddlywiki",
				"<$outline tiddler=\"" + title + "\"><$transclude $tiddler=\"" + title + "\" $mode=\"block\"/></$outline>",
				{parseAsInline: false}),
			root = wiki.makeWidget(parser, {document: $tw.fakeDocument}),
			container = $tw.fakeDocument.createElement("div");
		root.render(container, null);
		var r = {root: root, widget: findWidget(root, "outline"), wiki: wiki, title: title};
		r.widget.wake();
		// Re-render like the browser does after a change event
		r.refresh = function() {
			var changes = {};
			changes[title] = {modified: true};
			changes[SEL + title] = {modified: true};
			root.refresh(changes);
		};
		return r;
	}

	function key(r, keyCode, mods) {
		mods = mods || {};
		var ev = {
			keyCode: keyCode,
			key: mods.key,
			shiftKey: !!mods.shift, altKey: !!mods.alt, ctrlKey: !!mods.ctrl, metaKey: false,
			target: mods.target || r.widget.domNode,
			defaultPrevented: !!mods.defaultPrevented,
			prevented: false,
			stopped: false,
			preventDefault: function() { this.prevented = true; },
			stopPropagation: function() { this.stopped = true; }
		};
		r.widget.handleKeydown(ev);
		return ev;
	}

	function hasClass(el, cls) {
		return (el.attributes["class"] || "").split(" ").indexOf(cls) !== -1;
	}

	function selectedUnit(r) {
		var id = r.widget.selectedId;
		return id === -1 ? null : r.widget.units[id].unit;
	}

	function selectedSource(r) {
		var u = selectedUnit(r);
		return u ? r.widget.model.text.substring(u.start, u.end) : null;
	}

	function idOf(r, source) {
		var m = r.widget.model;
		for(var i = 0; i < m.units.length; i++) {
			if(m.text.substring(m.units[i].start, m.units[i].end) === source) {
				return i;
			}
		}
		return -1;
	}

	it("ships configurable default keys", function() {
		var wiki = makeWiki(),
			expected = {
				"outline-up": "Up", "outline-down": "Down", "outline-move-up": "alt-Up", "outline-move-down": "alt-Down",
				"outline-indent": "Tab", "outline-promote": "shift-Tab", "outline-edit": "Enter", "outline-menu": "alt-Enter", "outline-add": "ctrl-Enter",
				"outline-parent": "Left", "outline-child": "Right", "outline-up-deep": "ctrl-Up", "outline-down-deep": "ctrl-Down", "outline-edit-up": "ctrl-Up", "outline-edit-down": "ctrl-Down",
				"outline-open": "shift-Enter", "outline-clear": "Escape", "outline-save": "ctrl-Enter",
				"outline-continue": "Enter", "outline-newline": "shift-Enter", "outline-cancel": "Escape",
				"outline-help": "shift-slash", "outline-delete": "Delete", "outline-merge": "Backspace", "outline-merge-next": "Delete",
				"outline-undo": "ctrl-Z", "outline-redo": "ctrl-Y ctrl-shift-Z"
			};
		Object.keys(expected).forEach(function(name) {
			expect(name + "=" + wiki.getTiddlerText("$:/config/shortcuts/" + name)).toBe(name + "=" + expected[name]);
			expect($tw.wiki.getTiddlerText("$:/config/ShortcutInfo/" + name)).toBeTruthy();
		});
		var up = $tw.keyboardManager.parseKeyDescriptors("((outline-move-up))", {wiki: wiki});
		expect(up[0].keyCode).toBe(38);
		expect(up[0].altKey).toBe(true);
	});

	it("every shortcut is in exactly one key group, every group key is a shortcut", function() {
		var names = $tw.wiki.filterTiddlers("[all[shadows+tiddlers]removeprefix[$:/config/shortcuts/]prefix[outline-]]").sort(),
			grouped = [];
		$tw.wiki.getTiddlerList("$:/plugins/rimir/outline/key-groups").forEach(function(group) {
			expect($tw.wiki.getTiddler(group)).withContext(group).toBeTruthy();
			grouped = grouped.concat($tw.wiki.getTiddlerList(group));
		});
		expect(grouped.slice().sort()).toEqual(names);
	});

	it("? (any layout) and the help key toggle the key overview; Escape closes it before clearing", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "* a\n* b"}]), "T"),
			HELP = "$:/temp/rimir/outline/help/T";
		// Nothing selected: the overview still opens
		var ev = key(r, 219, {shift: true, key: "?"});
		expect(ev.prevented).toBe(true);
		expect(r.wiki.getTiddlerText(HELP)).toBe("yes");
		key(r, 191, {shift: true, key: "?"});
		expect(r.wiki.tiddlerExists(HELP)).toBe(false);
		// The configured key (shift-slash), whatever character it types
		key(r, 191, {shift: true, key: "_"});
		expect(r.wiki.getTiddlerText(HELP)).toBe("yes");
		// Ctrl-? is not the typed character
		expect(key(r, 219, {ctrl: true, key: "?"}).prevented).toBe(false);
		r.widget.select(0);
		ev = key(r, KEYS.escape);
		expect(ev.prevented).toBe(true);
		expect(r.wiki.tiddlerExists(HELP)).toBe(false);
		expect(r.widget.selectedId).toBe(0);
		key(r, KEYS.escape);
		expect(r.widget.selectedId).toBe(-1);
	});

	it("the key overview shows every group and the current keys", function() {
		var html = $tw.wiki.renderTiddler("text/html", "$:/plugins/rimir/outline/ui/keys-table");
		$tw.wiki.getTiddlerList("$:/plugins/rimir/outline/key-groups").forEach(function(group) {
			expect(html).toContain($tw.wiki.getTiddler(group).fields.caption);
		});
		expect(html).toContain("<kbd>alt-Up</kbd>");
		expect(html).toContain("Select the parent unit");
		expect(html).not.toContain("Outline:");
		// Fixed block menu keys
		expect(html).toContain("<kbd>Home</kbd>");
		// A changed key shows at once
		$tw.wiki.addTiddler({title: "$:/config/shortcuts/outline-move-up", text: "ctrl-shift-K"});
		try {
			expect($tw.wiki.renderTiddler("text/html", "$:/plugins/rimir/outline/ui/keys-table")).toContain("<kbd>ctrl-shift-K</kbd>");
		} finally {
			$tw.wiki.deleteTiddler("$:/config/shortcuts/outline-move-up");
		}
	});

	it("the settings tab has a shortcut editor row for every outline key", function() {
		var html = $tw.wiki.renderTiddler("text/html", "$:/plugins/rimir/outline/settings");
		$tw.wiki.filterTiddlers("[all[shadows+tiddlers]removeprefix[$:/config/shortcuts/]prefix[outline-]]").forEach(function(name) {
			expect(html).withContext(name).toContain("<strong>" + name + "</strong>");
		});
	});

	it("delete asks first: yes deletes with the subtree, Escape and cancel keep it", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "* a\n* b\n** b1\n* c"}]), "T");
		r.widget.select(r.widget.units.filter(function(e) { return e.unit.kind === "item"; })[1].unit.id);
		expect(key(r, KEYS.del).prevented).toBe(true);
		expect(r.widget.menu.entries.map(function(e) { return e.action; })).toEqual(["delete", "cancel"]);
		expect(r.widget.menu.active).toBe(0);
		key(r, KEYS.escape);
		expect(r.widget.menu).toBe(null);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* b\n** b1\n* c");
		key(r, KEYS.del);
		key(r, KEYS.down);
		key(r, KEYS.enter);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* b\n** b1\n* c");
		key(r, KEYS.del);
		key(r, KEYS.enter);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* c");
	});

	it("delete on a heading with a section offers just the heading", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "! A\n\nx\n\n! B\n\ny"}]), "T");
		r.widget.select(0);
		key(r, KEYS.del);
		expect(r.widget.menu.entries.map(function(e) { return e.action + ":" + (e.arg || ""); })).toEqual(["delete:", "delete:own", "cancel:"]);
		key(r, KEYS.down);
		key(r, KEYS.enter);
		expect(r.wiki.getTiddlerText("T")).toBe("x\n\n! B\n\ny");
	});

	it("quick delete of childless list items is a setting; read-only deletes nothing", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "* a\n** a1\n* b\n* c"},
			{title: "$:/config/rimir/outline/quick-delete-items", text: "yes"}]), "T"),
			items = function() { return r.widget.units.filter(function(e) { return e.unit.kind === "item"; }); };
		r.widget.select(items()[2].unit.id);
		key(r, KEYS.del);
		expect(r.widget.menu).toBe(null);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n** a1\n* c");
		// With children it still asks
		r.refresh();
		r.widget.select(items()[0].unit.id);
		key(r, KEYS.del);
		expect(r.widget.menu).not.toBe(null);
		key(r, KEYS.escape);
		r.wiki.addTiddler({title: "$:/status/IsReadOnly", text: "yes"});
		r.widget.select(items()[1].unit.id);
		expect(key(r, KEYS.del).prevented).toBe(true);
		expect(r.widget.menu).toBe(null);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n** a1\n* c");
	});

	it("undo and redo the outline's own changes, with the selection", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "* a\n* b\n** b1\n* c"}]), "T"),
			items = function() { return r.widget.units.filter(function(e) { return e.unit.kind === "item"; }); };
		r.widget.select(items()[1].unit.id);
		key(r, KEYS.del);
		key(r, KEYS.enter);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* c");
		r.refresh();
		key(r, KEYS.down, {alt: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* c");
		r.widget.select(items()[1].unit.id);
		key(r, KEYS.up, {alt: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* c\n* a");
		r.refresh();
		expect(key(r, KEYS.z, {ctrl: true}).prevented).toBe(true);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* c");
		r.refresh();
		key(r, KEYS.z, {ctrl: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* b\n** b1\n* c");
		r.refresh();
		expect(selectedSource(r)).toBe("* b");
		// Nothing left to undo: the key is consumed, nothing changes
		expect(key(r, KEYS.z, {ctrl: true}).prevented).toBe(true);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* b\n** b1\n* c");
		key(r, KEYS.y, {ctrl: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n* c");
		r.refresh();
		key(r, KEYS.z, {ctrl: true, shift: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* c\n* a");
		r.refresh();
		// A new change empties the redo list
		key(r, KEYS.z, {ctrl: true});
		r.refresh();
		r.widget.select(items()[1].unit.id);
		key(r, KEYS.tab);
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n** c");
		key(r, KEYS.y, {ctrl: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* a\n** c");
	});

	it("undo drops a history that no longer fits, keeps the depth, does nothing read-only", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "* a\n* b\n* c"},
			{title: "$:/config/rimir/outline/undo-depth", text: "2"}]), "T"),
			moveFirstDown = function() {
				r.refresh();
				r.widget.select(r.widget.units.filter(function(e) { return e.unit.kind === "item"; })[0].unit.id);
				key(r, KEYS.down, {alt: true});
			};
		moveFirstDown();
		moveFirstDown();
		moveFirstDown();
		expect(r.wiki.getTiddlerText("T")).toBe("* b\n* a\n* c");
		expect(JSON.parse(r.wiki.getTiddlerText("$:/temp/rimir/outline/undo/T")).undo.length).toBe(2);
		r.refresh();
		r.wiki.addTiddler({title: "$:/status/IsReadOnly", text: "yes"});
		key(r, KEYS.z, {ctrl: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* b\n* a\n* c");
		r.wiki.deleteTiddler("$:/status/IsReadOnly");
		// Changed outside the outline: nothing is written, the history is gone
		r.wiki.addTiddler(new $tw.Tiddler(r.wiki.getTiddler("T"), {text: "* b\n* a\n* c\n* d"}));
		r.refresh();
		key(r, KEYS.z, {ctrl: true});
		expect(r.wiki.getTiddlerText("T")).toBe("* b\n* a\n* c\n* d");
		expect(r.wiki.tiddlerExists("$:/temp/rimir/outline/undo/T")).toBe(false);
	});

	it("double-click edits the unit under the pointer, a transclusion its line", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "para\n\n{{X}}"}, {title: "X", text: "x"}]), "T"),
			node = r.widget.units[1].domNodes[0];
		r.widget.handleDblClick({target: node, preventDefault: function() {}});
		expect(r.widget.editor).not.toBe(null);
		expect(r.widget.editor.id).toBe(1);
		expect(r.wiki.getTiddlerText("$:/temp/rimir/outline/edit/T")).toBe("{{X}}");
	});

	it("select marks the unit and saves the selection", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "* a\n* b"}]), "T");
		expect(r.widget.select(2)).toBe(true);
		expect(r.widget.selectedId).toBe(2);
		expect(hasClass(r.widget.units[2].domNodes[0], "rr-ol-selected")).toBe(true);
		var state = r.wiki.getTiddler(SEL + "T");
		expect(state.fields.start).toBe("4");
		expect(state.fields.index).toBe("2");
		r.widget.select(1);
		expect(hasClass(r.widget.units[2].domNodes[0], "rr-ol-selected")).toBe(false);
		expect(hasClass(r.widget.units[1].domNodes[0], "rr-ol-selected")).toBe(true);
	});

	it("arrows move in document order and skip units without DOM nodes", function() {
		var r = renderOutline(makeWiki([
			{title: "T", text: "* a\n\n<$list filter=\"x\">\n\n<$text text=\"t\"/>\n\n</$list>\n\npara"}
		]), "T");
		var listWidget = r.widget.units[2];
		expect(listWidget.unit.kind).toBe("widget");
		expect(listWidget.domNodes.length).toBe(0);
		// Down without a selection selects the first unit
		var ev = key(r, KEYS.down);
		expect(ev.prevented).toBe(true);
		expect(ev.stopped).toBe(true);
		expect(r.widget.selectedId).toBe(0);
		// Ctrl-Down: every unit, into the list
		key(r, KEYS.down, {ctrl: true});
		expect(r.widget.selectedId).toBe(1);
		key(r, KEYS.down);
		expect(selectedSource(r)).toBe("para");
		key(r, KEYS.down);
		expect(selectedSource(r)).toBe("para");
		key(r, KEYS.up, {ctrl: true});
		expect(r.widget.selectedId).toBe(1);
		r.widget.select(2);
		expect(r.widget.selectedId).toBe(1);
	});

	it("up/down treat a whole list as one block; ctrl-up/down step through its items", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "! H\n\n* a\n** a1\n* b\n\npara\n\n# n\n\nend"}]), "T");
		function sel() { var u = selectedUnit(r); return u.kind === "list" ? "list:" + r.widget.model.text.substring(u.start, u.start + 1) : selectedSource(r); }
		r.widget.select(idOf(r, "! H"));
		key(r, KEYS.down);
		expect(sel()).toBe("list:*");
		// Down from the whole list: the block after it
		key(r, KEYS.down);
		expect(sel()).toBe("para");
		// Up from below: the whole list, then the block above it
		key(r, KEYS.up);
		expect(sel()).toBe("list:*");
		key(r, KEYS.up);
		expect(sel()).toBe("! H");
		// Inside a list: item by item; Down from the last item leaves the list
		r.widget.select(idOf(r, "* a"));
		key(r, KEYS.down);
		expect(sel()).toBe("** a1");
		key(r, KEYS.down);
		expect(sel()).toBe("* b");
		key(r, KEYS.up);
		expect(sel()).toBe("** a1");
		r.widget.select(idOf(r, "* b"));
		key(r, KEYS.down);
		expect(sel()).toBe("para");
		// From a list straight to the next list: selected as a whole when coming from below
		r.widget.select(idOf(r, "end"));
		key(r, KEYS.up);
		expect(sel()).toBe("list:#");
		key(r, KEYS.up);
		expect(sel()).toBe("para");
		// Ctrl-Up from below a list: its last item; Ctrl-Down from the list: its first item
		key(r, KEYS.up, {ctrl: true});
		expect(sel()).toBe("* b");
		r.widget.select(idOf(r, "! H"));
		key(r, KEYS.down);
		key(r, KEYS.down, {ctrl: true});
		expect(sel()).toBe("* a");
	});

	it("left/right select the parent and the first child", function() {
		var r = renderOutline(makeWiki([{title: "T", text: "! H\n\n* a\n** a1\n*** a1x\n* b\n\npara\n\n!! S\n\ns1"}]), "T");
		r.widget.select(idOf(r, "*** a1x"));
		expect(key(r, KEYS.left).prevented).toBe(true);
		expect(selectedSource(r)).toBe("** a1");
		key(r, KEYS.left);
		expect(selectedSource(r)).toBe("* a");
		// A top-level item: the whole list, then the heading
		key(r, KEYS.left);
		expect(selectedUnit(r).kind).toBe("list");
		key(r, KEYS.left);
		expect(selectedSource(r)).toBe("! H");
		// At the top: stays, still consumed
		expect(key(r, KEYS.left).prevented).toBe(true);
		expect(selectedSource(r)).toBe("! H");
		// Right mirrors Left: the list, its first item, then down the items
		key(r, KEYS.right);
		expect(selectedUnit(r).kind).toBe("list");
		key(r, KEYS.right);
		expect(selectedSource(r)).toBe("* a");
		key(r, KEYS.right);
		expect(selectedSource(r)).toBe("** a1");
		key(r, KEYS.right);
		expect(selectedSource(r)).toBe("*** a1x");
		key(r, KEYS.right);
		expect(selectedSource(r)).toBe("*** a1x");
		// A paragraph in a section: Left is the heading
		r.widget.select(idOf(r, "s1"));
