			return r.widget.rangeIds().map(function(id) { return m.text.substring(m.units[id].start, m.units[id].end); });
		}
		function framed(r) {
			return r.widget.units.filter(function(e) {
				return e.domNodes.length && hasClass(e.domNodes[0], "rr-ol-selected");
